window.JLPT_N2_EXAMS = [{"id":"2025_12","displayName":"12/2025","sourceFile":"17.N2 12-2025 _260603.pdf","questions":[{"mondai":1,"q":1,"prompt":"この家の<u>柱</u>はしっかりしている。","options":["はしら","ゆか","かべ","たな"],"answer":1,"word_explain":"柱 (はしら): cột nhà, trụ","translation_vi":"Cột của ngôi nhà này rất chắc chắn."},{"mondai":1,"q":2,"prompt":"なかなか<u>討論</u>が終わらない。","options":["どうろん","ぎろん","とうろん","きろん"],"answer":3,"word_explain":"討論 (とうろん): thảo luận, tranh luận","translation_vi":"Cuộc thảo luận mãi mà không kết thúc."},{"mondai":1,"q":3,"prompt":"家具の色は白で<u>統一</u>した。","options":["とういつ","とういち","どういつ","どういち"],"answer":1,"word_explain":"統一 (とういつ): thống nhất, đồng bộ","translation_vi":"Tôi đã đồng bộ màu sắc của đồ nội thất bằng màu trắng."},{"mondai":1,"q":4,"prompt":"彼はいつも誰かと<u>争って</u>いる。","options":["たたかって","あらそって","きそって","ぶつかって"],"answer":2,"word_explain":"争う (あらそう): tranh cãi, tranh giành, xung đột","translation_vi":"Anh ấy lúc nào cũng tranh cãi với ai đó."},{"mondai":1,"q":5,"prompt":"この野菜はビタミンが<u>豊富</u>です。","options":["ほんふう","ほんふ","ほうふう","ほうふ"],"answer":4,"word_explain":"豊富 (ほうふ): phong phú, dồi dào","translation_vi":"Loại rau này rất giàu vitamin."},{"mondai":2,"q":6,"prompt":"「デジタルカメラ」を<u>りゃくして</u>「デジカメ」という。","options":["縮して","省して","略して","簡して"],"answer":3,"word_explain":"略して (りゃくして): viết tắt, gọi tắt","translation_vi":"\"Digital camera\" được gọi tắt là \"Dejikame\"."},{"mondai":2,"q":7,"prompt":"暑いので、日陰で<u>すずんだ</u>。","options":["快んだ","冷んだ","清んだ","涼んだ"],"answer":4,"word_explain":"涼む (すずむ): hóng mát, nghỉ mát","translation_vi":"Vì trời nóng nên tôi đã hóng mát ở bóng râm."},{"mondai":2,"q":8,"prompt":"来年からサービスを<u>かくじゅう</u>することになった。","options":["拡張","拡充","各充","各張"],"answer":2,"word_explain":"拡充 (かくじゅう): mở rộng và nâng cao, tăng cường","translation_vi":"Từ năm sau, dịch vụ sẽ được mở rộng và nâng cao."},{"mondai":2,"q":9,"prompt":"私はあの人たちに<u>すくわれました</u>。","options":["嫌われました","敬われました","疑われました","救われました"],"answer":4,"word_explain":"救われる (すくわれる): được cứu giúp","translation_vi":"Tôi đã được những người đó cứu giúp."},{"mondai":2,"q":10,"prompt":"犯人はすでに国外に逃亡した可能性が<u>のうこう</u>だ。","options":["濃厚","農厚","濃高","農高"],"answer":1,"word_explain":"濃厚 (のうこう): đậm đặc; (khả năng) rất cao, rõ rệt","translation_vi":"Khả năng hung thủ đã trốn ra nước ngoài là rất cao."},{"mondai":3,"q":11,"prompt":"9時(　　)の新幹線に乗るために、8時に家を出た。","options":["行","発","進","始"],"answer":2,"word_explain":"9時発 (くじはつ): khởi hành lúc 9 giờ","translation_vi":"Để kịp lên chuyến tàu Shinkansen khởi hành lúc 9 giờ, tôi đã ra khỏi nhà lúc 8 giờ."},{"mondai":3,"q":12,"prompt":"コンサートのチケットは、先着(　　)で買うことができます。","options":["列","番","序","順"],"answer":4,"word_explain":"先着順 (せんちゃくじゅん): theo thứ tự đến trước","translation_vi":"Vé buổi hòa nhạc có thể mua theo thứ tự người đến trước."},{"mondai":3,"q":13,"prompt":"(　　)予約の場合は、キャンセル料がかかりません。","options":["単","副","仮","中"],"answer":3,"word_explain":"仮予約 (かりよやく): đặt chỗ tạm thời","translation_vi":"Trường hợp đặt chỗ tạm thời thì sẽ không mất phí hủy."},{"mondai":4,"q":14,"prompt":"風邪の(　　)のために、栄養と睡眠を十分に取りましょう。","options":["自衛","予備","予防","守衛"],"answer":3,"word_explain":"予防 (よぼう): phòng ngừa, dự phòng","translation_vi":"Để phòng ngừa cảm cúm, hãy bổ sung đầy đủ dinh dưỡng và ngủ đủ giấc."},{"mondai":4,"q":15,"prompt":"昨日のコンサートでは(　　)に近い席に座れたので、演奏者の様子が良く見えた。","options":["ホール","ステージ","スペース","マーケット"],"answer":2,"word_explain":"ステージ: sân khấu","translation_vi":"Ở buổi hòa nhạc hôm qua, vì ngồi được ở ghế gần sân khấu nên tôi đã nhìn rõ được dáng vẻ của người biểu diễn."},{"mondai":4,"q":16,"prompt":"来週の発表内容を(　　)して、大事なところだけ短くまとめて話してください。","options":["要約","節約","減量","縮小"],"answer":1,"word_explain":"要約 (ようやく): tóm tắt","translation_vi":"Hãy tóm tắt nội dung thuyết trình tuần tới và chỉ trình bày ngắn gọn những điểm quan trọng."},{"mondai":4,"q":17,"prompt":"フライパンの油が回りに(　　)、キッチンが汚れた。","options":["飛び散って","飛び立って","飛び越えて","飛び上がって"],"answer":1,"word_explain":"飛び散る (とびちる): bắn tung tóe, văng ra xung quanh","translation_vi":"Dầu từ chảo rán bắn tung tóe ra xung quanh làm bẩn nhà bếp."},{"mondai":4,"q":18,"prompt":"私の娘は音に(　　)で、小さな音でも目を覚ましてしまう。","options":["詳細","器用","敏感","短気"],"answer":3,"word_explain":"敏感 (びんかん): nhạy cảm, thính","translation_vi":"Con gái tôi rất nhạy cảm với âm thanh nên chỉ một tiếng động nhỏ cũng tỉnh giấc."},{"mondai":4,"q":19,"prompt":"ユーキ教授の主張が正しいことを(　　)貴重な資料が見つかった。","options":["近づける","取り上げる","持ち上げる","裏づける"],"answer":4,"word_explain":"裏づける (うらづける): chứng minh, làm bằng chứng củng cố","translation_vi":"Đã tìm thấy tài liệu quý giá chứng minh rằng lập luận của giáo sư Yuki là đúng."},{"mondai":4,"q":20,"prompt":"今日は仕事で一日中歩き回ったので、(　　)疲れた。","options":["かさかさに","くたくたに","ぶくぶくに","ふさふさに"],"answer":2,"word_explain":"くたくたに: mệt rã rời, kiệt sức","translation_vi":"Hôm nay vì công việc phải đi bộ khắp nơi cả ngày nên tôi mệt rã rời."},{"mondai":5,"q":21,"prompt":"二人の意見は<u>一致して</u>いた。","options":["正しかった","同じだった","はっきりしていた","似ていた"],"answer":2,"word_explain":"一致する (いっちする) = 同じだ: nhất trí, giống nhau, trùng khớp","translation_vi":"Ý kiến của hai người đã trùng khớp với nhau."},{"mondai":5,"q":22,"prompt":"この作品の<u>題</u>はとても印象的だ。","options":["デザイン","アイデア","ストーリー","タイトル"],"answer":4,"word_explain":"題 (だい) = タイトル: tiêu đề, nhan đề","translation_vi":"Tiêu đề của tác phẩm này rất ấn tượng."},{"mondai":5,"q":23,"prompt":"この辺りはいつも<u>そうぞうしい</u>。","options":["暗い","静かだ","明るい","うるさい"],"answer":4,"word_explain":"そうぞうしい (騒々しい) = うるさい: ồn ào, huyên náo","translation_vi":"Khu vực này lúc nào cũng ồn ào."},{"mondai":5,"q":24,"prompt":"私はいつもより<u>用心</u>した。","options":["注意","努力","準備","集中"],"answer":1,"word_explain":"用心 (ようじん) = 注意: cảnh giác, cẩn thận, chú ý","translation_vi":"Tôi đã cẩn thận hơn bình thường."},{"mondai":5,"q":25,"prompt":"このシャツは私には<u>ぶかぶかだ</u>。","options":["派手すぎる","小さすぎる","大きすぎる","地味すぎる"],"answer":3,"word_explain":"ぶかぶかだ = 大きすぎる: rộng thùng thình, quá rộng/quá lớn","translation_vi":"Chiếc áo sơ mi này đối với tôi thì rộng thùng thình."},{"mondai":6,"q":26,"prompt":"休憩","options":["仕事の途中だったが、少し疲れたので<u>休憩</u>を取った。","今週は日曜日に仕事がありますが、月曜日は<u>休憩</u>です。","夏の<u>休憩</u>を使って、家族と海外旅行に行きました。","手術のため、病院で1週間、<u>休憩</u>をすることになった。"],"answer":1,"word_explain":"休憩 (きゅうけい): nghỉ giải lao (trong lúc làm việc/học tập, thường dùng với ～を取る/～する)","translation_vi":"Dù đang làm dở việc nhưng vì hơi mệt nên tôi đã nghỉ giải lao."},{"mondai":6,"q":27,"prompt":"進める","options":["一度試合に勝って自信を<u>進めれば</u>、チームの成績は必ずよくなるだろう。","朝にトレーニングを行うことで、運動の効果を<u>進める</u>ことができるそうです。","市では現在、防災対策として、道路整備の検討を<u>進めて</u>います。","ユーキさんが仕事で同じ失敗を繰り返すのは、その失敗の反省を<u>進めていない</u>からだ。"],"answer":3,"word_explain":"進める (すすめる): xúc tiến, tiến hành (kế hoạch, công việc, việc xem xét 検討を進める)","translation_vi":"Thành phố hiện đang tiến hành xem xét việc chỉnh trang đường sá như một biện pháp phòng chống thiên tai."},{"mondai":6,"q":28,"prompt":"貢献","options":["高校時代の先生の一言が、私の人生に大きく<u>貢献</u>した。","この薬は、痛みを抑えるのに大きく<u>貢献</u>するのでよく売れるらしい。","鈴木氏が長い間行ってきた活動は、地域の安全に大きく<u>貢献</u>した。","海外での経験が就職に大きく<u>貢献</u>し、希望の会社に入社できた。"],"answer":3,"word_explain":"貢献 (こうけん): cống hiến, đóng góp (cho xã hội, địa phương, tổ chức, sự phát triển...)","translation_vi":"Hoạt động mà ông Suzuki đã thực hiện trong thời gian dài đã đóng góp rất lớn cho sự an toàn của địa phương."},{"mondai":6,"q":29,"prompt":"早急","options":["原さんは素質があるので、<u>早急</u>に強くなって、試合にも勝てるだろう。","薬がよく効いたようで、痛みは<u>早急</u>に治まった。","二つの液体を混ぜると、<u>早急</u>に反応して気体が発生する。","この問題については<u>早急</u>に対策を検討する必要がある。"],"answer":4,"word_explain":"早急 (さっきゅう / そうきゅう): khẩn cấp, gấp rút, nhanh chóng (dùng cho việc xử lý, đối ứng, giải quyết vấn đề)","translation_vi":"Đối với vấn đề này, cần phải khẩn trương xem xét biện pháp đối phó."},{"mondai":6,"q":30,"prompt":"区切り","options":["雨が降っている間、<u>区切り</u>がついていた試合が、やっと再開された。","この仕事は今日中には終わりそうもないので、<u>区切り</u>をつけて帰ります。","今が成功か失敗かの<u>区切り</u>なので、諦めずに頑張りましょう。","次のバスまで<u>区切り</u>が2時間あるので、食事をしながら待つことにした。"],"answer":2,"word_explain":"区切り (くぎり): dấu mốc, điểm ngắt quãng; 区切りをつける = tạm dừng ở một chặng/mốc hợp lý","translation_vi":"Công việc này có vẻ không thể xong trong hôm nay nên tôi sẽ làm đến một mốc hợp lý rồi về."}]},{"id":"2025_07","displayName":"07/2025","sourceFile":"De thi JLPT N2  thang 7 2025.pdf","questions":[{"mondai":1,"q":1,"prompt":"<u>辛い</u>食べ物は好きではありません。","options":["あまい","からい","にがい","しぶい"],"answer":2,"word_explain":"辛い (からい): cay","translation_vi":"Tôi không thích đồ ăn cay."},{"mondai":1,"q":2,"prompt":"私の友人は<u>刑事</u>です。","options":["けんじ","かんじ","けいじ","かいじ"],"answer":3,"word_explain":"刑事 (けいじ): cảnh sát hình sự","translation_vi":"Bạn của tôi là cảnh sát hình sự."},{"mondai":1,"q":3,"prompt":"素晴らしい<u>才能</u>を発揮した。","options":["ぜいのう","ざいのう","せいのう","さいのう"],"answer":4,"word_explain":"才能 (さいのう): tài năng","translation_vi":"Đã phát huy tài năng tuyệt vời."},{"mondai":1,"q":4,"prompt":"夕方になって、ようやく風が<u>収まった</u>","options":["さだまった","しずまった","おさまった","やすまった"],"answer":3,"word_explain":"収まった (おさまった): dịu xuống, lắng xuống","translation_vi":"Đến chiều tối, cuối cùng gió cũng đã dịu xuống."},{"mondai":1,"q":5,"prompt":"毎朝6時に<u>起床</u>して、少し運動をしている。","options":["きしょう","ぎしょう","きしょ","ぎしょ"],"answer":1,"word_explain":"起床 (きしょう): thức dậy, rời giường","translation_vi":"Mỗi sáng tôi thức dậy lúc 6 giờ và tập thể dục một chút."},{"mondai":2,"q":6,"prompt":"この時期は風邪をひく人が増える<u>けいこう</u>がある。","options":["傾向","頃向","傾高","頃高"],"answer":1,"word_explain":"傾向 (けいこう): xu hướng, khuynh hướng","translation_vi":"Vào thời điểm này có xu hướng gia tăng số người bị cảm lạnh."},{"mondai":2,"q":7,"prompt":"このタオルはまだ<u>しめって</u>いる。","options":["渡って","温って","汗って","湿って"],"answer":4,"word_explain":"湿って (しめって): ẩm ướt (từ 湿る)","translation_vi":"Chiếc khăn này vẫn còn ẩm."},{"mondai":2,"q":8,"prompt":"もう少し力に入れて<u>けずって</u>ください。","options":["絞って","削って","握って","掘って"],"answer":2,"word_explain":"削って (けずって): gọt, bào, vót (từ 削る)","translation_vi":"Hãy dồn thêm chút lực rồi gọt đi."},{"mondai":2,"q":9,"prompt":"この<u>しせつ</u>には、駐車場はありません。","options":["支接","施接","支設","施設"],"answer":4,"word_explain":"施設 (しせつ): cơ sở vật chất, công trình","translation_vi":"Cơ sở này không có bãi đỗ xe."},{"mondai":2,"q":10,"prompt":"大勢の人が<u>しさつ</u>に訪れた。","options":["診察","視祭","視察","診祭"],"answer":3,"word_explain":"視察 (しさつ): thị sát, tham quan khảo sát","translation_vi":"Rất nhiều người đã đến thị sát."},{"mondai":3,"q":11,"prompt":"この魚は骨が多くて食べ(　　)。","options":["づらい","いたい","おそい","ぐるしい"],"answer":1,"word_explain":"食べづらい (たべづらい): khó ăn","translation_vi":"Con cá này nhiều xương nên khó ăn."},{"mondai":3,"q":12,"prompt":"今回の事故は(　　)条件が重なって起きた。","options":["損","劣","危","悪"],"answer":4,"word_explain":"悪条件 (あくじょうけん): điều kiện xấu, bất lợi","translation_vi":"Vụ tai nạn lần này xảy ra do nhiều điều kiện bất lợi chồng chất lên nhau."},{"mondai":3,"q":13,"prompt":"教師たちの間で、新たな教育(　　)が注目されている。","options":["則","理","論","規"],"answer":3,"word_explain":"教育論 (きょういくろん): lý luận giáo dục, quan điểm giáo dục","translation_vi":"Trong giới giáo viên, một lý luận giáo dục mới đang thu hút sự chú ý."},{"mondai":4,"q":14,"prompt":"息子はみんなの前で、悪いことはもう絶対にしないと(　　)。","options":["論じた","命じた","誓った","迫った"],"answer":3,"word_explain":"誓った (ちかった): thề, cam kết (từ 誓う)","translation_vi":"Con trai tôi đã thề trước mặt mọi người rằng tuyệt đối sẽ không làm điều xấu nữa."},{"mondai":4,"q":15,"prompt":"工事のため、(　　)電気が止まることがあります。","options":["簡潔に","一時的に","手軽に","不完全に"],"answer":2,"word_explain":"一時的に (いちじてきに): tạm thời","translation_vi":"Do thi công nên điện có thể bị ngắt tạm thời."},{"mondai":4,"q":16,"prompt":"あの人物が今回の事件に(　　)していたのは間違いない。","options":["参列","加入","登場","関与"],"answer":4,"word_explain":"関与 (かんよ): liên quan, dính líu, tham gia vào","translation_vi":"Chắc chắn nhân vật đó đã có liên quan đến vụ việc lần này."},{"mondai":4,"q":17,"prompt":"油で汚れたフライパンは、(　　)してとても洗いにくいです。","options":["べたべた","かさかさ","じめじめ","ちくちく"],"answer":1,"word_explain":"べたべた: bết dính, nhớp nháp (dầu mỡ)","translation_vi":"Cái chảo dính đầy dầu mỡ bị nhờn rít nên rất khó rửa."},{"mondai":4,"q":18,"prompt":"サッカーで手を使うのは禁止されていて、もし使ったら(　　)になる。","options":["反則","違法","非常識","不都合"],"answer":1,"word_explain":"反則 (はんそく): phạm luật, phạm quy (trong thể thao)","translation_vi":"Trong bóng đá việc dùng tay bị cấm, nếu dùng thì sẽ bị tính là phạm luật."},{"mondai":4,"q":19,"prompt":"虫が飛んできたので、手に持っていた帽子を振って遠くに(　　)。","options":["連れ出した","締め出した","取り払った","追い払った"],"answer":4,"word_explain":"追い払った (おいはらった): xua đuổi đi (từ 追い払う)","translation_vi":"Vì có con côn trùng bay tới nên tôi vung chiếc mũ đang cầm trên tay để xua nó đi xa."},{"mondai":4,"q":20,"prompt":"社会の変化に合わせて、働き方や休日の過ごし方など人々が選ぶ生活の(　　)も変わってきた。","options":["ポーズ","スタイル","ブランド","シリーズ"],"answer":2,"word_explain":"スタイル: phong cách, kiểu cách (生活のスタイル: phong cách sống)","translation_vi":"Cùng với sự thay đổi của xã hội, phong cách sống mà mọi người lựa chọn như cách làm việc hay cách trải qua ngày nghỉ cũng đã thay đổi."},{"mondai":5,"q":21,"prompt":"昨夜、家の近くで<u>妙な</u>事件が起こった。","options":["恐ろしい","不思議な","悲しい","重大な"],"answer":2,"word_explain":"妙な (みょうな) = 不思議な: kỳ lạ, kỳ quặc","translation_vi":"Đêm qua, một vụ việc kỳ lạ đã xảy ra gần nhà tôi."},{"mondai":5,"q":22,"prompt":"鈴木さんは<u>相当</u>迷っているらしい。","options":["いろいろ","まだ","やっぱり","かなり"],"answer":4,"word_explain":"相当 (そうとう) = かなり: khá là, tương đối nhiều","translation_vi":"Nghe nói anh/chị Suzuki đang phân vân khá nhiều."},{"mondai":5,"q":23,"prompt":"教室が<u>やかましくて</u>、勉強に集中できない。","options":["うるさくて","汚くて","暑くて","暗て"],"answer":1,"word_explain":"やかましくて (喧しくて) = うるさくて: ồn ào, ầm ĩ","translation_vi":"Lớp học ồn ào quá nên không thể tập trung học được."},{"mondai":5,"q":24,"prompt":"中山さんは<u>帰省</u>しています。","options":["出張から戻って","部屋に戻って","ふるさとに戻って","休暇から戻って"],"answer":3,"word_explain":"帰省 (きせい) = ふるさとに戻って: về quê","translation_vi":"Anh/chị Nakayama đang về quê."},{"mondai":5,"q":25,"prompt":"林さんは、<u>いきなり</u>振り向いた。","options":["やっと","一度","突然","ゆっくり"],"answer":3,"word_explain":"いきなり = 突然: đột nhiên, bất ngờ","translation_vi":"Anh/chị Hayashi đột nhiên quay đầu nhìn lại."},{"mondai":6,"q":26,"prompt":"潰す","options":["ガラスのコップを落として、<u>潰して</u>しまった。","空き缶は、<u>潰して</u>からごみ箱に入れてください。","洗濯物が乾いたので、きれいに<u>潰して</u>たんすにしまった。","いらなくなった書類をひりひりと細かく<u>潰して</u>捨てた。"],"answer":2,"word_explain":"潰す (つぶす): làm bẹp, nghiền nát, ép dẹt (dùng đúng với lon rỗng, hộp giấy...)","translation_vi":"Vỏ lon rỗng hãy làm bẹp rồi mới bỏ vào thùng rác."},{"mondai":6,"q":27,"prompt":"粗末","options":["昔の学校給食は、おかずの種類も少なく、今と比べると<u>粗末</u>なものだった。","言葉遣いが<u>粗末</u>だったので、友達を怒らせてしまった。","風邪をひいてしまい、声が<u>粗末</u>で上手に歌えない。","お金がないので、友人がくれた古くて機能の<u>粗末</u>をパソコンを使っている。"],"answer":1,"word_explain":"粗末 (そまつ): đạm bạc, sơ sài, nghèo nàn (về đồ ăn, vật dụng...)","translation_vi":"Bữa ăn trưa ở trường ngày xưa có ít loại thức ăn kèm, so với bây giờ thì rất đạm bạc."},{"mondai":6,"q":28,"prompt":"熱中","options":["ごみ処理の問題に関して、市民から担当者に批判が<u>熱中</u>した。","学生のときは野球に<u>熱中</u>していて、毎日遅くまで練習していた。","うちの娘はこの服に<u>熱中</u>していて、毎日こればかり着たがりまま。","オリンピックの期間中、世界の関心が開催地に<u>熱中</u>している。"],"answer":2,"word_explain":"熱中 (ねっちゅう): say mê, miệt mài, đắm chìm vào (～に熱中する: say mê hoạt động/sở thích gì đó)","translation_vi":"Hồi còn là học sinh tôi rất say mê bóng chày, ngày nào cũng tập luyện đến khuya."},{"mondai":6,"q":29,"prompt":"和やか","options":["火事や地震のときは、慌てずに<u>和やか</u>な行動を取ることが重要だ。","この地方は、一年中気候が<u>和やか</u>なので暮らしやすい。","この店のスープは、<u>和やか</u>な味で飲むとほっとする。","代表者同士の話し合いは、<u>和やか</u>な雰囲気で行われた。"],"answer":4,"word_explain":"和やか (なごやか): hòa nhã, ôn hòa, vui vẻ ấm cúng (thường đi với 雰囲気, 話し合い...)","translation_vi":"Cuộc trao đổi giữa các đại diện đã diễn ra trong bầu không khí ôn hòa, thân thiện."},{"mondai":6,"q":30,"prompt":"愛着","options":["いろいろな靴をはいてみたが、どれも<u>愛着</u>がなかったので置わなかった。","スーパーで、地元の人が<u>愛着</u>を入れて育てた野菜を買った。","この机はもう使っていないのだが、<u>愛着</u>があってなかなか捨てられない。","弟は教師になるという夢に<u>愛着</u>を持ち、教育学部に進学した。"],"answer":3,"word_explain":"愛着 (あいちゃく): sự gắn bó, quyến luyến (tình cảm gắn bó với đồ vật, nơi chốn đã dùng lâu)","translation_vi":"Cái bàn này tôi không dùng nữa nhưng vì có sự gắn bó nên mãi vẫn không nỡ vứt đi."}]},{"id":"2024_12","displayName":"12/2024","sourceFile":"Đề N2 12-2024 Bản hoàn chỉnh.pdf","questions":[{"mondai":1,"q":1,"prompt":"山本さんは<u>優秀</u>な社員だ。","options":["ゆしゅ","ゆうしゅ","ゆしゅう","ゆうしゅう"],"answer":4,"word_explain":"優秀 (ゆうしゅう): ưu tú, xuất sắc","translation_vi":"Anh/chị Yamamoto là một nhân viên ưu tú."},{"mondai":1,"q":2,"prompt":"そんなことを言われたら、私も<u>迷った</u>に違いない。","options":["あやまった","あせった","まよった","うたがった"],"answer":3,"word_explain":"迷った (まよった) [迷う]: phân vân, do dự, bối rối","translation_vi":"Nếu bị nói như vậy thì chắc chắn tôi cũng sẽ phân vân thôi."},{"mondai":1,"q":3,"prompt":"今から行うのは<u>背骨</u>を伸ばす体操です。","options":["せいこつ","せこつ","せいぼね","せぼね"],"answer":4,"word_explain":"背骨 (せぼね): xương sống, cột sống","translation_vi":"Bài tập thể dục sắp thực hiện bây giờ là bài tập giãn cột sống."},{"mondai":1,"q":4,"prompt":"すぐに<u>実践</u>できるとは思っていなかった。","options":["じっせん","じっけん","じつぜん","じつげん"],"answer":1,"word_explain":"実践 (じっせん): thực tiễn, thực hành","translation_vi":"Tôi đã không nghĩ là có thể thực hành ngay lập tức được."},{"mondai":1,"q":5,"prompt":"彼はコンサートで派手な<u>衣装</u>を着ていた。","options":["いそう","いしょう","いじょう","いぞう"],"answer":2,"word_explain":"衣装 (いしょう): trang phục, y phục","translation_vi":"Anh ấy đã mặc trang phục sặc sỡ ở buổi hòa nhạc."},{"mondai":2,"q":6,"prompt":"<u>けいび</u>をもっと厳しくしたほうがいい。","options":["警護","係備","警備","係護"],"answer":3,"word_explain":"警備 (けいび): cảnh bị, bảo vệ, canh gác","translation_vi":"Nên thắt chặt việc bảo vệ, canh gác hơn nữa."},{"mondai":2,"q":7,"prompt":"安全な場所に<u>ひなん</u>をしてください。","options":["被離","避離","被難","避難"],"answer":4,"word_explain":"避難 (ひなん): tị nạn, lánh nạn, sơ tán","translation_vi":"Hãy sơ tán đến nơi an toàn."},{"mondai":2,"q":8,"prompt":"先祖を<u>うやまう</u>心を大切にしたい。","options":["拝う","敬う","礼う","尊う"],"answer":2,"word_explain":"敬う (うやまう): kính trọng, tôn kính","translation_vi":"Tôi muốn trân trọng tấm lòng tôn kính tổ tiên."},{"mondai":2,"q":9,"prompt":"パソコン教室の<u>じゅこう</u>の申し込みをした。","options":["受講","授講","受校","授校"],"answer":1,"word_explain":"受講 (じゅこう): tham gia khóa học, theo học","translation_vi":"Tôi đã đăng ký theo học lớp học máy tính."},{"mondai":2,"q":10,"prompt":"あの人は本当に<u>あつかましい</u>人だ。","options":["圧かましい","厚かましい","熱かましい","暑かましい"],"answer":2,"word_explain":"厚かましい (あつかましい): trơ trẽn, mặt dày, không biết ngại","translation_vi":"Người đó thật sự là một người mặt dày, trơ trẽn."},{"mondai":3,"q":11,"prompt":"中村選手は日本を代表する(　　)選手だ。","options":["高","優","名","真"],"answer":3,"word_explain":"名選手 (めいせんしゅ): tuyển thủ xuất sắc, vận động viên danh tiếng","translation_vi":"Tuyển thủ Nakamura là một vận động viên xuất sắc đại diện cho Nhật Bản."},{"mondai":3,"q":12,"prompt":"今日は月が地球に(　　)接近する日なので、通常の満月より大きく見えます。","options":["特","最","極","激"],"answer":2,"word_explain":"最接近 (さいせっきん): tiếp cận gần nhất","translation_vi":"Hôm nay là ngày Mặt Trăng tiến lại gần Trái Đất nhất, nên trông nó lớn hơn trăng tròn bình thường."},{"mondai":3,"q":13,"prompt":"家のポストに私(　　)の手紙が入っていた。","options":["宛て","着き","届け","便り"],"answer":1,"word_explain":"私宛て (わたしあて): gửi cho tôi (〜宛て: gửi đến ai)","translation_vi":"Trong hòm thư của nhà có một lá thư gửi cho tôi."},{"mondai":4,"q":14,"prompt":"会員の登録が(　　)したので、今からサービスを利用できます。","options":["決着","完了","終業","到達"],"answer":2,"word_explain":"完了 (かんりょう): hoàn tất, hoàn thành","translation_vi":"Việc đăng ký hội viên đã hoàn tất, nên từ bây giờ bạn có thể sử dụng dịch vụ."},{"mondai":4,"q":15,"prompt":"年を取って運動をしなくなると、筋肉がだんだん(　　)いきます。","options":["潰れて","欠けて","尽きて","衰えて"],"answer":4,"word_explain":"衰えて (おとろえて) [衰える]: suy yếu đi, suy giảm","translation_vi":"Khi có tuổi và không còn vận động nữa thì cơ bắp sẽ dần suy yếu đi."},{"mondai":4,"q":16,"prompt":"会議時間が残り少なくなったので、資料の詳細な説明は(　　)して、要点のみを説明した。","options":["減量","休止","節約","省略"],"answer":4,"word_explain":"省略 (しょうりゃく): giản lược, lược bỏ","translation_vi":"Vì thời gian họp còn lại ít nên tôi đã lược bỏ phần giải thích chi tiết tài liệu và chỉ trình bày những điểm chính."},{"mondai":4,"q":17,"prompt":"この小説はフィクションだと(　　)いたが、実際にあった話らしい。","options":["思い込んで","思い起こして","考え抜いて","考えついて"],"answer":1,"word_explain":"思い込んで (おもいこんで) [思い込む]: đinh ninh, tin chắc","translation_vi":"Tôi đã đinh ninh cuốn tiểu thuyết này là hư cấu, nhưng hình như đó là câu chuyện có thật."},{"mondai":4,"q":18,"prompt":"山口さんは、子どもが怖がらないように優しい(　　)で話しかけた。","options":["音声","口調","顔色","内心"],"answer":2,"word_explain":"口調 (くちょう): giọng điệu, ngữ điệu","translation_vi":"Anh/chị Yamaguchi đã bắt chuyện bằng giọng điệu dịu dàng để đứa trẻ không bị sợ."},{"mondai":4,"q":19,"prompt":"部下に仕事を教えるのは、上司の(　　)の一つだ。","options":["労働","勤務","役目","当番"],"answer":3,"word_explain":"役目 (やくめ): nhiệm vụ, vai trò, bổn phận","translation_vi":"Việc hướng dẫn công việc cho cấp dưới là một trong những nhiệm vụ của cấp trên."},{"mondai":4,"q":20,"prompt":"森さんは外食のとき、いつも誰かに払ってもらおうとするので、(　　)人だと思う。","options":["みずみずしい","たどたどしい","ずうずうしい","よわよわしい"],"answer":3,"word_explain":"ずうずうしい: mặt dày, trơ trẽn, vô duyên","translation_vi":"Anh/chị Mori khi đi ăn ngoài lúc nào cũng định nhờ ai đó trả tiền hộ nên tôi nghĩ đó là người mặt dày."},{"mondai":5,"q":21,"prompt":"佐藤さんが<u>ガイド</u>してくれました。","options":["案内","解決","応援","準備"],"answer":1,"word_explain":"ガイド = 案内 (あんない): hướng dẫn, chỉ dẫn","translation_vi":"Anh/chị Sato đã hướng dẫn cho tôi."},{"mondai":5,"q":22,"prompt":"この表現は<u>修正</u>したほうがいいですよ。","options":["調べた","覚えた","直した","使った"],"answer":3,"word_explain":"修正 (しゅうせい) = 直した (なおした): chỉnh sửa, sửa lại","translation_vi":"Cách diễn đạt này bạn nên sửa lại thì hơn đấy."},{"mondai":5,"q":23,"prompt":"<u>徐々に</u>会社に慣れてきた。","options":["ずいぶん","いつのまにか","やっと","次第に"],"answer":4,"word_explain":"徐々に (じょじょに) = 次第に (しだいに): dần dần, từng chút một","translation_vi":"Tôi đã dần dần quen với công ty."},{"mondai":5,"q":24,"prompt":"青いペンキが<u>はげて</u>いる。","options":["取れて","ついて","乾いて","こぼれて"],"answer":1,"word_explain":"はげて [剥げる] = 取れて [取れる]: bong tróc ra, tróc sơn","translation_vi":"Lớp sơn màu xanh dương đang bị bong tróc."},{"mondai":5,"q":25,"prompt":"彼女のあの<u>しぐさ</u>は印象的だった。","options":["考え","動作","服装","言葉"],"answer":2,"word_explain":"しぐさ (仕草) = 動作 (どうさ): cử chỉ, điệu bộ, hành động","translation_vi":"Cử chỉ đó của cô ấy thật ấn tượng."},{"mondai":6,"q":26,"prompt":"薄める","options":["私には難しすぎたので、コースのレベルを<u>薄めた</u>。","部屋が暑かったので、エアコンをつけて温度を<u>薄めた</u>。","スープがしょっぱかったので、水を加えて味を<u>薄めた</u>。","うるさいと言われたので、テレビの音量を<u>薄めた</u>。"],"answer":3,"word_explain":"薄める (うすめる): pha loãng, làm nhạt đi (dùng cho vị, màu sắc, nồng độ, chất lỏng)","translation_vi":"Vì món súp bị mặn nên tôi đã cho thêm nước để làm nhạt vị đi."},{"mondai":6,"q":27,"prompt":"充実","options":["今日の午後は雨の予報で、空には雲が<u>充実</u>している。","今はやりがいのある仕事ができて、毎日が<u>充実</u>している。","喫茶店の中は、コーヒーのにおいが<u>充実</u>している。","計画を実行するためには、まだ問題が<u>充実</u>している。"],"answer":2,"word_explain":"充実 (じゅうじつ): sung túc, đầy đủ, viên mãn, phong phú (dùng cho cuộc sống, thời gian, nội dung, cơ sở vật chất)","translation_vi":"Hiện tại tôi được làm công việc đầy ý nghĩa nên mỗi ngày đều rất viên mãn."},{"mondai":6,"q":28,"prompt":"鮮明","options":["次回のセミナーの開催日はまだ<u>鮮明</u>に決まっていない。","できそうにない仕事は<u>鮮明</u>に断ったほうがいい。","B社の製品のほうが性能が<u>鮮明</u>に優れている。","あのときの出来事は今でも<u>鮮明</u>に覚えている。"],"answer":4,"word_explain":"鮮明 (せんめい): rõ nét, rõ ràng, sống động (dùng cho hình ảnh, màu sắc, ký ức)","translation_vi":"Sự việc lúc đó đến tận bây giờ tôi vẫn còn nhớ rõ mồn một."},{"mondai":6,"q":29,"prompt":"ふもと","options":["明日、駅の<u>ふもと</u>で池田さんと会う約束をした。","あのビルの<u>ふもと</u>に、新しいお店ができるらしい。","山の<u>ふもと</u>に車を止めて、そこから登りましょう。","ドアの<u>ふもと</u>に猫がいて、開けることができない。"],"answer":3,"word_explain":"ふもと (麓): chân núi (chỉ dùng cho núi, đồi)","translation_vi":"Hãy đỗ xe ở chân núi rồi từ đó leo lên nhé."},{"mondai":6,"q":30,"prompt":"定年","options":["私の会社は60歳が<u>定年</u>なので、あと半年で退職だ。","この乗り物は子ども向けのため、10歳が<u>定年</u>になっている。","この国では、<u>定年</u>の20歳になると選挙で投票することができる。","犬の<u>定年</u>は一般的に10歳から15歳の間だといわれている。"],"answer":1,"word_explain":"定年 (ていねん): tuổi nghỉ hưu theo quy định","translation_vi":"Công ty của tôi quy định 60 tuổi là tuổi nghỉ hưu, nên còn nửa năm nữa là tôi nghỉ việc."}]},{"id":"2024_07","displayName":"07/2024","sourceFile":"n2-7-2024.pdf","questions":[{"mondai":1,"q":1,"prompt":"状況を<u>詳細</u>に書いてください。","options":["そうざい","そうさい","しょうざい","しょうさい"],"answer":4,"word_explain":"詳細 (しょうさい): chi tiết, cặn kẽ","translation_vi":"Hãy viết chi tiết tình hình."},{"mondai":1,"q":2,"prompt":"<u>分析</u>には少し時間がかかります。","options":["ぶんせき","ぶんかい","ぶんせつ","ぶんかつ"],"answer":1,"word_explain":"分析 (ぶんせき): phân tích","translation_vi":"Việc phân tích sẽ mất một chút thời gian."},{"mondai":1,"q":3,"prompt":"髪の毛がくしに<u>絡まって</u>しまった。","options":["はさまって","からまって","つまって","たまって"],"answer":2,"word_explain":"絡まる (からまる): vướng vào, quấn vào, rối vào","translation_vi":"Tóc đã bị mắc rối vào lược mất rồi."},{"mondai":1,"q":4,"prompt":"ここでは<u>農薬</u>をまったく使わずに野菜を栽培している。","options":["のんやく","のうやく","のうらく","のんらく"],"answer":2,"word_explain":"農薬 (のうやく): thuốc trừ sâu, nông dược","translation_vi":"Ở đây người ta trồng rau hoàn toàn không sử dụng thuốc trừ sâu."},{"mondai":1,"q":5,"prompt":"とても<u>鮮やか</u>だったことを覚えています。","options":["おだやか","さわやか","あざやか","なごやか"],"answer":3,"word_explain":"鮮やか (あざやか): rực rỡ, tươi sáng, sắc nét","translation_vi":"Tôi nhớ rằng nó đã rất rực rỡ/tươi sáng."},{"mondai":2,"q":6,"prompt":"この会社を<u>しぼう</u>した理由を教えてください。","options":["希望","志望","指望","貴望"],"answer":2,"word_explain":"志望 (しぼう): nguyện vọng, mong muốn (vào trường/công ty)","translation_vi":"Hãy cho biết lý do bạn ứng tuyển (nguyện vọng vào) công ty này."},{"mondai":2,"q":7,"prompt":"あの作家の<u>たんぺん</u>小説はとても面白い。","options":["短編","単編","短遍","単遍"],"answer":1,"word_explain":"短編 (たんぺん): đoản thiên, truyện ngắn","translation_vi":"Tiểu thuyết ngắn của tác giả đó rất thú vị."},{"mondai":2,"q":8,"prompt":"桜の花が<u>ちって</u>いくのを眺める。","options":["消って","去って","散って","失って"],"answer":3,"word_explain":"散る (ちる): rụng, tàn, rơi lả tả (hoa)","translation_vi":"Ngắm nhìn những cánh hoa anh đào đang rơi rụng."},{"mondai":2,"q":9,"prompt":"このセーターにはとても<u>やわらかい</u>毛糸が使われている。","options":["伸らかい","軽らかい","暖らかい","柔らかい"],"answer":4,"word_explain":"柔らかい (やわらかい): mềm, mềm mại","translation_vi":"Chiếc áo len này được làm từ loại sợi len rất mềm mại."},{"mondai":2,"q":10,"prompt":"最近あまり体調がよくないのは、<u>ひろう</u>のせいだろう。","options":["疲労","病労","疲老","病老"],"answer":1,"word_explain":"疲労 (ひろう): mệt mỏi, kiệt sức","translation_vi":"Dạo gần đây sức khỏe không được tốt lắm chắc là do mệt mỏi đấy."},{"mondai":3,"q":11,"prompt":"しょうゆの(　　)原料は大豆です。","options":["主","要","正","本"],"answer":1,"word_explain":"主原料 (しゅげんりょう): nguyên liệu chính","translation_vi":"Nguyên liệu chính của nước tương là đậu nành."},{"mondai":3,"q":12,"prompt":"子どもたちの読書(　　)が進んでいるらしい。","options":["抜け","逃げ","別れ","離れ"],"answer":4,"word_explain":"読書離れ (どくしょばなれ): sự xa rời việc đọc sách, ít đọc sách đi","translation_vi":"Có vẻ như tình trạng trẻ em ngày càng xa rời việc đọc sách đang gia tăng."},{"mondai":3,"q":13,"prompt":"経営の方針については社長が決定(　　)を持っている。","options":["任","手","権","裁"],"answer":3,"word_explain":"決定権 (けっていけん): quyền quyết định","translation_vi":"Về phương châm kinh doanh thì giám đốc nắm quyền quyết định."},{"mondai":4,"q":14,"prompt":"両親はおいしい料理で客を(　　)のが好きだ。","options":["もてなす","おだてる","託す","救う"],"answer":1,"word_explain":"もてなす: tiếp đãi, chiêu đãi","translation_vi":"Bố mẹ tôi thích chiêu đãi khách bằng những món ăn ngon."},{"mondai":4,"q":15,"prompt":"その駅は各駅停車の電車は止まりますが、急行電車は(　　)します。","options":["経由","直進","通過","横断"],"answer":3,"word_explain":"通過 (つうか): đi qua, chạy thẳng qua không dừng","translation_vi":"Ở nhà ga đó tàu thường dừng, nhưng tàu tốc hành thì chạy thẳng qua (không dừng)."},{"mondai":4,"q":16,"prompt":"見た人の記憶に残るような(　　)のあるポスターにしたい。","options":["インパクト","プレッシャー","チャージ","ショック"],"answer":1,"word_explain":"インパクト: ấn tượng mạnh, tác động mạnh","translation_vi":"Tôi muốn làm một tấm áp phích có sức hút mạnh mẽ để đọng lại trong ký ức người xem."},{"mondai":4,"q":17,"prompt":"地元の選手がオリンピックでメダルを獲得したことがテレビで(　　)された。","options":["通信","普及","伝言","報道"],"answer":4,"word_explain":"報道 (ほうどう): đưa tin, tường thuật tin tức","translation_vi":"Việc vận động viên địa phương giành huy chương tại Olympic đã được đưa tin trên truyền hình."},{"mondai":4,"q":18,"prompt":"台風で電車が運休になり通勤や通学で利用する人に(　　)影響を与えた。","options":["大まかな","偉大な","大げさな","多大な"],"answer":4,"word_explain":"多大な (ただいな): to lớn, nhiều (ảnh hưởng, thiệt hại, công sức)","translation_vi":"Do bão nên tàu điện ngừng chạy, gây ảnh hưởng to lớn đến những người sử dụng để đi làm và đi học."},{"mondai":4,"q":19,"prompt":"西川さんは転校してきたばかりだが、友達もできて、もうすっかりクラスに(　　)いる。","options":["当てはまって","溶け込んで","結びついて","触れ合って"],"answer":2,"word_explain":"溶け込む (とけこむ): hòa nhập, hòa mình vào","translation_vi":"Bạn Nishikawa mới chuyển trường đến thôi nhưng đã kết bạn được và giờ đã hoàn toàn hòa nhập vào lớp rồi."},{"mondai":4,"q":20,"prompt":"私は(　　)性格なので、時々財布を持たずに買い物に出かけてしまうことがある。","options":["あつかましい","うっとうしい","そそっかしい","さわがしい"],"answer":3,"word_explain":"そそっかしい: hấp tấp, cẩu thả, hay quên trước quên sau","translation_vi":"Vì tôi có tính hay hấp tấp bất cẩn nên thỉnh thoảng lại đi mua sắm mà quên không mang ví."},{"mondai":5,"q":21,"prompt":"出張の日程は<u>おおよそ</u>決まりました。","options":["だいたい","すべて","やっと","もう"],"answer":1,"word_explain":"おおよそ = だいたい: đại khái, khoảng chừng","translation_vi":"Lịch trình chuyến công tác đã được quyết định đại khái rồi."},{"mondai":5,"q":22,"prompt":"彼女はとても<u>行儀</u>がいい。","options":["アイディア","サービス","マナー","イメージ"],"answer":3,"word_explain":"行儀 (ぎょうぎ) = マナー: phép tắc, tác phong, cách cư xử","translation_vi":"Cô ấy có phép tắc (cách cư xử) rất lịch sự."},{"mondai":5,"q":23,"prompt":"中西さんは、いつも<u>いばっている</u>。","options":["眠そうにして","偉そうにして","暇そうにして","嫌そうにして"],"answer":2,"word_explain":"威張る (いばる) = 偉そうにする: lên mặt, ra vẻ ta đây, kiêu ngạo","translation_vi":"Anh Nakanishi lúc nào cũng ra vẻ oai phong / kiêu ngạo."},{"mondai":5,"q":24,"prompt":"使わない物は、ここに<u>収納して</u>ください。","options":["並べて","捨てて","預けて","しまって"],"answer":4,"word_explain":"収納する (しゅうのうする) = しまう: cất giữ, sắp xếp vào chỗ cất","translation_vi":"Những đồ không dùng đến thì hãy cất vào đây."},{"mondai":5,"q":25,"prompt":"横山さんは<u>不平</u>を言うことが多い。","options":["冗談","文句","うそ","わがまま"],"answer":2,"word_explain":"不平 (ふへい) = 文句 (もんく): lời phàn nàn, bất bình","translation_vi":"Anh Yokoyama thường hay phàn nàn / kêu ca."},{"mondai":6,"q":26,"prompt":"共有","options":["市民ボランティアの<u>共有</u>で、留学生のスピーチコンテストが行われた。","大学と企業が<u>共有</u>で新しい技術の研究を行っている。","これらの事件には、発生場所に<u>共有</u>の特徴があることが分かった。","結婚してから購入した物は、夫婦の<u>共有</u>の財産になる。"],"answer":4,"word_explain":"共有 (きょうゆう): sở hữu chung, dùng chung (tài sản, thông tin, không gian...)","translation_vi":"Những đồ vật mua sau khi kết hôn sẽ trở thành tài sản chung của hai vợ chồng."},{"mondai":6,"q":27,"prompt":"鋭い","options":["動物たちが自然界で生きていくためには、<u>鋭い</u>感覚が必要だ","弟は記憶が<u>鋭く</u>て、本に載っているたくさんの国名や国旗をすぐに覚えた。","赤ちゃんの肌は<u>鋭い</u>から、少しの刺激で赤くなってしまう。","運動の能力が<u>鋭い</u>人は、どんなスポーツでもすぐに上達する。"],"answer":1,"word_explain":"鋭い (するどい): sắc bén, nhạy bén (giác quan, ánh mắt, đầu nhọn, nhận xét...)","translation_vi":"Để các loài động vật sinh tồn trong thế giới tự nhiên thì cần có giác quan nhạy bén."},{"mondai":6,"q":28,"prompt":"はきはき","options":["よく眠ったので、今日は頭が<u>はきはき</u>としている。","ビルの屋上から、遠くの山が<u>はきはき</u>と見える。","その学生は、聞かれたことに<u>はきはき</u>と答えた","ミスの原因を<u>はきはき</u>とさせるために、調査が行われた。"],"answer":3,"word_explain":"はきはき: nói năng/trả lời rành mạch, dõng dạc, lưu loát và dứt khoát","translation_vi":"Sinh viên đó đã trả lời một cách dõng dạc, rành mạch đối với những câu được hỏi."},{"mondai":6,"q":29,"prompt":"鑑賞","options":["学校の授業で、工場へ行って自動車を組み立てる様子を<u>鑑賞</u>した。","中学生のとき、市のコンサートホールでクラシック音楽を<u>鑑賞</u>した。","資料を読んで、自然を守るための国の活動について<u>鑑賞</u>した。","レストランで、素材の良さを生かした料理を舌でじっくり<u>鑑賞</u>した。"],"answer":2,"word_explain":"鑑賞 (かんしょう): thưởng thức (nghệ thuật, âm nhạc, phim ảnh, hội họa...)","translation_vi":"Hồi học cấp hai, tôi đã thưởng thức nhạc cổ điển tại nhà hát hòa nhạc của thành phố."},{"mondai":6,"q":30,"prompt":"着々","options":["ベランダが<u>着々</u>と古くなって危険なので、修理を決める","ゲームに夢中になっていたら、時間が<u>着々</u>とたっていた","来週のパーティーの準備は<u>着々</u>と進んでいるようだ。","夕方になって、外は<u>着々</u>と涼しくなってきている。"],"answer":3,"word_explain":"着々 (ちゃくちゃく): tuần tự, từng bước vững chắc theo đúng kế hoạch (thường đi với 進む)","translation_vi":"Có vẻ như công việc chuẩn bị cho bữa tiệc tuần tới đang tiến triển thuận lợi từng bước một."}]},{"id":"2023_12","displayName":"12/2023","sourceFile":"2023年12月N2.pdf","questions":[{"mondai":1,"q":1,"prompt":"昨日から<u>腕</u>が痛くて困っている。","options":["こし","うで","かた","ひざ"],"answer":2,"word_explain":"腕 (うで): cánh tay","translation_vi":"Từ hôm qua tôi bị đau cánh tay nên đang rất khổ sở."},{"mondai":1,"q":2,"prompt":"青木さんは<u>善良</u>な人です。","options":["せんりょう","ぜんりゅう","ぜんりょう","せんりゅう"],"answer":3,"word_explain":"善良 (ぜんりょう): lương thiện, hiền lành","translation_vi":"Anh/chị Aoki là người lương thiện."},{"mondai":1,"q":3,"prompt":"丸山さんは意外に<u>幼い</u>ところがある。","options":["おさない","するどい","かしこい","しつこい"],"answer":1,"word_explain":"幼い (おさない): non nớt, trẻ con, ngây thơ","translation_vi":"Anh/chị Maruyama không ngờ lại có nét trẻ con (ngây thơ)."},{"mondai":1,"q":4,"prompt":"古いデータを<u>削除</u>した。","options":["そくよ","さくよ","そくじょ","さくじょ"],"answer":4,"word_explain":"削除 (さくじょ): xóa bỏ, cắt bỏ","translation_vi":"Tôi đã xóa dữ liệu cũ."},{"mondai":1,"q":5,"prompt":"私たちは働く機会の<u>平等</u>を求めています。","options":["へいど","びょうどう","びょうど","へいどう"],"answer":2,"word_explain":"平等 (びょうどう): bình đẳng","translation_vi":"Chúng tôi đang đòi hỏi sự bình đẳng về cơ hội làm việc."},{"mondai":2,"q":6,"prompt":"お金の<u>かんり</u>は、きちんとしてください。","options":["管利","官理","管理","官利"],"answer":3,"word_explain":"管理 (かんり): quản lý","translation_vi":"Hãy quản lý tiền bạc một cách cẩn thận."},{"mondai":2,"q":7,"prompt":"今日から２週間の<u>けんしゅう</u>を行います。","options":["演習","研習","研修","演修"],"answer":3,"word_explain":"研修 (けんしゅう): đào tạo, tập huấn","translation_vi":"Từ hôm nay chúng tôi sẽ tổ chức khóa tập huấn trong 2 tuần."},{"mondai":2,"q":8,"prompt":"社会は<u>たえず</u>変化している。","options":["完えず","絶えず","停えず","滞えず"],"answer":2,"word_explain":"絶えず (たえず): không ngừng, liên tục","translation_vi":"Xã hội đang thay đổi không ngừng."},{"mondai":2,"q":9,"prompt":"選挙で誰に<u>とうひょう</u>するかまだ決めていない。","options":["投票","当票","投標","当標"],"answer":1,"word_explain":"投票 (とうひょう): bỏ phiếu, bầu cử","translation_vi":"Tôi vẫn chưa quyết định sẽ bỏ phiếu cho ai trong cuộc bầu cử."},{"mondai":2,"q":10,"prompt":"中島さんは何かを<u>かかえて</u>部屋に入ってきた。","options":["押えて","捕えて","握えて","抱えて"],"answer":4,"word_explain":"抱えて (かかえて): ôm (vào lòng/trong tay)","translation_vi":"Anh/chị Nakajima ôm thứ gì đó đi vào phòng."},{"mondai":3,"q":11,"prompt":"彼は兄に対抗(　　)を持っているようだ。","options":["心","欲","願","熱"],"answer":1,"word_explain":"対抗心 (たいこうしん): tâm lý cạnh tranh, lòng hiếu thắng","translation_vi":"Có vẻ như cậu ấy có tâm lý cạnh tranh với anh trai mình."},{"mondai":3,"q":12,"prompt":"引っ越しのための(　　)手続きをしなければならない。","options":["総","複","多","諸"],"answer":4,"word_explain":"諸手続き (しょてつづき): các thủ tục, nhiều thủ tục","translation_vi":"Tôi phải làm các thủ tục cho việc chuyển nhà."},{"mondai":3,"q":13,"prompt":"買い物をしている二人(　　)にインタビューをしました。","options":["出かけ","連れ","会い","集まり"],"answer":2,"word_explain":"二人連れ (ふたりづれ): cặp hai người đi cùng nhau","translation_vi":"Tôi đã phỏng vấn một cặp hai người đang đi mua sắm cùng nhau."},{"mondai":4,"q":14,"prompt":"このアニメは、登場人物がとてもかわいいと、若者の間で(　　)になっている。","options":["課題","題名","題材","話題"],"answer":4,"word_explain":"話題 (わだい): chủ đề bàn tán, đề tài nóng","translation_vi":"Bộ anime này đang trở thành đề tài bàn tán sôi nổi trong giới trẻ vì các nhân vật rất dễ thương."},{"mondai":4,"q":15,"prompt":"あのとき、友達に謝らなかったことをずっと(　　)している。","options":["同情","後悔","我慢","恐縮"],"answer":2,"word_explain":"後悔 (こうかい): hối hận","translation_vi":"Tôi luôn hối hận vì lúc đó đã không xin lỗi bạn mình."},{"mondai":4,"q":16,"prompt":"楽器の音量を確認するために、コンサートの前日に会場で(　　)をした。","options":["チャージ","アポイントメント","オリエンテーション","リハーサル"],"answer":4,"word_explain":"リハーサル: buổi tổng duyệt, diễn tập","translation_vi":"Để kiểm tra âm lượng của nhạc cụ, chúng tôi đã tổng duyệt tại hội trường vào ngày trước buổi hòa nhạc."},{"mondai":4,"q":17,"prompt":"この魚は、いつでもこの辺りの海にいるわけではなく、(　　)の時期にしかいない。","options":["特定","指定","固定","限定"],"answer":1,"word_explain":"特定 (とくてい): nhất định, cụ thể, xác định","translation_vi":"Loài cá này không phải lúc nào cũng có ở vùng biển quanh đây, mà chỉ có vào một khoảng thời gian nhất định."},{"mondai":4,"q":18,"prompt":"この季節は乾燥していて、肌が(　　)になる。","options":["どろどろ","ふさふさ","かさかさ","べたべた"],"answer":3,"word_explain":"かさかさ: khô ráp, nứt nẻ","translation_vi":"Mùa này thời tiết khô hanh nên da bị khô ráp."},{"mondai":4,"q":19,"prompt":"先生の発音をよく聞いて、同じになるように発音を(　　)みましょう。","options":["まねて","かなえて","映して","保って"],"answer":1,"word_explain":"まねる (真似る): bắt chước, mô phỏng","translation_vi":"Hãy nghe kỹ phát âm của giáo viên và thử bắt chước phát âm cho giống nhé."},{"mondai":4,"q":20,"prompt":"金子さんとは初めて会ったが、お互いサッカーが大好きだと分かって、話が(　　)。","options":["飛び出した","行き過ぎた","盛り上がった","駆け抜けた"],"answer":3,"word_explain":"盛り上がる (もりあがる): trở nên sôi nổi, hào hứng","translation_vi":"Tuy mới gặp anh/chị Kaneko lần đầu, nhưng khi biết cả hai đều rất thích bóng đá thì câu chuyện trở nên vô cùng sôi nổi."},{"mondai":5,"q":21,"prompt":"これについては、<u>各自</u>が責任を持つことにします。","options":["私","代表者","一人一人","あなた"],"answer":3,"word_explain":"各自 (かくじ) = 一人一人 (ひとりひとり): mỗi người, từng cá nhân","translation_vi":"Về việc này, mỗi người sẽ tự chịu trách nhiệm."},{"mondai":5,"q":22,"prompt":"明日はレポートを<u>仕上げる</u>つもりです。","options":["書く","完成させる","出す","整理する"],"answer":2,"word_explain":"仕上げる (しあげる) = 完成させる (かんせいさせる): hoàn thành, làm cho xong","translation_vi":"Ngày mai tôi dự định sẽ hoàn thành bản báo cáo."},{"mondai":5,"q":23,"prompt":"それは<u>深刻な</u>問題だ。","options":["単純な","身近な","微妙な","重大な"],"answer":4,"word_explain":"深刻な (しんこくな) = 重大な (じゅうだいな): nghiêm trọng, trầm trọng","translation_vi":"Đó là một vấn đề nghiêm trọng."},{"mondai":5,"q":24,"prompt":"今日は<u>同僚</u>と食事に行く予定です。","options":["同じ会社の人","同じアパートの人","同じ出身地の人","同じクラスの人"],"answer":1,"word_explain":"同僚 (どうりょう) = 同じ会社の人: đồng nghiệp","translation_vi":"Hôm nay tôi dự định đi ăn với đồng nghiệp."},{"mondai":5,"q":25,"prompt":"前田さんはさっきから<u>うつむいて</u>いる。","options":["上を向いて","横を向いて","下を向いて","後ろを向いて"],"answer":3,"word_explain":"うつむく = 下を向く: cúi mặt xuống, nhìn xuống","translation_vi":"Anh/chị Maeda từ nãy đến giờ cứ cúi mặt xuống."},{"mondai":6,"q":26,"prompt":"廃止","options":["両親は20年以上続けてきた店を<u>廃止</u>することにした。","点検のため、午前中はエレベーターの使用を<u>廃止</u>します。","雨が降ってきたので、今日のイベントは<u>廃止</u>します。","時代に合わない古い制度は<u>廃止</u>したほうがいい。"],"answer":4,"word_explain":"廃止 (はいし): bãi bỏ, hủy bỏ (dùng cho chế độ, quy định, luật lệ, tuyến đường...)","translation_vi":"Những chế độ cũ không còn phù hợp với thời đại thì nên bãi bỏ."},{"mondai":6,"q":27,"prompt":"腫れる","options":["森さんのポケットは、物が多くて<u>腫れて</u>いる。","今日はたくさん食べたので、おなかが<u>腫れて</u>いる。","サッカーの試合でけがをして、足が<u>腫れて</u>しまった。","オーブンでクッキーを焼いたら、だんだん<u>腫れて</u>きた。"],"answer":3,"word_explain":"腫れる (はれる): sưng lên, sưng tấy (do bị thương, viêm)","translation_vi":"Tôi bị chấn thương trong trận đấu bóng đá nên chân bị sưng lên mất rồi."},{"mondai":6,"q":28,"prompt":"上達","options":["毎日練習しているので、ピアノがかなり<u>上達</u>した。","いい病院で治療してもらえたようで、祖父の体調は<u>上達</u>した。","同じ作家が好きなことが分かって、大野さんとの仲が<u>上達</u>した。","小川さんが詳しく説明してくれたので、理解が<u>上達</u>した。"],"answer":1,"word_explain":"上達 (じょうたつ): tiến bộ, giỏi lên (dùng cho kỹ năng, năng lực như đàn, ngoại ngữ...)","translation_vi":"Vì luyện tập mỗi ngày nên trình độ chơi piano đã tiến bộ lên nhiều."},{"mondai":6,"q":29,"prompt":"暮れ","options":["この物語の<u>暮れ</u>は、意外な内容だった。","旅行の<u>暮れ</u>に、みんなで記念に写真を撮った。","授業の<u>暮れ</u>に、先生が今日の宿題を出した。","今年の<u>暮れ</u>は、実家で両親と過ごしたい。"],"answer":4,"word_explain":"暮れ (くれ): cuối năm (hoặc lúc chiều tà)","translation_vi":"Cuối năm nay tôi muốn về quê đón cùng bố mẹ."},{"mondai":6,"q":30,"prompt":"残高","options":["私たちが会議室を利用できる<u>残高</u>は、あと10分です。","私の銀行口座の<u>残高</u>は、1,000円しかありません。","この町の<u>残高</u>は、ついに１万人を下回りました。","山の頂上までの<u>残高</u>は、100メートルくらいです。"],"answer":2,"word_explain":"残高 (ざんだか): số dư (tài khoản ngân hàng, tiền còn lại)","translation_vi":"Số dư trong tài khoản ngân hàng của tôi chỉ còn 1.000 yên."}]},{"id":"2023_07","displayName":"07/2023","sourceFile":"Đề N2 T7-2023 (230710).pdf","questions":[{"mondai":1,"q":1,"prompt":"バスの<u>運賃</u>を払う。","options":["うんしん","うんちん","うんにん","うんりん"],"answer":2,"word_explain":"運賃 (うんちん): tiền cước, giá vé (xe buýt, tàu...)","translation_vi":"Trả tiền vé xe buýt."},{"mondai":1,"q":2,"prompt":"風が強くて、髪が<u>乱れて</u>しまった。","options":["くずれて","あれて","あばれて","みだれて"],"answer":4,"word_explain":"乱れる (みだれる): rối tung, hỗn loạn","translation_vi":"Vì gió mạnh nên tóc đã bị rối tung lên."},{"mondai":1,"q":3,"prompt":"前田さんは子供たちに正しい泳ぎ方の<u>模範</u>を示した。","options":["もうばん","もうはん","もばん","もはん"],"answer":4,"word_explain":"模範 (もはん): gương mẫu, kiểu mẫu","translation_vi":"Anh Maeda đã làm mẫu cách bơi đúng cho bọn trẻ."},{"mondai":1,"q":4,"prompt":"思った以上に<u>険しかった</u>。","options":["けわしかった","まぶしかった","おそろしかった","はげしかった"],"answer":1,"word_explain":"険しい (けわしい): hiểm trở, dốc đứng; nghiêm khắc","translation_vi":"Hiểm trở hơn tôi nghĩ."},{"mondai":1,"q":5,"prompt":"さっき<u>握手</u>していた人は誰ですか。","options":["おくしゅ","はくしゅ","あくしゅ","ほくしゅ"],"answer":3,"word_explain":"握手 (あくしゅ): bắt tay","translation_vi":"Người vừa nãy bắt tay là ai vậy?"},{"mondai":2,"q":6,"prompt":"その<u>ぬの</u>を広げてください。","options":["布","袋","衣","帯"],"answer":1,"word_explain":"布 (ぬの): vải","translation_vi":"Hãy trải tấm vải đó ra."},{"mondai":2,"q":7,"prompt":"今後は<u>ふくし</u>の仕事に就く予定です。","options":["福支","副祉","福祉","副支"],"answer":3,"word_explain":"福祉 (ふくし): phúc lợi","translation_vi":"Từ nay về sau tôi dự định sẽ làm công việc liên quan đến phúc lợi."},{"mondai":2,"q":8,"prompt":"毎日たくさんのごみが<u>すてられて</u>いる。。","options":["拾てられて","投てられて","採てられて","捨てられて"],"answer":4,"word_explain":"捨てる (すてる): vứt bỏ","translation_vi":"Mỗi ngày có rất nhiều rác bị vứt bỏ."},{"mondai":2,"q":9,"prompt":"小山さんの<u>きげん</u>がよいときに頼んでみよう。","options":["機兼","機嫌","気嫌","気兼"],"answer":2,"word_explain":"機嫌 (きげん): tâm trạng, thái độ","translation_vi":"Hãy thử nhờ vào lúc tâm trạng anh Koyama đang tốt xem sao."},{"mondai":2,"q":10,"prompt":"これは、会社にとって大きな<u>そんしつ</u>だ。","options":["消失","隕失","消失","損失"],"answer":4,"word_explain":"損失 (そんしつ): tổn thất, thiệt hại","translation_vi":"Đây là một tổn thất lớn đối với công ty."},{"mondai":3,"q":11,"prompt":"アンケートでは、質問に(　　)回答の人もいた。","options":["無","空","欠","失"],"answer":1,"word_explain":"無回答 (むかいとう): không trả lời, bỏ trống câu trả lời","translation_vi":"Trong bảng khảo sát, cũng có người không trả lời câu hỏi."},{"mondai":3,"q":12,"prompt":"この本には海外にある日本(　　)の家がたくさん載っている。","options":["気","類","風","状"],"answer":3,"word_explain":"日本風 (にほんふう): kiểu Nhật, phong cách Nhật Bản","translation_vi":"Trong cuốn sách này có đăng rất nhiều ngôi nhà phong cách Nhật Bản ở nước ngoài."},{"mondai":3,"q":13,"prompt":"壁(　　)のソファーに座る。","options":["所","際","辺","域"],"answer":2,"word_explain":"壁際 (かべぎわ): sát tường, cạnh tường","translation_vi":"Ngồi lên chiếc ghế sofa ở sát tường."},{"mondai":4,"q":14,"prompt":"彼は本当は優しい人なのに、無口なせいで、冷たい人だとよく(　　)される。","options":["観測","誤解","決意","承認"],"answer":2,"word_explain":"誤解 (ごかい): hiểu lầm","translation_vi":"Anh ấy thực ra là người tốt bụng, nhưng vì ít nói nên hay bị hiểu lầm là người lạnh lùng."},{"mondai":4,"q":15,"prompt":"新製品の売れ行きが(　　)なので、生産量を増やすことにした。","options":["温厚","円満","好調","適切"],"answer":3,"word_explain":"好調 (こうちょう): thuận lợi, tiến triển tốt, bán chạy","translation_vi":"Vì tình hình tiêu thụ sản phẩm mới rất khả quan nên chúng tôi đã quyết định tăng sản lượng."},{"mondai":4,"q":16,"prompt":"彼は、どんな仕事でもミス一つなく期日までに仕上げてくれるので、本当に(　　)部下だと思う。","options":["頼もしい","たくましい","輝かしい","親しい"],"answer":1,"word_explain":"頼もしい (たのもしい): đáng tin cậy, vững chãi","translation_vi":"Cậu ấy hoàn thành mọi công việc đúng thời hạn mà không một sai sót nào, nên tôi nghĩ cậu ấy thực sự là một cấp dưới đáng tin cậy."},{"mondai":4,"q":17,"prompt":"食費を(　　)するために、なるべく外食をしないようにしている。","options":["減量","省略","短縮","節約"],"answer":4,"word_explain":"節約 (せつやく): tiết kiệm","translation_vi":"Để tiết kiệm tiền ăn, tôi cố gắng hạn chế đi ăn ngoài."},{"mondai":4,"q":18,"prompt":"簡単にお金がもうかるというような話に、すぐ(　　)のはやめたほうがいい。","options":["駆け込む","触れ合う","寄りかかる","飛びつく"],"answer":4,"word_explain":"飛びつく (とびつく): vồ lấy, ham hố tin ngay (vào chuyện hời)","translation_vi":"Bạn nên từ bỏ thói quen hễ nghe chuyện kiếm tiền dễ dàng là vồ lấy ngay đi."},{"mondai":4,"q":19,"prompt":"やりたい仕事内容の(　　)があったので、早速応募することにした。","options":["催促","入社","求人","収集"],"answer":3,"word_explain":"求人 (きゅうじん): tuyển dụng, tin tuyển người","translation_vi":"Vì có tin tuyển dụng đúng nội dung công việc tôi muốn làm, nên tôi đã quyết định ứng tuyển ngay."},{"mondai":4,"q":20,"prompt":"友達だと思っていたのに、私のいないところで(　　)と私の悪口を言っていたなんてひどい。","options":["うとうと","こそこそ","ぶるぶる","じろじろ"],"answer":2,"word_explain":"こそこそ: lén lút, giấu giếm","translation_vi":"Tôi cứ nghĩ là bạn bè, vậy mà lại lén lút nói xấu sau lưng tôi, thật quá đáng."},{"mondai":5,"q":21,"prompt":"この建物を壊すには<u>惜しい</u>。","options":["危ない","もったいない","めんどくさい","難しい"],"answer":2,"word_explain":"惜しい (おしい) = もったいない: đáng tiếc, lãng phí","translation_vi":"Phá bỏ tòa nhà này thì thật đáng tiếc."},{"mondai":5,"q":22,"prompt":"きちんと<u>テンポ</u>を合わせてください。","options":["長さ","高さ","大きさ","速さ"],"answer":4,"word_explain":"テンポ = 速さ (はやさ): nhịp độ, tốc độ","translation_vi":"Hãy phối hợp đúng nhịp độ (tốc độ)."},{"mondai":5,"q":23,"prompt":"そのニュースは<u>たちまち</u>広まった。","options":["すぐに","次第に","確かに","意外に"],"answer":1,"word_explain":"たちまち = すぐに: ngay lập tức, trong chốc lát","translation_vi":"Tin tức đó đã lan truyền ra ngay lập tức."},{"mondai":5,"q":24,"prompt":"研究の<u>概要</u>を述べる。","options":["詳しい内容","大体の内容","主な目的","最終的な目的"],"answer":2,"word_explain":"概要 (がいよう) = 大体の内容: khái quát, nội dung đại khái","translation_vi":"Trình bày khái quát về nghiên cứu."},{"mondai":5,"q":25,"prompt":"あのときは<u>油断していた</u>。","options":["慌てていた","何も覚えていなかった","気を付けていなかった","迷っていた"],"answer":3,"word_explain":"油断する (ゆだんする) = 気を付けていない: chủ quan, lơ là, mất cảnh giác","translation_vi":"Lúc đó tôi đã chủ quan (lơ là)."},{"mondai":6,"q":26,"prompt":"早期","options":["夏休みの<u>早期</u>は旅行をして、その後は試験勉強をする予定だ。","明日の飛行機は<u>早期</u>の便だから、朝5時に家を出なければならない。","一人暮らしの<u>早期</u>は、料理などの失敗も多くて苦労した。","医学の進歩によって、病気を<u>早期</u>の段階で見つけられるようになった。"],"answer":4,"word_explain":"早期 (そうき): giai đoạn đầu, sớm (thường dùng cho bệnh tật, giải quyết vấn đề: 早期発見, 早期の段階)","translation_vi":"Nhờ sự tiến bộ của y học, người ta đã có thể phát hiện bệnh ở giai đoạn sớm."},{"mondai":6,"q":27,"prompt":"偉大","options":["山川さんのフランス語のスピーチはとても<u>偉大</u>だった。","この国には<u>偉大</u>な画家がたくさんいる。","あの家は、この辺りでいちばん<u>偉大</u>な家です。","あの人は<u>偉大</u>な馬を何頭も飼っている。"],"answer":2,"word_explain":"偉大 (いだい): vĩ đại, kiệt xuất (dùng cho nhân vật, thành tích, công lao...)","translation_vi":"Ở đất nước này có rất nhiều họa sĩ vĩ đại."},{"mondai":6,"q":28,"prompt":"印","options":["復習するときのために、大切な単語に赤のペンで<u>印</u>をつけた。","係員が旗を上げたのを<u>印</u>に、選手たちは一斉に走りだした。","角に病院がありますから、それを<u>印</u>に私の家まで来てください。","運転する人は、交通の<u>印</u>の意味を全部知っていなければならない。"],"answer":1,"word_explain":"印 (しるし): dấu, ký hiệu đánh dấu (印をつける: đánh dấu)","translation_vi":"Để tiện cho việc ôn tập, tôi đã dùng bút đỏ đánh dấu vào những từ vựng quan trọng."},{"mondai":6,"q":29,"prompt":"続出","options":["昨日からの雪で、転んでけがをする人が<u>続出</u>している。","ゆうべはせきが<u>続出</u>して、あまりよく眠れなかった。","鈴木アナウンサーは、このテレビ番組に5年間<u>続出</u>している。","この映画に関係する本や商品が、来週から<u>続出</u>するらしい。"],"answer":1,"word_explain":"続出 (ぞくしゅつ): xuất hiện liên tiếp, xảy ra dồn dập (thường dùng cho sự cố, người bị thương, ý kiến, người bỏ cuộc...)","translation_vi":"Do tuyết rơi từ hôm qua nên số người bị trượt ngã và chấn thương đang xuất hiện liên tiếp."},{"mondai":6,"q":30,"prompt":"さまたげる","options":["掲示板のポスターが取れそうになっていたので、テープで<u>さまたげた</u>。","原材料が高くなったが、製造方法を変えて、製品の値上げを<u>さまたげた</u>。","関係のない発言で、会議の進行を<u>さまたげ</u>ないでください。","工場内の事故を<u>さまたげる</u>ために、作業の前に安全確認を行う。"],"answer":3,"word_explain":"妨げる (さまたげる): cản trở, làm gián đoạn (tiến độ, giấc ngủ, công việc...)","translation_vi":"Xin đừng làm gián đoạn tiến trình cuộc họp bằng những phát biểu không liên quan."}]},{"id":"2022_12","displayName":"12/2022","sourceFile":"N2 T12-2022.pdf","questions":[{"mondai":1,"q":1,"prompt":"建物の入口に<u>警備</u>の人がいます。","options":["けいひ","けいび","けひ","けび"],"answer":2,"word_explain":"警備 (けいび): cảnh bị, bảo vệ","translation_vi":"Ở lối vào tòa nhà có nhân viên bảo vệ."},{"mondai":1,"q":2,"prompt":"絵を見て、想像力が<u>刺激</u>されました。","options":["じえき","じげき","しえき","しげき"],"answer":4,"word_explain":"刺激 (しげき): kích thích","translation_vi":"Nhìn bức tranh, trí tưởng tượng đã được kích thích."},{"mondai":1,"q":3,"prompt":"ここが<u>外れて</u>いますけど、どうしたんですか。","options":["はずれて","みだれて","やぶれて","つぶれて"],"answer":1,"word_explain":"外れる (はずれる): tuột ra, rời ra, trật ra","translation_vi":"Chỗ này bị tuột ra rồi, có chuyện gì thế?"},{"mondai":1,"q":4,"prompt":"私は<u>世間</u>の目を気にしすぎていたようだ。","options":["せかん","せけん","せいかん","せいはん"],"answer":2,"word_explain":"世間 (せけん): thế gian, xã hội, người đời","translation_vi":"Hình như tôi đã quá để ý đến ánh mắt của người đời."},{"mondai":1,"q":5,"prompt":"本田さんはとても<u>勇ましい</u>人だ。","options":["たくましい","やかましい","いさましい","あつかましい"],"answer":3,"word_explain":"勇ましい (いさましい): dũng cảm, gan dạ, oai phong","translation_vi":"Anh Honda là một người rất dũng cảm."},{"mondai":2,"q":6,"prompt":"彼にはお金持ちになりたいという<u>よく</u>がない。","options":["欲","望","求","情"],"answer":1,"word_explain":"欲 (よく): lòng tham, ham muốn","translation_vi":"Anh ấy không có ham muốn trở nên giàu có."},{"mondai":2,"q":7,"prompt":"私の職業は、<u>はいゆう</u>です。","options":["非憂","非優","俳憂","俳優"],"answer":4,"word_explain":"俳優 (はいゆう): diễn viên","translation_vi":"Nghề nghiệp của tôi là diễn viên."},{"mondai":2,"q":8,"prompt":"中山さんは、家族と<u>はなれて</u>、一人で暮らしているらしい。","options":["逃れて","別れて","離れて","避けて"],"answer":3,"word_explain":"離れる (はなれる): xa cách, rời xa","translation_vi":"Nghe nói anh Nakayama sống một mình, xa gia đình."},{"mondai":2,"q":9,"prompt":"病院で医師の<u>しんだん</u>を受けた。","options":["身断","診断","身談","診談"],"answer":2,"word_explain":"診断 (しんだん): chẩn đoán","translation_vi":"Tôi đã được bác sĩ chẩn đoán ở bệnh viện."},{"mondai":2,"q":10,"prompt":"AとBは、大きさが<u>ひとしい</u>。","options":["並しい","等しい","似しい","比しい"],"answer":2,"word_explain":"等しい (ひとしい): bằng nhau, tương đương","translation_vi":"A và B có kích thước bằng nhau."},{"mondai":3,"q":11,"prompt":"(　　)制度には、大きな問題があります。","options":["近","在","常","現"],"answer":4,"word_explain":"現制度 (げんせいど): chế độ hiện hành, chế độ hiện tại","translation_vi":"Chế độ hiện hành có vấn đề lớn."},{"mondai":3,"q":12,"prompt":"伯父は、電車の中で財布を盗まれてから用心(　　)なった。","options":["濃く","強く","深く","高く"],"answer":3,"word_explain":"用心深い (ようじんぶかい): thận trọng, cảnh giác cao","translation_vi":"Bác trai tôi từ sau khi bị trộm ví trên tàu điện đã trở nên cảnh giác hơn."},{"mondai":3,"q":13,"prompt":"このアンケートでは、(　　)団体の活動についてお尋ねします。","options":["貴","尊","敬","偉"],"answer":1,"word_explain":"貴団体 (きだんたい): quý tổ chức, quý đoàn thể (kính ngữ)","translation_vi":"Trong bản khảo sát này, chúng tôi xin hỏi về hoạt động của quý tổ chức."},{"mondai":4,"q":14,"prompt":"規則に(　　)した場合は、罰金を払わなければならない。","options":["相違","対決","違反","対抗"],"answer":3,"word_explain":"違反 (いはん): vi phạm","translation_vi":"Trường hợp vi phạm quy định thì phải nộp tiền phạt."},{"mondai":4,"q":15,"prompt":"この体育館は、ロッカーやシャワーなどの(　　)がそろっている。","options":["用具","物体","設備","容器"],"answer":3,"word_explain":"設備 (せつび): trang thiết bị, cơ sở vật chất","translation_vi":"Nhà thi đấu này có đầy đủ các trang thiết bị như tủ đồ và vòi hoa sen."},{"mondai":4,"q":16,"prompt":"化粧品メーカーが健康食品の分野に(　　)して成功した例もある。","options":["到達","転勤","直行","進出"],"answer":4,"word_explain":"進出 (しんしゅつ): tiến quân vào, mở rộng sang (lĩnh vực, thị trường mới)","translation_vi":"Cũng có ví dụ về việc hãng mỹ phẩm mở rộng sang lĩnh vực thực phẩm chức năng và thành công."},{"mondai":4,"q":17,"prompt":"この時期に雪が降ることはあるが、積もることは(　　)だ。","options":["まれ","なだらか","ささやか","かすか"],"answer":1,"word_explain":"まれ (稀): hiếm khi, hiếm hoi","translation_vi":"Vào thời điểm này tuyết cũng có khi rơi, nhưng việc tuyết đọng dày thì rất hiếm."},{"mondai":4,"q":18,"prompt":"家の隣で夜遅くまでマンション建設工事が行われてうるさいので、建設会社に(　　)の電話をした。","options":["悪口","苦情","反論","皮肉"],"answer":2,"word_explain":"苦情 (くじょう): lời phàn nàn, khiếu nại","translation_vi":"Vì công trình xây dựng chung cư bên cạnh nhà thi công đến tận đêm khuya gây ồn ào nên tôi đã gọi điện phàn nàn với công ty xây dựng."},{"mondai":4,"q":19,"prompt":"箱の中には、隙間なく(　　)お菓子が詰まっていた。","options":["どしどし","どっしり","うじゃうじゃ","ぎっしり"],"answer":4,"word_explain":"ぎっしり: chật kín, đầy ắp (không còn chỗ trống)","translation_vi":"Trong hộp được xếp đầy ắp bánh kẹo không một kẽ hở."},{"mondai":4,"q":20,"prompt":"私は前回の実験の結果にずっと疑問を(　　)いる。","options":["いだいて","にぎって","たもって","そなえて"],"answer":1,"word_explain":"抱く (いだく): ôm ấp, mang (nghi vấn, hy vọng, cảm xúc)","translation_vi":"Tôi vẫn luôn mang mối nghi ngờ về kết quả của thí nghiệm lần trước."},{"mondai":5,"q":21,"prompt":"あの選手には<u>テクニック</u>がある。","options":["自信","技術","経験","体力"],"answer":2,"word_explain":"テクニック = 技術 (ぎじゅつ): kỹ thuật","translation_vi":"Vận động viên kia có kỹ thuật."},{"mondai":5,"q":22,"prompt":"ここには大量の<u>書籍</u>が収められている。","options":["新聞","絵","本","手紙"],"answer":3,"word_explain":"書籍 (しょせき) = 本 (ほん): sách vở","translation_vi":"Ở đây lưu giữ một lượng lớn sách."},{"mondai":5,"q":23,"prompt":"今年になって国の方針が<u>一転した</u>。","options":["すっかり変わった","少し変わった","やっと決まった","すぐに決まった"],"answer":1,"word_explain":"一転する (いってんする) = すっかり変わる: thay đổi hoàn toàn, xoay chuyển 180 độ","translation_vi":"Sang năm nay, phương châm của nhà nước đã thay đổi hoàn toàn."},{"mondai":5,"q":24,"prompt":"この道具は先が<u>とがっている</u>。","options":["柔らかくなって","細くなって","硬くなって","太くなって"],"answer":2,"word_explain":"とがる (尖る) = 先が細くなる: nhọn, thuôn nhỏ ở đầu","translation_vi":"Dụng cụ này có đầu nhọn."},{"mondai":5,"q":25,"prompt":"彼がしていることは<u>くだらない</u>。","options":["効果がない","目的がない","変化がない","価値がない"],"answer":4,"word_explain":"くだらない = 価値がない (かちがない): vô giá trị, vớ vẩn, nhảm nhí","translation_vi":"Những việc anh ta đang làm thật vô giá trị."},{"mondai":6,"q":26,"prompt":"頑固","options":["木村さんはとても<u>頑固</u>で、自分の考えを変えない。","瓶のふたが<u>頑固</u>で、いくら力を入れても開かない。","兄は体が<u>頑固</u>なので、風邪をほとんどひかない。","相手チームの守りがとても<u>頑固</u>で、点が取れない。"],"answer":1,"word_explain":"頑固 (がんこ): ngoan cố, bướng bỉnh, cố chấp (dùng cho tính cách con người)","translation_vi":"Anh Kimura rất bướng bỉnh, không chịu thay đổi suy nghĩ của mình."},{"mondai":6,"q":27,"prompt":"打ち合わせ","options":["本日11時から、来月の講演会の<u>打ち合わせ</u>を行います。","高校生のころはよく、親友と互いの悩みの<u>打ち合わせ</u>をしました。","ホテルに電話をして、眼鏡の忘れ物がないか<u>打ち合わせ</u>をしました。","実験の後、失敗の原因について<u>打ち合わせ</u>を行いました。"],"answer":1,"word_explain":"打ち合わせ (うちあわせ): cuộc họp bàn, thảo luận sắp xếp trước (cho sự kiện, công việc)","translation_vi":"Từ 11 giờ hôm nay, chúng tôi sẽ tiến hành họp bàn về buổi diễn thuyết tháng tới."},{"mondai":6,"q":28,"prompt":"中断","options":["急に仕事が入ってしまい、レストランの予約を<u>中断</u>した。","部屋のカーテンを閉めて、太陽の光を<u>中断</u>した。","雨が強くなってきたので、やむまで試合を<u>中断</u>した。","今日は用事があるため、友人からの誘いを<u>中断</u>した。"],"answer":3,"word_explain":"中断 (ちゅうだん): gián đoạn, tạm dừng giữa chừng một việc đang diễn ra","translation_vi":"Vì trời mưa ngày càng nặng hạt nên trận đấu đã bị tạm dừng cho đến khi tạnh mưa."},{"mondai":6,"q":29,"prompt":"ベテラン","options":["あの<u>ベテラン</u>の電車は、今まで多くのお客さんを乗せてきた。","大野先生は、この学校で昔から教えている<u>ベテラン</u>の先生だ。","この<u>ベテラン</u>の時計は、もう生産していないので貴重だ。","ここは、私が生まれる前からある<u>ベテラン</u>のレストランだ。"],"answer":2,"word_explain":"ベテラン: người kỳ cựu, người dày dạn kinh nghiệm (chỉ dùng cho người)","translation_vi":"Thầy Ohno là một giáo viên kỳ cựu đã giảng dạy tại ngôi trường này từ lâu."},{"mondai":6,"q":30,"prompt":"荒れる","options":["この靴は10年履き続けているから、かなり<u>荒れて</u>いる。","入院で仕事を休んでいたので、営業成績は<u>荒れて</u>しまった。","冷蔵庫に入れておいたのに、りんごが<u>荒れて</u>しまった。","今日は海が<u>荒れて</u>いて、船で釣りに行くことはできない。"],"answer":4,"word_explain":"荒れる (あれる): (biển, thời tiết) nổi sóng, động, dữ dội; (da, phòng...) thô ráp, bừa bộn","translation_vi":"Hôm nay biển động nên không thể đi câu cá bằng thuyền được."}]},{"id":"2022_07","displayName":"07/2022","sourceFile":"N2 T7-2022 Final Version.pdf","questions":[{"mondai":1,"q":1,"prompt":"その当時の<u>記憶</u>あまりない。","options":["きりょく","きよく","きろく","きおく"],"answer":4,"word_explain":"記憶 (きおく): ký ức, trí nhớ","translation_vi":"Tôi không có nhiều ký ức về lúc đó."},{"mondai":1,"q":2,"prompt":"前田さんがそんなに<u>偉い</u>人だとは知りませんでした。","options":["かしこい","えらい","すごい","するどい"],"answer":2,"word_explain":"偉い (えらい): vĩ đại, xuất sắc, có địa vị cao","translation_vi":"Tôi đã không biết anh Maeda là một người xuất sắc đến vậy."},{"mondai":1,"q":3,"prompt":"私が仕事の話を始めたら、<u>途端に</u>西田さんの機嫌が悪くなった。","options":["とたんに","よたんに","たんとに","たんとうに"],"answer":1,"word_explain":"途端に (とたんに): ngay lập tức, vừa mới... thì","translation_vi":"Vừa mới khi tôi bắt đầu nói chuyện công việc, tâm trạng của anh Nishida lập tức trở nên tệ đi."},{"mondai":1,"q":4,"prompt":"スピーチ大会の司会を<u>務める</u>。","options":["まとめる","やめる","さだめる","つとめる"],"answer":4,"word_explain":"務める (つとめる): đảm nhiệm, giữ vai trò","translation_vi":"Đảm nhiệm vai trò người dẫn chương trình của cuộc thi hùng biện."},{"mondai":1,"q":5,"prompt":"これは特別な<u>素材</u>で作られているそうだ。","options":["そうざい","しょうざい","そざい","しょざい"],"answer":3,"word_explain":"素材 (そざい): chất liệu, nguyên liệu","translation_vi":"Nghe nói cái này được làm từ chất liệu đặc biệt."},{"mondai":2,"q":6,"prompt":"いつのまにか太陽が<u>のぼって</u>いた。","options":["去って","至って","昇って","照って"],"answer":3,"word_explain":"昇って (のぼって): mọc lên, lên cao (mặt trời)","translation_vi":"Không biết tự bao giờ mặt trời đã mọc lên rồi."},{"mondai":2,"q":7,"prompt":"<u>すいちょく</u>に栓を引く。","options":["乗頂","乗直","垂頂","垂直"],"answer":4,"word_explain":"垂直 (すいちょく): thẳng đứng, vuông góc","translation_vi":"Kẻ một đường thẳng đứng. (Lưu ý: nguyên văn đề gõ nhầm 「線」 thành 「栓」)"},{"mondai":2,"q":8,"prompt":"研修生を受け入れるために、<u>じゅうきょ</u>を確保する必要がある。","options":["住宅","住居","住家","住屋"],"answer":2,"word_explain":"住居 (じゅうきょ): chỗ ở, nơi cư trú","translation_vi":"Để tiếp nhận thực tập sinh, cần phải đảm bảo chỗ ở."},{"mondai":2,"q":9,"prompt":"災害に<u>そなえる</u>ことはとても大切だ。","options":["備える","準える","整える","控える"],"answer":1,"word_explain":"備える (そなえる): chuẩn bị sẵn sàng, đề phòng","translation_vi":"Việc chuẩn bị sẵn sàng ứng phó với thiên tai là rất quan trọng."},{"mondai":2,"q":10,"prompt":"<u>てんけいてき</u>な例を挙げて説明した。","options":["点型的","典形的","点形的","典型的"],"answer":4,"word_explain":"典型的 (てんけいてき): điển hình","translation_vi":"Tôi đã đưa ra một ví dụ điển hình để giải thích."},{"mondai":3,"q":11,"prompt":"(　　)分野の人と話すのはいい刺激になる。","options":["逆","異","副","裏"],"answer":2,"word_explain":"異分野 (いぶんや): lĩnh vực khác","translation_vi":"Việc nói chuyện với người thuộc lĩnh vực khác sẽ là một sự kích thích tốt."},{"mondai":3,"q":12,"prompt":"その店は、よい品物を(　　)価格で売っている。","options":["半","安","小","低"],"answer":4,"word_explain":"低価格 (ていかかく): giá thấp, giá rẻ","translation_vi":"Cửa hàng đó đang bán những mặt hàng tốt với mức giá thấp."},{"mondai":3,"q":13,"prompt":"運転免許など、顔写真(　　)の身分証明書を見せてください。","options":["足し","載せ","付き","含み"],"answer":3,"word_explain":"顔写真付き (かおじゃしんつき): có kèm ảnh chân dung","translation_vi":"Xin hãy xuất trình giấy tờ tùy thân có ảnh chân dung, chẳng hạn như bằng lái xe."},{"mondai":4,"q":14,"prompt":"職場環境の問題については、会社との(　　)の結果、改善してもらえることになった。","options":["交渉","授受","通話","出願"],"answer":1,"word_explain":"交渉 (こうしょう): đàm phán, thương lượng","translation_vi":"Về vấn đề môi trường làm việc, kết quả sau khi thương lượng với công ty là sẽ được cải thiện."},{"mondai":4,"q":15,"prompt":"この企画を成功させるには、いくつもの課題を(　　)しなければならない。","options":["キャンセル","クリア","カット","ブラッシュ"],"answer":2,"word_explain":"クリア: vượt qua, giải quyết xong","translation_vi":"Để đưa kế hoạch này đến thành công, phải vượt qua rất nhiều vấn đề."},{"mondai":4,"q":16,"prompt":"このカメラは小型だが、通常のモデルに比べて性能が(　　)いるわけではない。","options":["縮んで","荒れて","沈んで","劣って"],"answer":4,"word_explain":"劣る (おとる): kém hơn, thua kém","translation_vi":"Chiếc máy ảnh này tuy nhỏ gọn nhưng không phải là hiệu năng kém hơn so với mẫu thông thường."},{"mondai":4,"q":17,"prompt":"父は手術後、医者も驚くほど(　　)回復した。","options":["劇的に","格別に","真剣に","強大に"],"answer":1,"word_explain":"劇的に (げきてきに): một cách ngoạn mục, đáng kinh ngạc","translation_vi":"Sau ca phẫu thuật, bố tôi đã hồi phục một cách ngoạn mục đến mức bác sĩ cũng phải kinh ngạc."},{"mondai":4,"q":18,"prompt":"このシステムを利用するには、インターネットに(　　)しているパソコンが必要です。","options":["到達","付属","接続","密着"],"answer":3,"word_explain":"接続 (せつぞく): kết nối","translation_vi":"Để sử dụng hệ thống này, cần có máy tính đang kết nối với internet."},{"mondai":4,"q":19,"prompt":"アルバイトの募集は3月末で(　　)ので、もう応募はできません。","options":["取り払った","打ち消した","締め切った","引き離した"],"answer":3,"word_explain":"締め切る (しめきる): kết thúc nhận (đơn), chốt hạn","translation_vi":"Việc tuyển nhân viên làm thêm đã kết thúc nhận hồ sơ vào cuối tháng 3, nên bây giờ không thể ứng tuyển được nữa."},{"mondai":4,"q":20,"prompt":"ガイドの後ろをツアー客たちが、(　　)ついて歩いている。","options":["ごくごく","ぞろぞろ","ぎしぎし","じめじめ"],"answer":2,"word_explain":"ぞろぞろ: lũ lượt, nối đuôi nhau từng đoàn","translation_vi":"Các khách du lịch theo tour đang lũ lượt đi theo phía sau hướng dẫn viên."},{"mondai":5,"q":21,"prompt":"<u>衝突しそう</u>になってしまった。","options":["ぶつかりそう","落ちそう","壊しそう","破りそう"],"answer":1,"word_explain":"衝突しそう (しょうとつしそう) = ぶつかりそう: suýt va chạm, suýt đâm vào","translation_vi":"Đã suýt chút nữa thì xảy ra va chạm."},{"mondai":5,"q":22,"prompt":"彼には<u>再三</u>お願いしているです。","options":["たまに","何度か","何度も","いつも"],"answer":3,"word_explain":"再三 (さいさん) = 何度も: nhiều lần, năm lần bảy lượt","translation_vi":"Tôi đã nhờ cậy anh ấy rất nhiều lần rồi."},{"mondai":5,"q":23,"prompt":"彼が言っていることは<u>でたらめ</u>だ。","options":["悪口","わがまま","うそ","自慢"],"answer":3,"word_explain":"でたらめ = うそ: bịa đặt, nói dối, vớ vẩn","translation_vi":"Những điều anh ta đang nói toàn là bịa đặt (nói dối)."},{"mondai":5,"q":24,"prompt":"すみません、<u>お勘定</u>をお願いします。","options":["注文","会計","予約","配達"],"answer":2,"word_explain":"お勘定 (おかんじょう) = 会計 (かいけい): thanh toán, tính tiền","translation_vi":"Xin lỗi, cho tôi thanh toán với ạ."},{"mondai":5,"q":25,"prompt":"今日は、犬がいつもより<u>さわがしい</u>。","options":["悲しい","静かだ","楽しい","うるさい"],"answer":4,"word_explain":"さわがしい = うるさい: ồn ào, ầm ĩ","translation_vi":"Hôm nay con chó ồn ào hơn mọi ngày."},{"mondai":6,"q":26,"prompt":"温厚","options":["<u>温厚</u>な伯父は、みんなから愛されている。","旅行中は、どこに行っても<u>温厚</u>な歓迎を受けてうれしかった。","今日は気温が下がるようなので、<u>温厚</u>なコートが必要だ。","雪の日には<u>温厚</u>なスープが飲みたくなる"],"answer":1,"word_explain":"温厚 (おんこう): ôn hòa, điềm đạm, hiền hậu (dùng để miêu tả tính cách con người)","translation_vi":"Người bác ôn hòa, hiền hậu của tôi được mọi người yêu quý."},{"mondai":6,"q":27,"prompt":"濁る","options":["外と室内の温度の差で窓が<u>濁っている</u>。","今日は空が雲で暗く<u>濁っている</u>。","しばらく洗っていないので、車が<u>濁っている</u>。","大雨で川の水が茶色く<u>濁っている</u>。"],"answer":4,"word_explain":"濁る (にごる): đục, vẩn đục (dùng cho chất lỏng như nước sông, nước hồ, hoặc giọng nói/âm thanh)","translation_vi":"Do mưa lớn nên nước sông bị vẩn đục thành màu nâu."},{"mondai":6,"q":28,"prompt":"世代","options":["野口さんはまだ20代なので、<u>世代</u>を取っているとはいえない。","先日のパーティーでは私と同じ<u>世代</u>の人がたくさんいて、話が盛り上がった。","青山さんは今は日本語の先生をしているが、実は英語の先生の<u>世代</u>が長い。","仕事を頑張るだけでなく、趣味も楽しんで、充実した<u>世代</u>を送りたい。"],"answer":2,"word_explain":"世代 (せだい): thế hệ, lứa tuổi","translation_vi":"Ở bữa tiệc hôm trước có rất nhiều người cùng thế hệ với tôi nên câu chuyện diễn ra rất sôi nổi."},{"mondai":6,"q":29,"prompt":"普及","options":["よくないうわさが<u>普及</u>しているので、気をつけてください。","全員に飲み物が<u>普及</u>したようなので、森さんから乾杯のあいさつをお願いします。","最近は携帯電話が<u>普及</u>しているので、家に電話を置かない家庭もある。","先週からインフルエンザが<u>普及</u>していて、小学校が休みになっている。"],"answer":3,"word_explain":"普及 (ふきゅう): phổ cập, phổ biến rộng rãi (thường dùng cho sản phẩm, công nghệ, chế độ, văn hóa)","translation_vi":"Gần đây điện thoại di động đã phổ biến rộng rãi nên cũng có những gia đình không lắp điện thoại cố định ở nhà."},{"mondai":6,"q":30,"prompt":"生じる","options":["メールシステムに問題が<u>生じて</u>、メールが送れなくなった。","バターやチーズは牛乳から<u>生じる</u>。","昨日、姉に2番目の子どもが<u>生じた</u>。","いくら考えても、いいアイデアが<u>生じない</u>。"],"answer":1,"word_explain":"生じる (しょうじる): phát sinh, nảy sinh (vấn đề, sự cố, nghi ngờ, cảm xúc...)","translation_vi":"Hệ thống email phát sinh sự cố nên không thể gửi email được nữa."}]},{"id":"2021_12","displayName":"12/2021","sourceFile":"Đề N2 T12-2021.pdf","questions":[{"mondai":1,"q":1,"prompt":"美しい<u>情景</u>が目に浮かんだ。","options":["じょうけい","じょけい","じょうえい","じょえい"],"answer":1,"word_explain":"情景 (じょうけい): cảnh tượng, khung cảnh","translation_vi":"Cảnh tượng tuyệt đẹp hiện lên trước mắt tôi."},{"mondai":1,"q":2,"prompt":"この世代の人たちはコンピューターの知識が<u>乏しい</u>ように思う。","options":["くわしい","とぼしい","まずしい","あやしい"],"answer":2,"word_explain":"乏しい (とぼしい): nghèo nàn, thiếu thốn, ít ỏi","translation_vi":"Tôi thấy những người thuộc thế hệ này có vẻ thiếu kiến thức về máy tính."},{"mondai":1,"q":3,"prompt":"ボランティアでお年寄りの<u>介護</u>をしている。","options":["かいごう","かんごう","かいご","かんご"],"answer":3,"word_explain":"介護 (かいご): sự chăm sóc, điều dưỡng (người già, người bệnh)","translation_vi":"Tôi đang làm tình nguyện viên chăm sóc người cao tuổi."},{"mondai":1,"q":4,"prompt":"今ごろになって<u>焦って</u>もしかたない。","options":["あせっても","しかっても","まよっても","いのっても"],"answer":1,"word_explain":"焦る (あせる): nóng vội, sốt ruột, hoảng hốt","translation_vi":"Đến bây giờ mới cuống lên thì cũng chẳng ích gì."},{"mondai":1,"q":5,"prompt":"高速道路の建設については、<u>賛否</u>が分かれた。","options":["さんふ","さんぽ","さんひ","さんぴ"],"answer":4,"word_explain":"賛否 (さんぴ): tán thành hay phản đối","translation_vi":"Về việc xây dựng đường cao tốc, ý kiến tán thành và phản đối đã bị chia rẽ."},{"mondai":2,"q":6,"prompt":"この仕事は、山本さんに<u>まかせて</u>おけば安心です。","options":["仕せて","担せて","任せて","但せて"],"answer":3,"word_explain":"任せる (まかせる): giao phó, ủy thác","translation_vi":"Công việc này cứ giao cho anh/chị Yamamoto thì sẽ yên tâm."},{"mondai":2,"q":7,"prompt":"新入生をテニスサークルに<u>かんゆう</u>した。","options":["勧誘","勧遊","観誘","観遊"],"answer":1,"word_explain":"勧誘 (かんゆう): sự mời mọc, rủ rê, chiêu mộ","translation_vi":"Tôi đã rủ sinh viên mới vào câu lạc bộ quần vợt."},{"mondai":2,"q":8,"prompt":"この計画は<u>じゅんちょう</u>に進んでいる。","options":["準長","準調","順長","順調"],"answer":4,"word_explain":"順調 (じゅんちょう): thuận lợi, suôn sẻ","translation_vi":"Kế hoạch này đang tiến triển thuận lợi."},{"mondai":2,"q":9,"prompt":"落ち葉が<u>つもった</u>道を歩いた。","options":["詰もった","満もった","占もった","積もった"],"answer":4,"word_explain":"積もる (つもる): chất đống, tích tụ, phủ dày","translation_vi":"Tôi đã đi bộ trên con đường phủ đầy lá rụng."},{"mondai":2,"q":10,"prompt":"この状態が<u>えいきゅう</u>に続くわけではない。","options":["延久","永久","延及","永及"],"answer":2,"word_explain":"永久 (えいきゅう): vĩnh cửu, mãi mãi","translation_vi":"Trạng thái này không phải là sẽ kéo dài mãi mãi."},{"mondai":3,"q":11,"prompt":"私も山口さんと(　　)意見です。","options":["等","同","共","似"],"answer":2,"word_explain":"同意見 (どういけん): cùng ý kiến, đồng quan điểm","translation_vi":"Tôi cũng có cùng ý kiến với anh/chị Yamaguchi."},{"mondai":3,"q":12,"prompt":"このバナナは甘い香りがするので、そろそろ食べ(　　)ですよ。","options":["頃","期","刻","節"],"answer":1,"word_explain":"食べ頃 (たべごろ): độ chín ngon nhất để ăn","translation_vi":"Quả chuối này có mùi thơm ngọt rồi nên sắp đến lúc ăn ngon nhất rồi đấy."},{"mondai":3,"q":13,"prompt":"本登録の前に、まずは(　　)登録を行ってください。","options":["先","予","仮","近"],"answer":3,"word_explain":"仮登録 (かりとうろく): đăng ký tạm thời","translation_vi":"Trước khi đăng ký chính thức, trước hết hãy thực hiện đăng ký tạm thời."},{"mondai":4,"q":14,"prompt":"学生のころ、宿題は(　　)になってからやることが多かった。","options":["びりびり","ばりばり","ぎりぎり","じりじり"],"answer":3,"word_explain":"ぎりぎり: sát nút, sát giờ chót","translation_vi":"Hồi còn là học sinh, tôi thường đợi đến sát giờ mới làm bài tập về nhà."},{"mondai":4,"q":15,"prompt":"生命保険を(　　)したいので、手続きを教えてください。","options":["廃止","解約","中止","解消"],"answer":2,"word_explain":"解約 (かいやく): hủy hợp đồng, giải ước","translation_vi":"Tôi muốn hủy hợp đồng bảo hiểm nhân thọ nên hãy chỉ cho tôi thủ tục."},{"mondai":4,"q":16,"prompt":"私たちは、お客様の(　　)に対応したサービスを提供しています","options":["ニーズ","ストライキ","セールス","エコノミー"],"answer":1,"word_explain":"ニーズ: nhu cầu (needs)","translation_vi":"Chúng tôi đang cung cấp dịch vụ đáp ứng nhu cầu của khách hàng."},{"mondai":4,"q":17,"prompt":"来年ここに新しい支店を(　　)することが決まった","options":["創造","形成","工作","開設"],"answer":4,"word_explain":"開設 (かいせつ): mở, thành lập (chi nhánh, cửa hàng, tài khoản...)","translation_vi":"Đã quyết định rằng năm sau sẽ mở một chi nhánh mới ở đây."},{"mondai":4,"q":18,"prompt":"卒業パーティーには、ちゃんとした(　　)で行ったほうがいいのかな。","options":["様子","容姿","外見","格好"],"answer":4,"word_explain":"格好 (かっこう): trang phục, diện mạo, vẻ ngoài","translation_vi":"Không biết đi dự tiệc tốt nghiệp thì có nên ăn mặc chỉnh tề không nhỉ."},{"mondai":4,"q":19,"prompt":"店が忙しいときは臨時にアルバイトを(　　)いる。","options":["つかんで","ふくんで","やとって","かせいで"],"answer":3,"word_explain":"雇う (やとう): thuê, tuyển dụng","translation_vi":"Khi cửa hàng bận rộn, chúng tôi thuê thêm nhân viên làm thêm tạm thời."},{"mondai":4,"q":20,"prompt":"誰にも言えずにずっと悩んでいたが、昨日親友に(　　)相談してみた。","options":["思しきって","うっかり","せっかく","知らず知らず"],"answer":1,"word_explain":"思いきって (おもいきって): lấy hết can đảm, đánh liều, quyết tâm (trong đề in nhầm là 思しきって)","translation_vi":"Tôi đã trăn trở mãi mà không nói được với ai, nhưng hôm qua tôi đã lấy hết can đảm thử tâm sự với người bạn thân."},{"mondai":5,"q":21,"prompt":"私の会社は<u>最寄り</u>の駅から歩いて15分です。","options":["一番大きい","一番近い","終点の","始発の"],"answer":2,"word_explain":"最寄り (もより) = 一番近い: gần nhất","translation_vi":"Công ty tôi cách nhà ga gần nhất 15 phút đi bộ."},{"mondai":5,"q":22,"prompt":"演奏会で着るドレスは、いつも近所の店で<u>レンタル</u>しています。","options":["作って","買って","直して","借りて"],"answer":4,"word_explain":"レンタル = 借りる (かりる): thuê, mượn","translation_vi":"Chiếc váy mặc trong buổi hòa nhạc tôi luôn thuê ở cửa hàng gần nhà."},{"mondai":5,"q":23,"prompt":"村上んはほかの人に<u>指図</u>されるのが嫌いだそうだ。","options":["命令","反対","注意","自慢"],"answer":1,"word_explain":"指図 (さしず) = 命令 (めいれい): chỉ đạo, sai khiến, ra lệnh","translation_vi":"Nghe nói anh/chị Murakami ghét bị người khác sai khiến."},{"mondai":5,"q":24,"prompt":"この時期に旅行するなら、かさは<u>欠かせない</u>。","options":["ないといい","あるとじゃまだ","ないと困る","あると便利だ"],"answer":3,"word_explain":"欠かせない (かかせない) = ないと困る: không thể thiếu, không có là rắc rối","translation_vi":"Nếu đi du lịch vào thời điểm này thì không thể thiếu ô (dù) được."},{"mondai":5,"q":25,"prompt":"雨は<u>依然</u>強かった。","options":["確かに","まだ","意外に","とても"],"answer":2,"word_explain":"依然 (いぜん) = まだ: vẫn, vẫn còn (như trước)","translation_vi":"Trời mưa vẫn còn rất to."},{"mondai":6,"q":26,"prompt":"栽培","options":["両親は牧場で牛を<u>栽培</u>して、チーズを作っています","私は今、生まれて半年の赤ちやんを<u>栽培</u>しています","庭で見つけた虫の卵を<u>栽培</u>して、観察日記を書いた。","この畑では、農薬を使わずに野菜を<u>栽培</u>しています。"],"answer":4,"word_explain":"栽培 (さいばい): trồng trọt, canh tác (dùng cho cây trồng, rau củ, hoa quả)","translation_vi":"Ở mảnh ruộng này, người ta trồng rau mà không sử dụng thuốc trừ sâu."},{"mondai":6,"q":27,"prompt":"急激","options":["イベントの開催日が近くなり、準備が<u>急激</u>に進められている。","新しい駅ができて、市の人口が<u>急激</u>に増加している。","このパンは非常に人気があり、朝8時に開店すると<u>急激</u>に売れていく","松田選手が現れると、フアンの人たちが<u>急激</u>に取り囲んだ。"],"answer":2,"word_explain":"急激 (きゅうげき): đột ngột, nhanh chóng, dữ dội (dùng cho sự biến đổi mạnh về số lượng, mức độ như dân số, giá cả, thời tiết)","translation_vi":"Từ khi nhà ga mới được xây dựng, dân số của thành phố đang tăng lên một cách nhanh chóng."},{"mondai":6,"q":28,"prompt":"漏れる","options":["ジュースを注ぎすぎて、コップから<u>漏れて</u>しまった。","転んでしまって、ひざから血が<u>漏れて</u>きた。","水道管に穴があいているのか、水が<u>漏れて</u>きている。","悲しい映面を見たせいで、涙が<u>漏れて</u>きた。"],"answer":3,"word_explain":"漏れる (もれる): rò rỉ, lọt ra ngoài (nước, khí ga, ánh sáng, thông tin qua khe hở hoặc lỗ thủng)","translation_vi":"Có lẽ ống nước bị thủng lỗ rồi nên nước đang bị rò rỉ ra."},{"mondai":6,"q":29,"prompt":"傾向","options":["ファッション誌によると、今年は黄色が<u>傾向</u>するそうだ。","最近では、家族がばらばらに食事をする<u>傾向</u>がある。","姉は日本文学の研究に<u>傾向</u>している。","この坂は<u>傾向</u>がきつくて、自転車だとつらい。"],"answer":2,"word_explain":"傾向 (けいこう): xu hướng, khuynh hướng (thường dùng với 傾向がある / 傾向にある)","translation_vi":"Gần đây có xu hướng các thành viên trong gia đình ăn cơm riêng lẻ không cùng nhau."},{"mondai":6,"q":30,"prompt":"さっさと","options":["いつまでもテレビを見てないで、<u>さっさと</u>宿題をしなさい。","雷が鳴り出したと思ったら、<u>さっさと</u>雨が降り出した。","<u>さっさと</u>着くので、もう少しそこで待っていてください","買ってまだ一週間なのに、<u>さっさと</u>壊れた。"],"answer":1,"word_explain":"さっさと: nhanh chóng, lẹ làng (dùng cho hành động có chủ ý, thường mang sắc thái thúc giục)","translation_vi":"Đừng xem tivi mãi thế, mau làm bài tập về nhà đi."}]},{"id":"2021_07","displayName":"07/2021","sourceFile":"2021_7_N2.pdf","questions":[{"mondai":1,"q":1,"prompt":"海外市場に進出するために販売部門を<u>拡充</u>した。","options":["こうじゅ","かくじゅ","こうじゅう","かくじゅう"],"answer":4,"word_explain":"拡充 (かくじゅう): mở rộng và tăng cường (quy mô, nội dung)","translation_vi":"Để tiến vào thị trường nước ngoài, công ty đã mở rộng và tăng cường bộ phận bán hàng."},{"mondai":1,"q":2,"prompt":"近年、科学技術は<u>著しい</u>進歩を見せている。","options":["かやぶかしい","かがやかしい","いちじるしい","いちるじしい"],"answer":3,"word_explain":"著しい (いちじるしい): rõ rệt, đáng kể, vượt bậc","translation_vi":"Những năm gần đây, khoa học kỹ thuật đang cho thấy những bước tiến rõ rệt."},{"mondai":1,"q":3,"prompt":"みなさんの<u>声援</u>に力づけられました。","options":["せいえん","しえん","せいいん","しいん"],"answer":1,"word_explain":"声援 (せいえん): sự cổ vũ, reo hò khích lệ","translation_vi":"Tôi đã được tiếp thêm sức mạnh nhờ sự cổ vũ của mọi người."},{"mondai":1,"q":4,"prompt":"いつのまにか<u>傾いて</u>いました。","options":["きずついて","かたむいて","かわいて","ういて"],"answer":2,"word_explain":"傾く (かたむく): nghiêng, đổ nghiêng","translation_vi":"Không biết từ lúc nào mà nó đã bị nghiêng mất rồi."},{"mondai":1,"q":5,"prompt":"ガラスの<u>破片</u>が落ちているから、気をつけてください。","options":["ひがた","はがた","ひへん","はへん"],"answer":4,"word_explain":"破片 (はへん): mảnh vỡ (lưu ý: bản PDF in thiếu thành はん)","translation_vi":"Có mảnh vỡ thủy tinh rơi ở đó nên xin hãy cẩn thận."},{"mondai":2,"q":6,"prompt":"私の故郷は自然が<u>ゆたか</u>なところです。","options":["豊か","恵か","富か","福か"],"answer":1,"word_explain":"豊か (ゆたか): phong phú, dồi dào, trù phú","translation_vi":"Quê hương của tôi là một nơi có thiên nhiên trù phú."},{"mondai":2,"q":7,"prompt":"この店の商品は、買ってから一週間以内なら<u>へんぴん</u>できます。","options":["返品","変品","逆品","戻品"],"answer":1,"word_explain":"返品 (へんぴん): việc trả lại hàng đã mua","translation_vi":"Sản phẩm của cửa hàng này có thể trả lại trong vòng 1 tuần kể từ ngày mua."},{"mondai":2,"q":8,"prompt":"道具を<u>らんぼう</u>に使ってはいけません。","options":["荒暴","乱暴","乱亡","荒亡"],"answer":2,"word_explain":"乱暴 (らんぼう): thô bạo, mạnh tay, ẩu tả","translation_vi":"Không được sử dụng dụng cụ một cách thô bạo (ẩu tả)."},{"mondai":2,"q":9,"prompt":"この二人はライバルとして常に<u>きそって</u>きた。","options":["争って","戦って","競って","討って"],"answer":3,"word_explain":"競う (きそう): cạnh tranh, ganh đua","translation_vi":"Hai người này luôn cạnh tranh với nhau với tư cách là đối thủ."},{"mondai":2,"q":10,"prompt":"特に目立った<u>じゃくてん</u>はない。","options":["悪点","欠点","低点","弱点"],"answer":4,"word_explain":"弱点 (じゃくてん): điểm yếu, nhược điểm","translation_vi":"Đặc biệt là không có điểm yếu nào nổi bật."},{"mondai":3,"q":11,"prompt":"この動物は、敵に襲われると、体をボール(　　)に丸めて身を守る。","options":["式","感","状","性"],"answer":3,"word_explain":"ボール状 (ボールじょう): có hình dạng quả bóng (~状: dạng ~)","translation_vi":"Loài động vật này khi bị kẻ thù tấn công sẽ cuộn tròn cơ thể lại thành hình quả bóng để tự vệ."},{"mondai":3,"q":12,"prompt":"明日のシンポジウムは(　　)会場で行われるので、ご注意ください。","options":["離","違","別","補"],"answer":3,"word_explain":"別会場 (べつかいじょう): hội trường khác, địa điểm khác","translation_vi":"Hội thảo chuyên đề ngày mai sẽ được tổ chức ở một hội trường khác nên xin hãy lưu ý."},{"mondai":3,"q":13,"prompt":"あの会社は、(　　)社長になってから経営方針が変わった。","options":["現","直","近","今"],"answer":1,"word_explain":"現社長 (げんしゃちょう): giám đốc hiện tại (đương nhiệm)","translation_vi":"Công ty đó đã thay đổi phương châm kinh doanh kể từ khi giám đốc hiện tại lên nắm quyền."},{"mondai":4,"q":14,"prompt":"最近、物価が(　　)している。","options":["増加","上達","増大","上昇"],"answer":4,"word_explain":"上昇 (じょうしょう): sự tăng lên, leo thang (giá cả, nhiệt độ, tỷ lệ...)","translation_vi":"Gần đây, giá cả đang tăng lên."},{"mondai":4,"q":15,"prompt":"ちょうどいい(　　)で警官が通りかかったので、助かった。","options":["タイマー","アクシデント","タイミング","アクション"],"answer":3,"word_explain":"タイミング: thời điểm, đúng lúc (timing)","translation_vi":"May quá, đúng lúc có cảnh sát đi ngang qua nên tôi đã được cứu."},{"mondai":4,"q":16,"prompt":"遠慮はいらないので、いつでも(　　)声をかけてください。","options":["無事に","気軽に","率直に","器用に"],"answer":2,"word_explain":"気軽に (きがるに): một cách thoải mái, không ngại ngùng","translation_vi":"Không cần khách sáo đâu, lúc nào cũng hãy thoải mái bắt chuyện với tôi nhé."},{"mondai":4,"q":17,"prompt":"Eメールに(　　)されたファイルが開けない。","options":["輸送","付属","郵送","添付"],"answer":4,"word_explain":"添付 (てんぷ): đính kèm (tệp tin, tài liệu)","translation_vi":"Tôi không mở được tệp được đính kèm trong email."},{"mondai":4,"q":18,"prompt":"そんなに人のことを(　　)見るものではありませんよ。","options":["じろじろ","たまたま","さっさと","うっかり"],"answer":1,"word_explain":"じろじろ: nhìn chằm chằm, nhìn săm soi","translation_vi":"Không nên nhìn chằm chằm vào người khác như vậy đâu."},{"mondai":4,"q":19,"prompt":"その選手は体力の(　　)している。","options":["制限","限界","境界","境目"],"answer":2,"word_explain":"限界 (げんかい): giới hạn (bản PDF in thiếu chữ trước している)","translation_vi":"Vận động viên đó đã đạt đến giới hạn thể lực của mình."},{"mondai":4,"q":20,"prompt":"彼はその出来事がきっかけで、医者になる決意を(　　)。","options":["固めた","まとめた","仕上げた","合わせた"],"answer":1,"word_explain":"固める (かためる): củng cố, hạ (cụm 決意を固める: hạ quyết tâm)","translation_vi":"Nhờ sự kiện đó làm bước ngoặt, anh ấy đã hạ quyết tâm trở thành bác sĩ."},{"mondai":5,"q":21,"prompt":"あの人の冷たい態度には<u>失望した</u>。","options":["がっかりした","びっくりした","かっとした","ぞっとした"],"answer":1,"word_explain":"失望する (しつぼうする) = がっかりする: thất vọng","translation_vi":"Tôi đã thất vọng trước thái độ lạnh nhạt của người đó."},{"mondai":5,"q":22,"prompt":"すぐに仕事に<u>とりかかります</u>。","options":["仕事を探します","仕事を始めます","仕事を教えます","仕事を頼みます"],"answer":2,"word_explain":"とりかかる (取り掛かる) = 始める: bắt tay vào, bắt đầu làm","translation_vi":"Tôi sẽ bắt tay vào công việc ngay lập tức."},{"mondai":5,"q":23,"prompt":"手書きの文字には書いた人の<u>人柄</u>が出る。","options":["格好","体調","気分","性格"],"answer":4,"word_explain":"人柄 (ひとがら) = 性格: nhân cách, tính cách, con người","translation_vi":"Trong nét chữ viết tay thể hiện tính cách (con người) của người viết."},{"mondai":5,"q":24,"prompt":"スピーチは<u>案の定</u>うまくできなかった。","options":["あまり","あいかわらず","やっぱり","ぜんぜん"],"answer":3,"word_explain":"案の定 (あんのじょう) = やっぱり: quả nhiên, đúng như dự đoán/lo ngại","translation_vi":"Quả nhiên là tôi đã không thể phát biểu tốt được."},{"mondai":5,"q":25,"prompt":"ごみを<u>くるんで</u>捨てた。","options":["縛って","集めて","分けて","包んで"],"answer":4,"word_explain":"くるむ (包む) = 包んで: gói lại, bọc lại","translation_vi":"Tôi đã gói rác lại rồi vứt đi."},{"mondai":6,"q":26,"prompt":"引用","options":["プレゼンがうまい先輩のやり方を<u>引用</u>する。","大きな川から水を<u>引用</u>する。","レポートで、新聞記事を<u>引用</u>する。","ほかの人のお金を<u>引用</u>してはいけない。"],"answer":3,"word_explain":"引用 (いんよう): trích dẫn (lời nói, bài viết, tư liệu của người khác vào bài viết/phát biểu của mình)","translation_vi":"Trích dẫn bài báo trong bài báo cáo."},{"mondai":6,"q":27,"prompt":"ほっと","options":["<u>ほっと</u>気づいたら、ポケットの中のかぎがなかった。","会議中に<u>ほっと</u>していたら、上司に注意された。","好きな人に話しかけられて、<u>ほっと</u>顔が赤くなった。","なくしたと思った大事な本が見つかって、<u>ほっと</u>した。"],"answer":4,"word_explain":"ほっと: nhẹ nhõm, thở phào (thường dùng ほっとする khi hết lo lắng, căng thẳng)","translation_vi":"Tìm thấy quyển sách quan trọng tưởng đã làm mất nên tôi thở phào nhẹ nhõm."},{"mondai":6,"q":28,"prompt":"展開","options":["高橋教授は、この島で生物の<u>展開</u>の歴史を調べている。","この漫画は、ストーリーの<u>展開</u>が面白い。","好きなことをしているときは、時間の<u>展開</u>が早い。","池田選手はとても強く、5年連続で決勝戦への<u>展開</u>を決めている。"],"answer":2,"word_explain":"展開 (てんかい): diễn biến, sự phát triển (cốt truyện, tình hình); triển khai (kế hoạch, kinh doanh)","translation_vi":"Bộ truyện tranh này có diễn biến cốt truyện rất thú vị."},{"mondai":6,"q":29,"prompt":"妥当","options":["品質に比べて値段が高いと言う人もいるが、私は<u>妥当</u>な金額だと思う。","風邪気味だったので、今日の会議が中止になったのは、私には<u>妥当</u>だった。","旅行の日は雨の予報だったが、きれいに晴れて、<u>妥当</u>な天気になった。","この曲は、歌詞が今の私の気持ちに<u>妥当</u>なので、最近よく聞いている。"],"answer":1,"word_explain":"妥当 (だとう): thỏa đáng, hợp lý, phù hợp (mức giá, nhận định, phán đoán...)","translation_vi":"Cũng có người nói giá đắt so với chất lượng, nhưng tôi nghĩ đó là mức giá hợp lý."},{"mondai":6,"q":30,"prompt":"かばう","options":["この団体は、海岸の清掃など、環境を<u>かばう</u>活動をしている。","この鳥は法律で<u>かばわれて</u>いて、捕まえたり飼ったりすることは禁止されている。","弟が両親にしかられていたので、「すごく反省してたよ」と言って、弟を<u>かばった</u>。","開発した新技術を<u>かばう</u>ため、関連する情報を厳重に管理している。"],"answer":3,"word_explain":"かばう (庇う): che chở, bênh vực, bao che (cho người khác khỏi bị trách mắng, tổn thương)","translation_vi":"Vì em trai bị bố mẹ mắng nên tôi đã nói \"Em ấy đã hối lỗi lắm rồi\" để bênh vực cho em ấy."}]},{"id":"2020_12","displayName":"12/2020","sourceFile":"N2 T12-2020.pdf","questions":[{"mondai":1,"q":1,"prompt":"<u>倒さない</u>ように気をつけてください。","options":["くずさない","たおさない","こわさない","つぶさない"],"answer":2,"word_explain":"倒さない (たおさない): không làm đổ, không đánh ngã","translation_vi":"Hãy cẩn thận để không làm đổ."},{"mondai":1,"q":2,"prompt":"今回の件での<u>損害</u>は数千万円にのぼった。","options":["ひかい","そんかい","そんがい","ひがい"],"answer":3,"word_explain":"損害 (そんがい): tổn hại, thiệt hại","translation_vi":"Thiệt hại trong vụ việc lần này đã lên tới hàng chục triệu yên."},{"mondai":1,"q":3,"prompt":"思ったより<u>険しい</u>山道だった。","options":["くるしい","さびしい","はげしい","けわしい"],"answer":4,"word_explain":"険しい (けわしい): hiểm trở, dốc đứng, gắt gao","translation_vi":"Đó là con đường núi hiểm trở hơn tôi nghĩ."},{"mondai":1,"q":4,"prompt":"この辺りは<u>比較的</u>人通りが少ない。","options":["ひこうてい","ひこてき","ひかくてき","ひかてき"],"answer":3,"word_explain":"比較的 (ひかくてき): tương đối, khá là","translation_vi":"Quanh khu vực này tương đối ít người qua lại."},{"mondai":1,"q":5,"prompt":"飛行機は<u>下降</u>を始めた。","options":["かこう","かくう","げこう","げくう"],"answer":1,"word_explain":"下降 (かこう): sự hạ xuống, giảm xuống","translation_vi":"Máy bay đã bắt đầu hạ độ cao."},{"mondai":2,"q":6,"prompt":"鈴木さんは<u>あざやか</u>な色のシャツを着ていた。","options":["鮮やか","美やか","清やか","純やか"],"answer":1,"word_explain":"鮮やか (あざやか): tươi sáng, rực rỡ, sắc nét","translation_vi":"Anh Suzuki mặc một chiếc áo sơ mi có màu sắc rực rỡ."},{"mondai":2,"q":7,"prompt":"今年の夏休みは<u>きせい</u>の予定はありません。","options":["帰勢","帰斉","帰省","帰成"],"answer":3,"word_explain":"帰省 (きせい): về quê thăm gia đình","translation_vi":"Kỳ nghỉ hè năm nay tôi không có dự định về quê."},{"mondai":2,"q":8,"prompt":"もう少し<u>ちぢめて</u>ください。","options":["薄めて","納めて","貯めて","縮めて"],"answer":4,"word_explain":"縮めて (ちぢめて): thu nhỏ lại, rút ngắn lại (từ 縮める)","translation_vi":"Hãy thu ngắn (hoặc co/rút gọn) lại thêm một chút nữa."},{"mondai":2,"q":9,"prompt":"これからさまざまことを<u>じっせん</u>していきたい。","options":["実施","実践","実桟","実旋"],"answer":2,"word_explain":"実践 (じっせん): thực tiễn, thực hành áp dụng vào thực tế","translation_vi":"Từ nay về sau tôi muốn thực hành nhiều điều khác nhau."},{"mondai":2,"q":10,"prompt":"西村氏の作品の中ではこの小説は、かなり<u>いしょく</u>だ。","options":["異色","違色","異食","違食"],"answer":1,"word_explain":"異色 (いしょく): dị sắc, độc đáo, khác lạ so với thông thường","translation_vi":"Trong các tác phẩm của ông Nishimura, cuốn tiểu thuyết này khá là độc đáo khác biệt."},{"mondai":3,"q":11,"prompt":"宿題を(　　)提出するよう、先生に言われた。","options":["復","改","再","補"],"answer":3,"word_explain":"再提出 (さいていしゅつ): nộp lại","translation_vi":"Tôi được giáo viên bảo hãy nộp lại bài tập về nhà."},{"mondai":3,"q":12,"prompt":"あの人は都会(　　)だ。","options":["育ち","過ごし","始まり","生き"],"answer":1,"word_explain":"都会育ち (とかいそだち): người lớn lên ở thành thị","translation_vi":"Người đó là người lớn lên ở thành phố."},{"mondai":3,"q":13,"prompt":"(　　)仕事終わったので、休憩しよう。","options":["半","短","小","一"],"answer":4,"word_explain":"一仕事 (ひとしごと): một phần việc, một chặp công việc","translation_vi":"Vì đã xong một mẻ công việc rồi nên chúng ta nghỉ giải lao thôi."},{"mondai":4,"q":14,"prompt":"彼の演技はとても個人的で、見る人の(　　)が大きく分かれる。","options":["考慮","評価","信頼","測定"],"answer":2,"word_explain":"評価 (ひょうか): sự đánh giá","translation_vi":"Diễn xuất của anh ấy mang tính cá nhân rất cao, nên sự đánh giá của người xem chia rẽ rất lớn."},{"mondai":4,"q":15,"prompt":"話し合いでは、相手の意見を(　　)し、よく聞くことが大切だ。","options":["尊重","信仰","提案","発揮"],"answer":1,"word_explain":"尊重 (そんちょう): tôn trọng","translation_vi":"Trong cuộc thảo luận, điều quan trọng là tôn trọng ý kiến của đối phương và lắng nghe kỹ."},{"mondai":4,"q":16,"prompt":"この商品は、健康を気にする40代から50代の人を(　　)に開発しました。","options":["ゴール","インパクト","アピール","ターゲット"],"answer":4,"word_explain":"ターゲット: mục tiêu, đối tượng hướng đến (target)","translation_vi":"Sản phẩm này được phát triển hướng tới đối tượng mục tiêu là những người ở độ tuổi 40 đến 50 quan tâm đến sức khỏe."},{"mondai":4,"q":17,"prompt":"佐藤さんは服装や髪形が個性的で、他の人とは違う(　　)の雰囲気がある。","options":["定着","専用","独特","区別"],"answer":3,"word_explain":"独特 (どくとく): độc đáo, riêng biệt","translation_vi":"Chị Sato có trang phục và kiểu tóc đầy cá tính, toát lên bầu không khí độc đáo khác với những người khác."},{"mondai":4,"q":18,"prompt":"前回の大会では、あの二人は最後まで優勝を(　　)していた。","options":["戦って","争って","奪って","破って"],"answer":2,"word_explain":"争って (あらそって): tranh giành, cạnh tranh (優勝を争う: tranh chức vô địch)","translation_vi":"Ở giải đấu lần trước, hai người đó đã tranh giành chức vô địch đến tận phút cuối."},{"mondai":4,"q":19,"prompt":"高橋さんの家を訪ねたが、みんな出かけているようで、人の(　　)がなかった。","options":["動作","実感","気配","状態"],"answer":3,"word_explain":"気配 (けはい): dấu hiệu, cảm giác có sự hiện diện (人の気配: hơi người/dấu hiệu có người)","translation_vi":"Tôi đã đến thăm nhà anh Takahashi nhưng hình như mọi người đều ra ngoài cả nên không có dấu hiệu có người."},{"mondai":4,"q":20,"prompt":"彼は自分で決めたルールも守らない、(　　)人だ。","options":["不規則な","あやふやな","大まかな","いいかげんな"],"answer":4,"word_explain":"いいかげんな: cẩu thả, tùy tiện, thiếu trách nhiệm","translation_vi":"Anh ta là người cẩu thả, vô trách nhiệm, đến cả quy tắc do chính mình đặt ra cũng không tuân thủ."},{"mondai":5,"q":21,"prompt":"ボランティアで町の名所を<u>ガイド</u>している。","options":["案内して","宣伝して","調査して","記録して"],"answer":1,"word_explain":"ガイド (hướng dẫn) = 案内 (あんない): dẫn đường, hướng dẫn","translation_vi":"Tôi đang làm tình nguyện hướng dẫn tham quan các danh lam thắng cảnh của thị trấn."},{"mondai":5,"q":22,"prompt":"山口さんも<u>真剣に</u>作っていた。","options":["上手に","自由に","積極的に","まじめに"],"answer":4,"word_explain":"真剣に (しんけんに) = まじめに: nghiêm túc, chuyên tâm","translation_vi":"Anh Yamaguchi cũng đã làm một cách nghiêm túc."},{"mondai":5,"q":23,"prompt":"彼女のような歌手は<u>まれだ</u>と思う。","options":["あまりいない","人気が出ない","人気が出る","たくさんいる"],"answer":1,"word_explain":"まれだ (hiếm có) = あまりいない: không có nhiều, hiếm thấy","translation_vi":"Tôi nghĩ một ca sĩ như cô ấy rất hiếm có."},{"mondai":5,"q":24,"prompt":"この道は<u>終日</u>通行止めです。","options":["週末","夜間","一日中","今日まで"],"answer":3,"word_explain":"終日 (しゅうじつ) = 一日中 (いちにちじゅう): suốt cả ngày","translation_vi":"Con đường này cấm lưu thông cả ngày."},{"mondai":5,"q":25,"prompt":"青木さんは髪を<u>いじって</u>いた。","options":["切って","触って","洗って","乾かして"],"answer":2,"word_explain":"いじる (nghịch, mân mê) = 触る (さわる): chạm vào, sờ vào","translation_vi":"Bạn Aoki đã cứ sờ nghịch tóc mãi."},{"mondai":6,"q":26,"prompt":"初期","options":["曲の<u>初期</u>の部分を聞いただけで、題名が何かわかりました。","この建物は有名な建築物で、明治時代の<u>初期</u>に建てられました。","池田選手は、試合の<u>初期</u>では負けていたが、最後には勝つことができた。","今日は朝から雲に覆われ、<u>初期</u>は雨だったが、途中から雪に変わった。"],"answer":2,"word_explain":"初期 (しょき): thời kỳ đầu, giai đoạn đầu (dùng cho thời đại lịch sử, bệnh tật hoặc hiện tượng kéo dài; không dùng cho bản nhạc, trận đấu hay thời tiết trong ngày)","translation_vi":"Tòa nhà này là một công trình kiến trúc nổi tiếng, được xây dựng vào thời kỳ đầu của thời đại Minh Trị."},{"mondai":6,"q":27,"prompt":"打ち明ける","options":["仕事でわからないことがあれば、彼が何でも<u>打ち明けて</u>くれます。","谷口さんが戻ってきたら、伝言を<u>打ち明けて</u>おいてもらえますか。","大事な情報はすぐに上司に<u>打ち明け</u>ましょう。","ずっと秘密にしていたことを友達に<u>打ち明けた</u>。"],"answer":4,"word_explain":"打ち明ける (うちあける): thổ lộ, tâm sự thẳng thắn điều bí mật hoặc nỗi lòng cho người khác biết","translation_vi":"Tôi đã thổ lộ với bạn điều mà mình giữ bí mật bấy lâu nay."},{"mondai":6,"q":28,"prompt":"欠陥","options":["あの人の<u>欠陥</u>は、自分に都合の悪いことがあるとうそをつくことだ。","眼鏡のレンズを硬い布でふいたら、<u>欠陥</u>がついてしまった。","先月発表された車のブレーキに<u>欠陥</u>が見つかり、販売が中止された。","このサービスを利用することの<u>欠陥</u>は費用が非常にかかることだ。"],"answer":3,"word_explain":"欠陥 (けっかん): khiếm khuyết, lỗi kỹ thuật/cấu trúc (ở sản phẩm, hệ thống, cơ thể; không dùng cho thói xấu cá nhân, vết xước hay nhược điểm chi phí)","translation_vi":"Phanh của chiếc xe ô tô được công bố tháng trước bị phát hiện có lỗi kỹ thuật nên việc bán hàng đã bị đình chỉ."},{"mondai":6,"q":29,"prompt":"引退","options":["山本さんは去年入学したばかりの大学を<u>引退</u>し、別の大学を受験するらしい。","これまで多くの名作を残した映画監督が、今回限り<u>引退</u>することを発表した。","この書店はもうすぐ商店街から<u>引退</u>し、駅前のビルの中で店を始めるらしい。","中村選手は前大会でのけがが回復せず、次の試合への出場を<u>引退</u>した。"],"answer":2,"word_explain":"引退 (いんたい): giải nghệ, rút lui hoàn toàn khỏi nghề nghiệp/vị trí/sự nghiệp (không dùng cho việc bỏ học đại học, chuyển địa điểm cửa hàng hay rút khỏi một trận đấu)","translation_vi":"Vị đạo diễn điện ảnh từng để lại nhiều kiệt tác đến nay đã tuyên bố giải nghệ sau lần này."},{"mondai":6,"q":30,"prompt":"ぎっしり","options":["大きな箱に本が<u>ぎっしり</u>詰まっている。","ジュースがコップに<u>ぎっしり</u>入っている。","少し太ったせいで、ズボンが<u>ぎっしり</u>している。","朝の電車はいつも人で<u>ぎっしり</u>している。"],"answer":1,"word_explain":"ぎっしり: chật ních, dày đặc, đầy ắp không còn kẽ hở (dùng với vật rắn, chữ viết, lịch trình, kết hợp với 詰まっている/並んでいる; không dùng cho chất lỏng hay dạng ぎっしりしている)","translation_vi":"Sách được xếp chật ních, đầy ắp trong chiếc hộp lớn."}]},{"id":"2019_12","displayName":"12/2019","sourceFile":"N2_T7_2019.pdf","questions":[{"mondai":1,"q":1,"prompt":"木村さんは誰に対しても<u>等しく</u>接する人だ。","options":["やさしく","ひとしく","したしく","きびしく"],"answer":2,"word_explain":"等しく (ひとしく): một cách bình đẳng, như nhau","translation_vi":"Anh/chị Kimura là người đối xử bình đẳng với bất kỳ ai."},{"mondai":1,"q":2,"prompt":"石川さんのけがは、<u>軽傷</u>だったらしい。","options":["けいしょう","けいそう","けしょう","けそう"],"answer":1,"word_explain":"軽傷 (けいしょう): vết thương nhẹ","translation_vi":"Vết thương của anh/chị Ishikawa có vẻ chỉ là vết thương nhẹ."},{"mondai":1,"q":3,"prompt":"費用はみんなで<u>負担</u>した。","options":["ぶんてん","ふてん","ぶんたん","ふたん"],"answer":4,"word_explain":"負担 (ふたん): gánh vác, chịu (chi phí, trách nhiệm)","translation_vi":"Mọi người đã cùng nhau chi trả (gánh vác) chi phí."},{"mondai":1,"q":4,"prompt":"湖に<u>映った</u>夕日がきれいだ。","options":["あたった","ひかった","てった","うつった"],"answer":4,"word_explain":"映った (うつった): phản chiếu, in bóng","translation_vi":"Ánh hoàng hôn phản chiếu xuống mặt hồ thật đẹp."},{"mondai":1,"q":5,"prompt":"9月の<u>下旬</u>に旅行に行く予定です。","options":["げしゅん","かじゅん","げじゅん","かしゅん"],"answer":3,"word_explain":"下旬 (げじゅん): hạ tuần (10 ngày cuối tháng)","translation_vi":"Tôi dự định sẽ đi du lịch vào cuối (hạ tuần) tháng 9."},{"mondai":2,"q":6,"prompt":"その行為は交通ルールに<u>いはん</u>します。","options":["偉判","偉反","違判","違反"],"answer":4,"word_explain":"違反 (いはん): vi phạm","translation_vi":"Hành vi đó vi phạm luật giao thông."},{"mondai":2,"q":7,"prompt":"<u>いさましい</u>声が聞こえてきた。","options":["戦ましい","勇ましい","騒ましい","勢ましい"],"answer":2,"word_explain":"勇ましい (いさましい): dũng mãnh, hào hùng, mạnh mẽ","translation_vi":"Tôi nghe thấy tiếng hô (giọng nói) đầy dũng mãnh vọng lại."},{"mondai":2,"q":8,"prompt":"その店には<u>ようき</u>な音楽が流れていた。","options":["揚起","揚気","陽気","陽起"],"answer":3,"word_explain":"陽気 (ようき): vui tươi, sôi nổi, rộn ràng","translation_vi":"Trong cửa hàng đó đang phát nhạc vui tươi."},{"mondai":2,"q":9,"prompt":"楽しみにしていたドラマを<u>みのがして</u>しまった。","options":["見逃して","見延して","見欠して","見去して"],"answer":1,"word_explain":"見逃す (みのがす): bỏ lỡ (cơ hội, chương trình)","translation_vi":"Tôi đã lỡ mất bộ phim truyền hình mà mình hằng mong đợi."},{"mondai":2,"q":10,"prompt":"来月から、道路を<u>かくちょう</u>するための工事が始まる。","options":["拡張","広張","拡長","広長"],"answer":1,"word_explain":"拡張 (かくちょう): mở rộng, khuếch trương","translation_vi":"Từ tháng sau, công trình mở rộng đường sẽ bắt đầu."},{"mondai":3,"q":11,"prompt":"この建物は(　　)町長の時代に建てられたものだ。","options":["先","古","前","昔"],"answer":3,"word_explain":"前町長 (ぜんちょうちょう): cựu trưởng thị trấn (nhiệm kỳ trước)","translation_vi":"Tòa nhà này được xây dựng vào thời của vị trưởng thị trấn nhiệm kỳ trước."},{"mondai":3,"q":12,"prompt":"池田さんには何度も助けてもらっているので、今回は頼み(　　)。","options":["づらい","わるい","きつい","よわい"],"answer":1,"word_explain":"頼みづらい (たのみづらい): khó mở lời nhờ vả","translation_vi":"Vì đã được anh/chị Ikeda giúp đỡ nhiều lần rồi nên lần này thật khó mà mở lời nhờ vả."},{"mondai":3,"q":13,"prompt":"この歌の歌詞は政治(　　)が強いように感じられる。","options":["香","風","味","色"],"answer":4,"word_explain":"政治色 (せいじしょく): màu sắc chính trị, tính chất chính trị","translation_vi":"Lời của bài hát này tạo cảm giác mang đậm màu sắc chính trị."},{"mondai":4,"q":14,"prompt":"今日は残業で疲れていて夕食を作るのが(　　)だから、外で食べて帰ろうと思う。","options":["余計","面倒","過剰","無力"],"answer":2,"word_explain":"面倒 (めんどう): phiền phức, ngại làm","translation_vi":"Hôm nay tăng ca mệt rồi nên ngại nấu bữa tối, tôi định ăn ngoài rồi về."},{"mondai":4,"q":15,"prompt":"この犬のロボットは動きが自然で、まるで(　　)の犬のようだ。","options":["本物","現状","事実","正式"],"answer":1,"word_explain":"本物 (ほんもの): đồ thật, hàng thật","translation_vi":"Con robot chó này chuyển động rất tự nhiên, trông cứ như một con chó thật vậy."},{"mondai":4,"q":16,"prompt":"山下先輩は私の(　　)で、いつか山下先輩のようになりたいと思っている。","options":["あこがれ","望み","願い","夢"],"answer":1,"word_explain":"あこがれ (憧れ): niềm ngưỡng mộ, hình mẫu ao ước","translation_vi":"Tiền bối Yamashita là hình mẫu tôi ngưỡng mộ, tôi mong một ngày nào đó sẽ trở thành người giống như anh/chị ấy."},{"mondai":4,"q":17,"prompt":"今日会社で京都支社から東京本社への(　　)を命じられ、今月末に東京へ引っ越すことになった。","options":["移行","転職","転勤","移住"],"answer":3,"word_explain":"転勤 (てんきん): chuyển công tác (sang chi nhánh/trụ sở khác trong cùng công ty)","translation_vi":"Hôm nay ở công ty tôi nhận lệnh chuyển công tác từ chi nhánh Kyoto lên trụ sở chính ở Tokyo, nên cuối tháng này sẽ chuyển nhà lên Tokyo."},{"mondai":4,"q":18,"prompt":"この辺りの農家は、無農薬で野菜を(　　)しています。","options":["制作","栽培","養成","製造"],"answer":2,"word_explain":"栽培 (さいばい): trồng trọt, canh tác","translation_vi":"Các hộ nông dân quanh đây đang trồng rau không dùng thuốc trừ sâu."},{"mondai":4,"q":19,"prompt":"彼は私の意見に対して何も言わなかったが、(　　)ことで同意を示してくれた。","options":["ふりむく","にらむ","かがむ","うなずく"],"answer":4,"word_explain":"うなずく (頷く): gật đầu","translation_vi":"Anh ấy không nói gì về ý kiến của tôi, nhưng đã gật đầu để thể hiện sự đồng tình."},{"mondai":4,"q":20,"prompt":"机の上がいろいろな物で(　　)しているから、早くきれいに片付けよう。","options":["きちんと","ぼんやり","ごちゃごちゃ","きょろきょろ"],"answer":3,"word_explain":"ごちゃごちゃ: bừa bộn, lộn xộn","translation_vi":"Trên bàn đang bừa bộn đủ thứ đồ đạc nên hãy mau dọn dẹp cho gọn gàng đi."},{"mondai":5,"q":21,"prompt":"この仕事はとても<u>ハードだ</u>。","options":["楽しい","簡単だ","大変だ","新しい"],"answer":3,"word_explain":"ハードだ = 大変だ (たいへんだ): vất vả, nặng nhọc, căng thẳng","translation_vi":"Công việc này rất vất vả (nặng nhọc)."},{"mondai":5,"q":22,"prompt":"その話を聞いて<u>動揺した</u>。","options":["うれしくなった","不安になった","不満に思った","面白いと思った"],"answer":2,"word_explain":"動揺した (どうようした) = 不安になった: dao động, bất an, bối rối","translation_vi":"Nghe câu chuyện đó xong tôi cảm thấy bất an (dao động)."},{"mondai":5,"q":23,"prompt":"早く<u>引き返した</u>ほうがいい。","options":["払った","直した","戻った","答えた"],"answer":3,"word_explain":"引き返した (ひきかえした) = 戻った (もどった): quay trở lại","translation_vi":"Tốt hơn là nên quay lại sớm đi."},{"mondai":5,"q":24,"prompt":"機能を<u>一層</u>強化したい。","options":["すぐに","少し","できるだけ","もっと"],"answer":4,"word_explain":"一層 (いっそう) = もっと: hơn nữa, càng thêm","translation_vi":"Tôi muốn tăng cường chức năng hơn nữa."},{"mondai":5,"q":25,"prompt":"急にひどい頭痛がしてきたので、<u>かかりつけの</u>病院に行った。","options":["いつも行く","休日も開いている","近くの","専門の"],"answer":1,"word_explain":"かかりつけの = いつも行く: quen thuộc, hay lui tới (bệnh viện/bác sĩ ruột)","translation_vi":"Vì đột nhiên bị đau đầu dữ dội nên tôi đã đến bệnh viện quen vẫn hay khám."},{"mondai":6,"q":26,"prompt":"特殊","options":["その日は夏なのに<u>特殊</u>な寒さだった。","自分で育てた野菜を食べるのは<u>特殊</u>な喜びがある。","母は誕生日など、<u>特殊</u>な日にはとても豪華な料理を作ってくれる。","バスを運転するためには<u>特殊</u>な免許が必要だ。"],"answer":4,"word_explain":"特殊 (とくしゅ): đặc thù, chuyên biệt (khác với thông thường; dùng cho kỹ thuật, bằng cấp, hoàn cảnh đặc thù, không dùng thay cho 特別 trong ngày kỷ niệm hay cảm xúc)","translation_vi":"Để lái xe buýt thì cần có giấy phép lái xe đặc biệt (chuyên dụng)."},{"mondai":6,"q":27,"prompt":"素材","options":["プラスチックは石油を<u>素材</u>に作られている。","このお店は<u>素材</u>の味を生かした料理で有名です。","いろいろな情報を集めて、判断の<u>素材</u>にする。","故障の<u>素材</u>になったものを探さなくてはいけない。"],"answer":2,"word_explain":"素材 (そざい): nguyên liệu, chất liệu (đặc biệt dùng cho nguyên liệu thực phẩm giữ hương vị tự nhiên hoặc chất liệu sáng tác; phân biệt với 原料 và 材料)","translation_vi":"Quán này nổi tiếng với các món ăn phát huy được hương vị tự nhiên của nguyên liệu."},{"mondai":6,"q":28,"prompt":"しみる","options":["飛んできたボールが頭に<u>しみて</u>、けがをした。","煙が目に<u>しみて</u>、涙が止まらなくなった。","食べすぎて、ベルトがおなかに<u>しみて</u>苦しい。","料理をしているときに包丁の先が指に<u>しみて</u>、少し血が出た。"],"answer":2,"word_explain":"しみる (染みる): thấm vào, làm cay/xót (như khói bay vào mắt gây cay mắt, thuốc thấm vào vết thương gây xót)","translation_vi":"Khói bay vào làm cay mắt khiến nước mắt cứ chảy không ngừng."},{"mondai":6,"q":29,"prompt":"充満","options":["この図書館は、あらゆる分野の本が<u>充満</u>していて、とても便利だ。","このコンサートは人気があって、常に観客が<u>充満</u>している。","部屋に食べ物の強いにおいが<u>充満</u>していたので、窓を開けた。","夢が<u>充満</u>している子どもたちが大好きで、小学校の教師になった。"],"answer":3,"word_explain":"充満 (じゅうまん): tràn ngập, đầy ắp (dùng cho khí, mùi hương, khói... lan tỏa kín một không gian)","translation_vi":"Vì mùi thức ăn nồng nặc tràn ngập khắp phòng nên tôi đã mở cửa sổ ra."},{"mondai":6,"q":30,"prompt":"めくる","options":["この小説は面白くて、次のページを<u>めくる</u>のが楽しみだった。","汗をかいたので、タオルを水でぬらし、きつく<u>めくって</u>体をふいた。","封筒に書類を入れ、開かないように丁寧にのりで<u>めくって</u>おいた。","そのドアは押すのではなくて手前に<u>めくらない</u>と開きませんよ。"],"answer":1,"word_explain":"めくる: lật, giở (trang sách, tờ lịch, tấm bạt...)","translation_vi":"Cuốn tiểu thuyết này hay đến nỗi tôi rất háo hức lật sang trang tiếp theo."}]},{"id":"2019_07","displayName":"07/2019","sourceFile":"N2 7-2019.pdf","questions":[{"mondai":1,"q":1,"prompt":"誰も<u>憎んで</u>なんていませんから、心配しないでください。","options":["なやんで","くやんで","うらんで","にくんで"],"answer":4,"word_explain":"憎んで (にくんで): ghét, căm ghét","translation_vi":"Không ai ghét bạn đâu, nên đừng lo lắng nhé."},{"mondai":1,"q":2,"prompt":"<u>偶然</u>、駅で友達に会った。","options":["とつぜん","ぐうぜん","ぐぜん","とぜん"],"answer":2,"word_explain":"偶然 (ぐうぜん): tình cờ, ngẫu nhiên","translation_vi":"Tôi tình cờ gặp bạn ở nhà ga."},{"mondai":1,"q":3,"prompt":"大学のゼミではいろいろな<u>刺激</u>を受けた。","options":["さてき","さげき","しげき","してき"],"answer":3,"word_explain":"刺激 (しげき): kích thích, nguồn cảm hứng","translation_vi":"Ở buổi hội thảo chuyên đề ở trường đại học, tôi đã nhận được nhiều nguồn cảm hứng (sự kích thích tư duy)."},{"mondai":1,"q":4,"prompt":"失敗して<u>恥</u>をかいたが、先輩の優しい一言に慰められた。","options":["はし","はじ","はず","はす"],"answer":2,"word_explain":"恥 (はじ): sự xấu hổ, nhục nhã (恥をかく: bị bẽ mặt)","translation_vi":"Dù thất bại và bị bẽ mặt, nhưng tôi đã được an ủi bởi lời nói dịu dàng của tiền bối."},{"mondai":1,"q":5,"prompt":"彼の強さは<u>圧倒的</u>だ。","options":["あっとうてき","おっとうてき","あつどうてき","おつどうてき"],"answer":1,"word_explain":"圧倒的 (あっとうてき): áp đảo, vượt trội hoàn toàn","translation_vi":"Sức mạnh của anh ấy thật sự áp đảo."},{"mondai":2,"q":6,"prompt":"私の<u>しゅみ</u>はピアノをひくことだ。","options":["趣味","興味","好味","習味"],"answer":1,"word_explain":"趣味 (しゅみ): sở thích","translation_vi":"Sở thích của tôi là chơi đàn piano."},{"mondai":2,"q":7,"prompt":"もう少し<u>こい</u>鉛筆が欲しい。","options":["軟い","薄い","硬い","濃い"],"answer":4,"word_explain":"濃い (こい): đậm, đặc","translation_vi":"Tôi muốn có cây bút chì đậm hơn một chút nữa."},{"mondai":2,"q":8,"prompt":"この皿は、真っ白ではなく、少し青が<u>まじった</u>ような色をしている。","options":["組じった","含じった","混じった","加じった"],"answer":3,"word_explain":"混じった (まじった): pha lẫn, trộn lẫn","translation_vi":"Chiếc đĩa này không phải màu trắng tinh, mà có màu hơi pha chút xanh."},{"mondai":2,"q":9,"prompt":"彼はいつも<u>そん</u>になることばかりしている。","options":["罪","害","損","毒"],"answer":3,"word_explain":"損 (そん): thiệt thòi, lỗ","translation_vi":"Anh ấy lúc nào cũng chỉ làm những việc khiến mình bị thiệt thòi."},{"mondai":2,"q":10,"prompt":"素晴らしい<u>えんぎ</u>に感動した。","options":["演劇","演技","園技","園劇"],"answer":2,"word_explain":"演技 (えんぎ): diễn xuất","translation_vi":"Tôi đã xúc động trước diễn xuất tuyệt vời."},{"mondai":3,"q":11,"prompt":"ゲームのしすぎは目に(　　)影響を与える。","options":["悪","重","高","大"],"answer":1,"word_explain":"悪影響 (あくえいきょう): ảnh hưởng xấu, tác hại","translation_vi":"Việc chơi game quá nhiều gây ảnh hưởng xấu đến mắt."},{"mondai":3,"q":12,"prompt":"彼はアメリカ(　　)のビジネスで成功した。","options":["形","質","性","流"],"answer":4,"word_explain":"アメリカ流 (アメリカりゅう): kiểu Mỹ, phong cách Mỹ","translation_vi":"Anh ấy đã thành công với mô hình kinh doanh kiểu Mỹ."},{"mondai":3,"q":13,"prompt":"別れ(　　)に、彼女は私に何か言ったが、聞こえなかった。","options":["刻","際","間","期"],"answer":2,"word_explain":"別れ際 (わかれぎわ): lúc chia tay, ngay trước khi chia tay","translation_vi":"Lúc chia tay, cô ấy có nói gì đó với tôi nhưng tôi không nghe rõ."},{"mondai":4,"q":14,"prompt":"予算もスタッフも希望通りにしたんだから成果を期待しているよと、上司に(　　)をかけられた。","options":["ショップ","プレッシャー","ダメージ","コンプレックス"],"answer":2,"word_explain":"プレッシャー: áp lực (プレッシャーをかける: gây áp lực)","translation_vi":"Cấp trên đã gây áp lực cho tôi bằng câu nói: \"Ngân sách và nhân sự đều đã làm theo đúng nguyện vọng của cậu rồi nên tôi rất kỳ vọng vào kết quả đấy\"."},{"mondai":4,"q":15,"prompt":"アルバイトの仕事は勤務が多い月と少ない月があって、毎月の収入が(　　)だ。","options":["不安定","不自由","不都合","不公平"],"answer":1,"word_explain":"不安定 (ふあんてい): không ổn định, bấp bênh","translation_vi":"Công việc làm thêm có tháng làm nhiều, tháng làm ít nên thu nhập hằng tháng không ổn định."},{"mondai":4,"q":16,"prompt":"彼は(　　)な返事をしていたから、パーティーに来るかどうかわからない。","options":["地味な","かすかな","あいまいな","鈍感な"],"answer":3,"word_explain":"あいまい: mơ hồ, mập mờ, không rõ ràng","translation_vi":"Vì anh ấy trả lời mập mờ nên không biết có đến bữa tiệc hay không."},{"mondai":4,"q":17,"prompt":"新しいことがなかなか覚えられないのは記憶力が(　　)からだろうか。","options":["傷んだ","散った","かれた","おとろえた"],"answer":4,"word_explain":"おとろえた (衰えた): suy giảm, yếu đi","translation_vi":"Việc khó nhớ được những điều mới mẻ phải chăng là do trí nhớ đã suy giảm?"},{"mondai":4,"q":18,"prompt":"相手が弱いと思って(　　)したら、負けてしまった。","options":["納得","油断","失望","覚悟"],"answer":2,"word_explain":"油断 (ゆだん): chủ quan, lơ là, mất cảnh giác","translation_vi":"Vì nghĩ đối thủ yếu nên tôi đã chủ quan, kết quả là bị thua."},{"mondai":4,"q":19,"prompt":"二人とも働いているので、家事や育児は夫婦で(　　)している。","options":["分別","区別","区分","分担"],"answer":4,"word_explain":"分担 (ぶんたん): phân công, chia sẻ (công việc)","translation_vi":"Vì cả hai cùng đi làm nên vợ chồng chia sẻ việc nhà và nuôi dạy con cái."},{"mondai":4,"q":20,"prompt":"次の社長に最も(　　)人は、経験豊富な鈴木さんでしょう。","options":["ふさわしい","等しい","ありがちな","当たり前な"],"answer":1,"word_explain":"ふさわしい: phù hợp, thích hợp, xứng đáng","translation_vi":"Người phù hợp nhất cho vị trí giám đốc tiếp theo có lẽ là anh Suzuki giàu kinh nghiệm."},{"mondai":5,"q":21,"prompt":"この辺りも<u>物騒に</u>なってきた気がする。","options":["きれいじゃなくなってきた","うるさくなってきた","安全じゃなくなったてきた","さびしくなってきた"],"answer":3,"word_explain":"物騒 (ぶっそう) = 安全じゃない: bất ổn, nguy hiểm, mất an toàn","translation_vi":"Tôi có cảm giác khu vực quanh đây cũng trở nên mất an toàn rồi."},{"mondai":5,"q":22,"prompt":"その話を聞いて<u>落ち込んだ</u>。","options":["緊張した","びっくりした","がっかりした","心配した"],"answer":3,"word_explain":"落ち込む (おちこむ) = がっかりする: chán nản, suy sụp, thất vọng","translation_vi":"Nghe câu chuyện đó xong, tôi cảm thấy chán nản (hụt hẫng)."},{"mondai":5,"q":23,"prompt":"<u>精いっぱい</u>やったのに、あまり評価されなかった。","options":["せっかく","一生懸命","いろいろ","何回も"],"answer":2,"word_explain":"精いっぱい (せいいっぱい) = 一生懸命 (いっしょうけんめい): hết sức mình, dốc toàn lực","translation_vi":"Dù đã cố gắng hết sức nhưng tôi lại không được đánh giá cao."},{"mondai":5,"q":24,"prompt":"その話を聞いて、みんな<u>同情した</u>。","options":["しかたないと思った","うらやましいと思った","なつかしいと思った","かわいそうだと思った"],"answer":4,"word_explain":"同情する (どうじょうする) = かわいそうだと思う: đồng cảm, thương cảm","translation_vi":"Nghe câu chuyện đó, mọi người đều cảm thấy thương cảm."},{"mondai":5,"q":25,"prompt":"条件を<u>定める</u>必要がある。","options":["決める","伝える","調べる","合わせる"],"answer":1,"word_explain":"定める (さだめる) = 決める (きめる): quy định, ấn định, quyết định","translation_vi":"Cần phải quy định (ấn định) các điều kiện."},{"mondai":6,"q":26,"prompt":"廃止","options":["予想以上のコストがかかることがわかり、新製品の開発を<u>廃止</u>した。","石川さんは毎日ジョギングすることを<u>廃止</u>したらしい。","ほかの人に話すことで、不安を<u>廃止</u>できることもある。","あの銀行はATM手数料無料のサービスを<u>廃止</u>するそうだ。"],"answer":4,"word_explain":"廃止 (はいし): bãi bỏ, hủy bỏ (dùng cho chế độ, quy định, dịch vụ, tuyến đường...)","translation_vi":"Nghe nói ngân hàng kia sắp bãi bỏ dịch vụ miễn phí giao dịch ATM."},{"mondai":6,"q":27,"prompt":"初歩","options":["3年前に英語を<u>初歩</u>から始め、今では自由に話せるようになった。","バスケットボールの試合で、<u>初歩</u>から大量の点を取られた。","今日の暑さはまだほんの<u>初歩</u>で、これからますます暑くなっていくだろう。","兄とのけんかの<u>初歩</u>は、くだらないことだった。"],"answer":1,"word_explain":"初歩 (しょほ): bước đầu, kiến thức căn bản/sơ cấp (trong học tập, kỹ năng)","translation_vi":"Ba năm trước tôi bắt đầu học tiếng Anh từ những kiến thức căn bản đầu tiên, và giờ đã có thể nói chuyện thoải mái."},{"mondai":6,"q":28,"prompt":"だらしない","options":["昨日作ったスープは塩がたりなかったのか、とても<u>だらしない</u>味だった。","この公園は管理する人がいないので、あちこちに草<u>だらしなく</u>生えている。","知識が<u>だらしなかった</u>せいで、間違ったことを人に教えてしまった。","先月までは、仕事もしないで遊んでばかりの<u>だらしない</u>生活をしていた。"],"answer":4,"word_explain":"だらしない: buông thả, lôi thôi, cẩu thả, thiếu kỷ luật (dùng cho lối sống, thái độ, trang phục...)","translation_vi":"Cho đến tháng trước, tôi vẫn sống một cuộc sống buông thả, chẳng làm việc mà suốt ngày chỉ ăn chơi."},{"mondai":6,"q":29,"prompt":"即座に","options":["私が駅に着くと<u>即座に</u>友人たちも来た。","さっきまで晴れていたのに、<u>即座に</u>雲が出てきた。","先生は学生からの質問に<u>即座に</u>答えた。","一月になってから<u>即座に</u>仕事が忙しくなった。"],"answer":3,"word_explain":"即座に (そくざに): ngay lập tức, tức khắc (dùng cho phản ứng, câu trả lời, quyết định tức thì)","translation_vi":"Thầy giáo đã trả lời ngay lập tức câu hỏi của sinh viên."},{"mondai":6,"q":30,"prompt":"尽きる","options":["あしたで定期券の期限が<u>尽きる</u>ので、新しいのを買いに行った。","森さんと会うのは久しぶりだったので、いくら話しても話が<u>尽きなかった</u>。","木村選手は、けがのせいで連続出場の記録が<u>尽きて</u>しまった。","この作家の絵が好きなので、展示会が<u>尽きない</u>うちにもう一度見に来たい。"],"answer":2,"word_explain":"尽きる (つきる): cạn kiệt, dứt, hết (話が尽きない: chuyện trò không dứt)","translation_vi":"Vì lâu rồi mới gặp anh Mori nên dù có nói bao nhiêu cũng không hết chuyện."}]},{"id":"2018_12","displayName":"12/2018","sourceFile":"N2 T12-2018.pdf","questions":[{"mondai":1,"q":1,"prompt":"二人は<u>離れて</u>座った。","options":["はなれて","わかれて","かくれて","はずれて"],"answer":1,"word_explain":"離れて (はなれて): cách xa, tách ra","translation_vi":"Hai người ngồi cách xa nhau."},{"mondai":1,"q":2,"prompt":"何か良い<u>企画</u>はありますか。","options":["しかく","きかく","きが","しが"],"answer":2,"word_explain":"企画 (きかく): kế hoạch, dự án","translation_vi":"Có kế hoạch nào hay không?"},{"mondai":1,"q":3,"prompt":"<u>再度</u>確認をお願いします。","options":["さいどう","さいど","ざいど","ざいどう"],"answer":2,"word_explain":"再度 (さいど): lần nữa, lại một lần nữa","translation_vi":"Xin vui lòng xác nhận lại một lần nữa."},{"mondai":1,"q":4,"prompt":"とても<u>和やか</u>なパーティーだった。","options":["おだやか","さわやか","なごやか","にぎやか"],"answer":3,"word_explain":"和やか (なごやか): hòa nhã, ấm cúng, thân mật","translation_vi":"Đó là một bữa tiệc rất ấm cúng và thân mật."},{"mondai":1,"q":5,"prompt":"コンピュータでデータを<u>処理</u>した。","options":["しゅり","しょうり","しゅうり","しょり"],"answer":4,"word_explain":"処理 (しょり): xử lý","translation_vi":"Tôi đã xử lý dữ liệu bằng máy tính."},{"mondai":2,"q":6,"prompt":"明日10時に<u>むかえ</u>に行きます。","options":["招え","仰え","迎え","紹え"],"answer":3,"word_explain":"迎え (むかえ): đón, sự đón tiếp","translation_vi":"Ngày mai lúc 10 giờ tôi sẽ đi đón."},{"mondai":2,"q":7,"prompt":"坂本さんは<u>かいご</u>の仕事をしている。","options":["看穫","介護","介穫","看護"],"answer":2,"word_explain":"介護 (かいご): chăm sóc, điều dưỡng (người già, người cần hỗ trợ)","translation_vi":"Anh/chị Sakamoto đang làm công việc điều dưỡng (chăm sóc)."},{"mondai":2,"q":8,"prompt":"カップや皿を同じ<u>けいとう</u>の色でそろえた。","options":["系統","系等","形統","形等"],"answer":1,"word_explain":"系統 (けいとう): hệ thống, tông màu (nhóm màu cùng loại)","translation_vi":"Tôi đã sắp xếp cốc và đĩa theo cùng một tông màu."},{"mondai":2,"q":9,"prompt":"古い新聞や本をひもで<u>たばねた</u>。","options":["結ねた","収ねた","包ねた","束ねた"],"answer":4,"word_explain":"束ねた (たばねた): bó lại, buộc thành bó (từ 束ねる)","translation_vi":"Tôi đã dùng dây buộc báo cũ và sách lại thành bó."},{"mondai":2,"q":10,"prompt":"出張後、費用の<u>せいさん</u>をした。","options":["請算","製算","精算","制算"],"answer":3,"word_explain":"精算 (せいさん): thanh toán, quyết toán (chi phí)","translation_vi":"Sau chuyến công tác, tôi đã làm quyết toán chi phí."},{"mondai":3,"q":11,"prompt":"(　　)計画のまま始めるのはやめたほうがいい。","options":["不","非","無","反"],"answer":3,"word_explain":"無計画 (むけいかく): không có kế hoạch, thiếu kế hoạch","translation_vi":"Tốt hơn là không nên bắt đầu khi vẫn còn không có kế hoạch gì."},{"mondai":3,"q":12,"prompt":"怪しいメールが届いたときには、メールの送信(　　)を確認するようにしている。","options":["元","原","根","素"],"answer":1,"word_explain":"送信元 (そうしんもと): nơi gửi, địa chỉ/nguồn gửi","translation_vi":"Khi nhận được email đáng ngờ, tôi luôn cố gắng kiểm tra người/nơi gửi email đó."},{"mondai":3,"q":13,"prompt":"この国では農家の働き(　　)が減少している。","options":["顔","手","足","腕"],"answer":2,"word_explain":"働き手 (はたらきて): người lao động, nhân lực","translation_vi":"Ở đất nước này, số lượng lao động trong các hộ nông dân đang giảm dần."},{"mondai":4,"q":14,"prompt":"このスーパーは店の前に車をとめる(　　)がない。","options":["スペース","フロア","ステージ","フロント"],"answer":1,"word_explain":"スペース: không gian, chỗ trống (để đỗ xe)","translation_vi":"Siêu thị này không có chỗ để đỗ xe ở phía trước cửa hàng."},{"mondai":4,"q":15,"prompt":"エレベーターに異常がないか、定期的に(　　)している。","options":["参観","検診","観測","点検"],"answer":4,"word_explain":"点検 (てんけん): kiểm tra định kỳ (máy móc, thiết bị)","translation_vi":"Thang máy được kiểm tra định kỳ xem có gì bất thường không."},{"mondai":4,"q":16,"prompt":"カメラを向けると、子どもたちは(　　)笑った。","options":["さっぱり","にっこり","ぴかぴか","ほかほか"],"answer":2,"word_explain":"にっこり: mỉm cười tươi tắn","translation_vi":"Khi hướng máy ảnh về phía bọn trẻ, chúng liền mỉm cười tươi."},{"mondai":4,"q":17,"prompt":"今日の海は波が高く、船が揺れたせいで、気分が悪くなる人が(　　)した。","options":["続行","続出","持続","継続"],"answer":2,"word_explain":"続出 (ぞくしゅつ): xuất hiện liên tiếp, xảy ra hàng loạt","translation_vi":"Hôm nay biển sóng to nên vì tàu rung lắc mà liên tiếp có nhiều người bị say sóng."},{"mondai":4,"q":18,"prompt":"料理中にくしゃみをしたら、小麦粉が(　　)しまった。","options":["飛び立って","飛び上がって","飛び散って","飛び降りて"],"answer":3,"word_explain":"飛び散って (とびちって): bay tung tóe, văng tung tóe (từ 飛び散る)","translation_vi":"Đang nấu ăn mà hắt hơi một cái khiến bột mì bay tung tóe khắp nơi."},{"mondai":4,"q":19,"prompt":"私は大学を卒業したら、(　　)に戻って実家の近くで就職したいと思う。","options":["地元","根元","土台","立場"],"answer":1,"word_explain":"地元 (じもと): quê nhà, địa phương nơi mình sinh ra và lớn lên","translation_vi":"Sau khi tốt nghiệp đại học, tôi muốn trở về quê hương và tìm việc gần nhà bố mẹ."},{"mondai":4,"q":20,"prompt":"中野さんは味に(　　)で、調味料が少し変わっただけで違いがわかるらしい。","options":["急激","機敏","過激","敏感"],"answer":4,"word_explain":"敏感 (びんかん): nhạy cảm, tinh tế (với mùi vị, sự thay đổi)","translation_vi":"Nghe nói anh/chị Nakano rất nhạy với mùi vị, chỉ cần gia vị thay đổi một chút thôi là nhận ra sự khác biệt ngay."},{"mondai":5,"q":21,"prompt":"この機械を扱うには、特別な<u>テクニック</u>が必要だ。","options":["技術","知識","工夫","訓練"],"answer":1,"word_explain":"テクニック = 技術 (ぎじゅつ): kỹ thuật","translation_vi":"Để vận hành chiếc máy này, cần phải có kỹ thuật đặc biệt."},{"mondai":5,"q":22,"prompt":"青木さんはしばらく黙って<u>うつむいていた</u>。","options":["遠くを見て","目を閉じて","下を向いて","腕を組んで"],"answer":3,"word_explain":"うつむいていた = 下を向いていた: cúi đầu, nhìn xuống dưới","translation_vi":"Anh/chị Aoki im lặng cúi đầu xuống một lúc."},{"mondai":5,"q":23,"prompt":"この犬は、本当に<u>利口</u>な犬ですね。","options":["かわいい","頭がいい","元気な","かっこいい"],"answer":2,"word_explain":"利口 (りこう) = 頭がいい: thông minh, khôn ngoan","translation_vi":"Con chó này đúng là một chú chó thông minh nhỉ."},{"mondai":5,"q":24,"prompt":"もう少し<u>用心した</u>ほうがいいんじゃないですか。","options":["落ち着いた","がんばった","よく考えた","気をつけた"],"answer":4,"word_explain":"用心した (ようじんした) = 気をつけた: cẩn trọng, đề phòng","translation_vi":"Chẳng phải nên cẩn thận hơn một chút thì tốt hơn sao?"},{"mondai":5,"q":25,"prompt":"説明が<u>くどくて</u>すみません。","options":["つまらなくて","下手で","複雑で","しつこくて"],"answer":4,"word_explain":"くどくて = しつこくて: dài dòng, lằng nhằng, lặp đi lặp lại","translation_vi":"Xin lỗi vì lời giải thích hơi dài dòng."},{"mondai":6,"q":26,"prompt":"保存","options":["将来のためにお金は<u>保存</u>したほうがいいですよ。","食堂に早く着いたので、後から来る友達の席を<u>保存</u>しておいた。","この食品は必ず冷蔵庫で<u>保存</u>してください。","山登りは長時間の運動なので、体力を<u>保存</u>しないと後半が大変だ。"],"answer":3,"word_explain":"保存 (ほぞん): bảo quản, lưu giữ (thực phẩm, dữ liệu, di tích, trạng thái ban đầu)","translation_vi":"Thực phẩm này nhất định hãy bảo quản trong tủ lạnh."},{"mondai":6,"q":27,"prompt":"鈍い","options":["私は数学が苦手で、計算がとても<u>鈍い</u>。","今日は仕事が暇で、時間がたつのが<u>鈍く</u>感じられた。","彼は仕事が<u>鈍い</u>が、その分丁寧だ。","疲れているのか、彼はいつもより動きが<u>鈍い</u>。"],"answer":4,"word_explain":"鈍い (にぶい): chậm chạp, cùn, kém nhạy bén (dùng cho cử động, cảm giác, phản ứng, lưỡi dao)","translation_vi":"Không biết có phải vì mệt không mà cử động của anh ấy hôm nay chậm chạp hơn mọi khi."},{"mondai":6,"q":28,"prompt":"日課","options":["停留所でバスの<u>日課</u>を見ると、次の発車時刻は20分後だった。","今日は売り上げが10万円以上あったので、<u>日課</u>が達成できた。","朝9時までに出社することが会社の<u>日課</u>で決まっている。","健康のため、毎朝30分体操することを<u>日課</u>にしている。"],"answer":4,"word_explain":"日課 (にっか): việc làm hằng ngày, thói quen hằng ngày (hay dùng với 「〜を日課にする」)","translation_vi":"Vì sức khỏe, tôi biến việc tập thể dục 30 phút mỗi sáng thành thói quen hằng ngày."},{"mondai":6,"q":29,"prompt":"多彩","options":["高橋氏は、小説家や画家として<u>多彩</u>な活動を行っている。","今夜は空に星が<u>多彩</u>に輝いていて、とてもきれいです。","文章にあいまいな表現を使うと、読者が<u>多彩</u>な理解をするだろう。","木村さんには生活全般において<u>多彩</u>にお世話になりました。"],"answer":1,"word_explain":"多彩 (たさい): đa dạng, phong phú, nhiều lĩnh vực/màu sắc (hay dùng cho hoạt động, tài năng, sự kiện)","translation_vi":"Ông Takahashi đang thực hiện các hoạt động đa dạng với tư cách là tiểu thuyết gia và họa sĩ."},{"mondai":6,"q":30,"prompt":"乗り継ぐ","options":["居眠りをして、降りるつもりだった駅を<u>乗り継いで</u>しまった。","疲れたので友達に運転を<u>乗り継いで</u>もらった。","バスと電車を<u>乗り継いで</u>、やっと目的地に着いた。","朝はたくさんの人が電車を<u>乗り継ぐ</u>ので、ドアの近くに立っていると大変だ。"],"answer":3,"word_explain":"乗り継ぐ (のりつぐ): chuyển tuyến, đổi xe/tàu để đi tiếp","translation_vi":"Chuyển từ xe buýt sang tàu điện rồi cuối cùng tôi cũng đến được nơi cần đến."}]},{"id":"2018_07","displayName":"07/2018","sourceFile":"Đề N2 7-2018.pdf","questions":[{"mondai":1,"q":1,"prompt":"私は少し<u>怖い</u>と思いました。","options":["つらい","きつい","ゆるい","こわい"],"answer":4,"word_explain":"怖い (こわい): đáng sợ, sợ hãi","translation_vi":"Tôi đã cảm thấy hơi sợ."},{"mondai":1,"q":2,"prompt":"この食品は<u>冷蔵庫</u>で保存してください。","options":["れいとうこ","れいぞうこう","れいぞうこ","れいとうこう"],"answer":3,"word_explain":"冷蔵庫 (れいぞうこ): tủ lạnh","translation_vi":"Hãy bảo quản thực phẩm này trong tủ lạnh."},{"mondai":1,"q":3,"prompt":"今年の支出は<u>総額</u>で約5,300万円だった。","options":["こうがく","そうがく","そうかく","こうかく"],"answer":2,"word_explain":"総額 (そうがく): tổng số tiền","translation_vi":"Tổng số tiền chi tiêu năm nay khoảng 53 triệu yên."},{"mondai":1,"q":4,"prompt":"まだ<u>湿って</u>いるから、もう少し待ちましょう。","options":["こおって","にごって","しめって","たまって"],"answer":3,"word_explain":"湿る (しめる): ẩm, ẩm ướt","translation_vi":"Vì vẫn còn ẩm ướt nên hãy đợi thêm một chút nữa."},{"mondai":1,"q":5,"prompt":"応募者には<u>抽選</u>でプレゼントが当たります。","options":["ちゅうせん","ちゅうぜん","つうせん","つうぜん"],"answer":1,"word_explain":"抽選 (ちゅうせん): bốc thăm, rút thăm trúng thưởng","translation_vi":"Những người đăng ký sẽ được rút thăm trúng quà tặng."},{"mondai":2,"q":6,"prompt":"この国にはまだ<u>ゆたか</u>な自然が残されている。","options":["恵か","富か","豊か","満か"],"answer":3,"word_explain":"豊か (ゆたか): phong phú, trù phú, dồi dào","translation_vi":"Đất nước này vẫn còn lưu giữ được thiên nhiên trù phú."},{"mondai":2,"q":7,"prompt":"このセミナーの目標は、「自分で考える力」を<u>やしなう</u>ことです。","options":["得う","築う","育う","養う"],"answer":4,"word_explain":"養う (やしなう): rèn luyện, nuôi dưỡng, bồi dưỡng","translation_vi":"Mục tiêu của hội thảo này là rèn luyện \"khả năng tự suy nghĩ\"."},{"mondai":2,"q":8,"prompt":"ガラスの<u>はへん</u>を踏まないように気をつけてください。","options":["破片","被片","破辺","被辺"],"answer":1,"word_explain":"破片 (はへん): mảnh vỡ","translation_vi":"Hãy cẩn thận để không giẫm phải mảnh vỡ thủy tinh."},{"mondai":2,"q":9,"prompt":"工場の入り口には夜間でも<u>けいび</u>の人がいる。","options":["警秘","警備","係備","係秘"],"answer":2,"word_explain":"警備 (けいび): cảnh vệ, bảo vệ, canh gác","translation_vi":"Ở lối vào nhà máy có nhân viên bảo vệ ngay cả vào ban đêm."},{"mondai":2,"q":10,"prompt":"時間がないので、詳しい説明は<u>はぶきます</u>。","options":["略きます","除きます","省きます","抜きます"],"answer":3,"word_explain":"省く (はぶく): lược bỏ, tỉnh lược","translation_vi":"Vì không có thời gian nên tôi xin lược bỏ phần giải thích chi tiết."},{"mondai":3,"q":11,"prompt":"正月もスキー(　　)は、人でいっぱいだ。","options":["所","場","区","地"],"answer":2,"word_explain":"スキー場 (スキーじょう): khu trượt tuyết","translation_vi":"Vào dịp Tết thì khu trượt tuyết cũng chật kín người."},{"mondai":3,"q":12,"prompt":"(　　)学期から新しいプログラムが始まる。","options":["明","近","隣","来"],"answer":4,"word_explain":"来学期 (らいがっき): học kỳ tới","translation_vi":"Chương trình mới sẽ bắt đầu từ học kỳ tới."},{"mondai":3,"q":13,"prompt":"この高校は進学(　　)が非常に高く、ほとんどの生徒が大学に進む。","options":["量","値","率","割"],"answer":3,"word_explain":"進学率 (しんがくりつ): tỷ lệ học lên cao (lên đại học)","translation_vi":"Trường cấp 3 này có tỷ lệ học lên đại học rất cao, hầu hết học sinh đều vào đại học."},{"mondai":3,"q":14,"prompt":"大臣の下に二人の(　　)大臣がいるのが一般的です。","options":["補","助","次","副"],"answer":4,"word_explain":"副大臣 (ふくだいじん): thứ trưởng, phó bộ trưởng","translation_vi":"Thông thường dưới bộ trưởng có hai thứ trưởng."},{"mondai":3,"q":15,"prompt":"スポーツテストの結果を学年(　　)に見ると、一年生だけが昨年を上回っていた。","options":["別","境","段","節"],"answer":1,"word_explain":"学年別 (がくねんべつ): theo từng khối lớp, theo từng năm học","translation_vi":"Khi xem kết quả kiểm tra thể lực theo từng khối lớp, chỉ có học sinh năm nhất là vượt qua năm ngoái."},{"mondai":4,"q":16,"prompt":"昨日の試合では実力を(　　)できず、一試合目で負けてしまった。","options":["表現","明示","公開","発揮"],"answer":4,"word_explain":"発揮 (はっき): phát huy","translation_vi":"Trong trận đấu hôm qua tôi đã không thể phát huy được thực lực nên đã thua ngay ở trận đầu tiên."},{"mondai":4,"q":17,"prompt":"料理本を見ながら、自分の好みに合うように味付けを(　　)する。","options":["コメント","デザイン","アレンジ","ケア"],"answer":3,"word_explain":"アレンジ: biến tấu, điều chỉnh cho phù hợp","translation_vi":"Vừa xem sách dạy nấu ăn vừa điều chỉnh gia vị sao cho hợp khẩu vị của mình."},{"mondai":4,"q":18,"prompt":"あの人が描く絵には、ほかの人の絵にはない(　　)の雰囲気がある。","options":["専属","独特","限定","孤立"],"answer":2,"word_explain":"独特 (どくとく): độc đáo, riêng biệt","translation_vi":"Trong những bức tranh người đó vẽ có một bầu không khí độc đáo mà tranh của người khác không có."},{"mondai":4,"q":19,"prompt":"父は、どんなに忙しいときでも、朝の運動を(　　)。","options":["空けない","離さない","奪わない","欠かさない"],"answer":4,"word_explain":"欠かさない (かかさない): không bỏ sót, không thiếu (làm đều đặn)","translation_vi":"Bố tôi dù bận rộn đến đâu cũng không bao giờ bỏ tập thể dục buổi sáng."},{"mondai":4,"q":20,"prompt":"クイズの答えがわからなくて(　　)答えたのに、正解だった。","options":["でたらめに","わがままに","ぎざぎざに","ごちゃごちゃに"],"answer":1,"word_explain":"でたらめに: bừa bãi, đại khái, đoán mò","translation_vi":"Tôi không biết đáp án câu đố nên trả lời bừa vậy mà lại trúng."},{"mondai":4,"q":21,"prompt":"昨夜はこの冬でいちばんの寒さとなり、最低気温はマイナス20度に(　　)。","options":["減った","達した","通じた","沈んだ"],"answer":2,"word_explain":"達する (たっする): đạt đến, chạm mức","translation_vi":"Đêm qua trở thành đêm lạnh nhất mùa đông này, nhiệt độ thấp nhất xuống tới âm 20 độ."},{"mondai":4,"q":22,"prompt":"来月の結婚式に向けて準備が(　　)進んでいる。","options":["着々と","慎重に","いちいち","ぐんぐん"],"answer":1,"word_explain":"着々と (ちゃくちゃくと): từng bước vững chắc, tuần tự (chuẩn bị tiến triển tốt)","translation_vi":"Công tác chuẩn bị cho lễ cưới vào tháng tới đang tiến triển từng bước một cách vững chắc."},{"mondai":5,"q":23,"prompt":"車にボールを<u>当てて</u>、しかられた。","options":["ぶつけて","隠して","落として","詰めて"],"answer":1,"word_explain":"当てる (あてる) = ぶつける: làm trúng vào, đập vào, ném trúng","translation_vi":"Tôi đã làm bóng đập trúng vào xe ô tô và bị mắng."},{"mondai":5,"q":24,"prompt":"その作家は<u>あわれな</u>人生を送った。","options":["退屈な","おかしな","かわいそうな","不安な"],"answer":3,"word_explain":"あわれな = かわいそうな: đáng thương, khốn khổ","translation_vi":"Nhà văn đó đã trải qua một cuộc đời đáng thương."},{"mondai":5,"q":25,"prompt":"<u>当分</u>は使わない予定です。","options":["これから","全部","今回","しばらく"],"answer":4,"word_explain":"当分 (とうぶん) = しばらく: tạm thời, trong một thời gian","translation_vi":"Dự kiến tạm thời một thời gian nữa sẽ không sử dụng."},{"mondai":5,"q":26,"prompt":"留学の話が<u>一転した</u>。","options":["急に止まった","すっかり変わった","少し進んだ","とうとう許された"],"answer":2,"word_explain":"一転する (いってんする) = すっかり変わる: thay đổi hoàn toàn, xoay chuyển 180 độ","translation_vi":"Câu chuyện đi du học đã thay đổi hoàn toàn."},{"mondai":5,"q":27,"prompt":"テストの前日になって<u>じたばたしても</u>しかたない。","options":["慌てても","心配しても","緊張しても","悩んでも"],"answer":1,"word_explain":"じたばたする = 慌てる (あわてる): cuống cuồng, luống cuống, vùng vẫy vô ích","translation_vi":"Đến sát ngày trước kỳ thi mới cuống cuồng lên thì cũng chẳng ích gì."},{"mondai":6,"q":28,"prompt":"役目","options":["次の公演で、私は医者の<u>役目</u>を演じる。","健康のために、毎朝散歩することが<u>役目</u>になっている。","池田さんが今日の掃除の<u>役目</u>だ。","部下に仕事を教えるのは、課長の<u>役目</u>の一つだ。"],"answer":4,"word_explain":"役目 (やくめ): vai trò, nhiệm vụ, bổn phận được giao (dùng cho trách nhiệm công việc/chức vụ, không dùng cho vai diễn hay thói quen cá nhân)","translation_vi":"Hướng dẫn công việc cho cấp dưới là một trong những nhiệm vụ của trưởng phòng."},{"mondai":6,"q":29,"prompt":"最寄り","options":["<u>最寄り</u>の店までは、歩いて30分だ。","彼女は私の<u>最寄り</u>の友達だ。","<u>最寄り</u>の試験は来月にある。","電車の中で<u>最寄り</u>の人に足を踏まれた。"],"answer":1,"word_explain":"最寄り (もより): gần nhất về mặt địa lý/vị trí (thường đi với 駅, 店, バス停...)","translation_vi":"Đi bộ đến cửa hàng gần nhất mất 30 phút."},{"mondai":6,"q":30,"prompt":"解約","options":["大臣は、内容に誤りがあったと述べ、昨日の発言を<u>解約</u>した。","1年の留学を終えて国へ帰るので、銀行の口座を<u>解約</u>した。","やむをえない理由により、A社との面会を<u>解約</u>した。","あの会社は今年は赤字を<u>解約</u>することができた。"],"answer":2,"word_explain":"解約 (かいやく): hủy hợp đồng, giải ước (dùng cho hợp đồng, tài khoản ngân hàng, thẻ, dịch vụ thuê bao...)","translation_vi":"Vì kết thúc 1 năm du học và về nước nên tôi đã đóng tài khoản ngân hàng."},{"mondai":6,"q":31,"prompt":"演説","options":["卒業生代表の森さんは卒業式での<u>演説</u>で、先生方への感謝の気持ちを述べた。","首相は昨日の国会での<u>演説</u>で、経済対策を最優先するとの決意を述べた。","決勝進出が決まった中島選手は試合後の<u>演説</u>で、必ず優勝すると述べた。","A社の社長は記者会見の<u>演説</u>で、今後の事業方針について述べた。"],"answer":2,"word_explain":"演説 (えんぜつ): diễn thuyết (phát biểu ý kiến, chủ trương trước công chúng, thường dùng trong chính trị, tranh cử, quốc hội)","translation_vi":"Trong bài diễn thuyết tại Quốc hội hôm qua, Thủ tướng đã bày tỏ quyết tâm ưu tiên hàng đầu cho các biện pháp kinh tế."},{"mondai":6,"q":32,"prompt":"きっぱり","options":["めがねをかけると、遠くの物も<u>きっぱり</u>見えるようになる。","このラーメンはもう何度も食べたので、<u>きっぱり</u>飽きてしまった。","鈴木さんは石川さんからのデートの誘いを<u>きっぱり</u>断った。","むかしのことはなかなか<u>きっぱり</u>思い出せない。"],"answer":3,"word_explain":"きっぱり: dứt khoát, thẳng thừng, rõ ràng (dùng khi từ chối, phủ định, hoặc bày tỏ thái độ kiên quyết)","translation_vi":"Chị Suzuki đã từ chối dứt khoát lời mời hẹn hò từ anh Ishikawa."}]},{"id":"2017_12","displayName":"12/2017","sourceFile":"Đề N2 12-2017.pdf","questions":[{"mondai":1,"q":1,"prompt":"きれいに整えた髪が<u>乱れて</u>しまった。","options":["みだれて","くずれて","つぶれて","よごれて"],"answer":1,"word_explain":"乱れて (みだれて - 乱れる): rối tung, bừa bộn (lưu ý: bản PDF gạch chân nhầm sang 整えた)","translation_vi":"Mái tóc được chải chuốt gọn gàng đã bị rối mất rồi."},{"mondai":1,"q":2,"prompt":"係員は<u>柔軟</u>に対応してくれた。","options":["じゅうけつ","じゅなん","じゅうなん","じゅけつ"],"answer":3,"word_explain":"柔軟 (じゅうなん): mềm dẻo, linh hoạt","translation_vi":"Nhân viên phụ trách đã xử lý một cách linh hoạt."},{"mondai":1,"q":3,"prompt":"表面を<u>強火</u>で焼いてください。","options":["きょうか","つよか","きょうび","つよび"],"answer":4,"word_explain":"強火 (つよび): lửa lớn, lửa to","translation_vi":"Hãy nướng bề mặt bằng lửa lớn."},{"mondai":1,"q":4,"prompt":"それを一人で<u>抱える</u>のは大変そうだ。","options":["つかまえる","かかえる","おさえる","ささえる"],"answer":2,"word_explain":"抱える (かかえる): ôm, gánh vác","translation_vi":"Việc một mình gánh vác chuyện đó có vẻ vất vả đấy."},{"mondai":1,"q":5,"prompt":"アルバイトの<u>求人</u>があったので、応募した。","options":["きゅうにん","きゅうじん","きゅじん","きゅにん"],"answer":2,"word_explain":"求人 (きゅうじん): tuyển dụng, tìm người làm","translation_vi":"Vì có tin tuyển dụng việc làm thêm nên tôi đã ứng tuyển."},{"mondai":2,"q":6,"prompt":"私は大学院に<u>ざいせき</u>している。","options":["採籍","在簿","在籍","採簿"],"answer":3,"word_explain":"在籍 (ざいせき): đang theo học, có tên trong danh sách (trường/tổ chức)","translation_vi":"Tôi đang theo học ở trường cao học."},{"mondai":2,"q":7,"prompt":"ここでは、係員の指示に<u>したがって</u>ください。","options":["沿って","従って","伴って","頼って"],"answer":2,"word_explain":"従って (したがって - 従う): tuân theo, làm theo","translation_vi":"Ở đây, xin hãy làm theo chỉ dẫn của nhân viên phụ trách."},{"mondai":2,"q":8,"prompt":"この国は<u>ふくし</u>が充実している。","options":["副仕","副社","福仕","福祉"],"answer":4,"word_explain":"福祉 (ふくし): phúc lợi","translation_vi":"Đất nước này có chế độ phúc lợi rất đầy đủ."},{"mondai":2,"q":9,"prompt":"<u>りょうしゅうしょ</u>を発行してもらった。","options":["領収書","了収書","領修書","了修書"],"answer":1,"word_explain":"領収書 (りょうしゅうしょ): biên lai, hóa đơn thu tiền","translation_vi":"Tôi đã được xuất cho biên lai."},{"mondai":2,"q":10,"prompt":"全力で走ったので、息が<u>あらくなった</u>。","options":["暴く","激く","荒く","雑く"],"answer":3,"word_explain":"荒く (あらく - 荒い): gấp gáp, dữ dội (息が荒くなる: thở dốc, thở gấp)","translation_vi":"Vì đã chạy hết sức nên hơi thở trở nên gấp gáp."},{"mondai":3,"q":11,"prompt":"駅の北側には、住宅(　　)が広がっている。","options":["枠（わく）","界（かい）","面（めん）","街（がい）"],"answer":4,"word_explain":"住宅街 (じゅうたくがい): khu dân cư, khu nhà ở","translation_vi":"Ở phía bắc nhà ga, khu dân cư trải rộng ra."},{"mondai":3,"q":12,"prompt":"資料を見ると、数値に(　　)正確なところがあった。","options":["否","反","非","不"],"answer":4,"word_explain":"不正確 (ふせいかく): không chính xác","translation_vi":"Khi xem tài liệu thì thấy có chỗ số liệu không chính xác."},{"mondai":3,"q":13,"prompt":"この料理は野菜が多く(　　)カロリーだ。","options":["弱","低","下","欠"],"answer":2,"word_explain":"低カロリー (ていカロリー): ít calo, hàm lượng calo thấp","translation_vi":"Món ăn này có nhiều rau và ít calo."},{"mondai":3,"q":14,"prompt":"スーツを着た会社員(　　)の人に道を尋（たず）ねられた。","options":["風","類","状","式"],"answer":1,"word_explain":"会社員風 (かいしゃいんふう): có vẻ ngoài giống nhân viên công ty","translation_vi":"Tôi đã bị một người có dáng vẻ giống nhân viên công ty mặc vest hỏi đường."},{"mondai":3,"q":15,"prompt":"日本は(　　)外国から資源を輸入している。","options":["多","種","諸","複"],"answer":3,"word_explain":"諸外国 (しょがいこく): các nước ngoài, nhiều quốc gia khác","translation_vi":"Nhật Bản đang nhập khẩu tài nguyên từ các nước ngoài."},{"mondai":4,"q":16,"prompt":"健康のためには、栄養（えいよう）の(　　)がいい食事を取ることが大切だ。","options":["バランス","リズム","ビタミン","エネルギー"],"answer":1,"word_explain":"バランス: sự cân bằng (栄養のバランスがいい: cân bằng dinh dưỡng tốt)","translation_vi":"Để giữ gìn sức khỏe, việc ăn những bữa ăn có sự cân bằng dinh dưỡng tốt là rất quan trọng."},{"mondai":4,"q":17,"prompt":"市役所には騒音などの迷惑（めいわく）行為（こうい）に対する(　　)が寄せられる。","options":["苦情","悪意","不便","多難"],"answer":1,"word_explain":"苦情 (くじょう): lời phàn nàn, khiếu nại","translation_vi":"Tòa thị chính nhận được những lời phàn nàn về các hành vi gây phiền toái như tiếng ồn."},{"mondai":4,"q":18,"prompt":"ここは桜の(　　)で、春になると大勢の花見客が訪れる。","options":["要所","名所","実地","現場"],"answer":2,"word_explain":"名所 (めいしょ): danh thắng, địa điểm nổi tiếng","translation_vi":"Nơi đây là địa điểm ngắm hoa anh đào nổi tiếng, cứ đến mùa xuân lại có rất nhiều du khách đến ngắm hoa."},{"mondai":4,"q":19,"prompt":"電車に遅れそうだったが、(　　)間に合って何とか乗れた。","options":["ばったり","ぐっすり","ぎりぎり","がらがら"],"answer":3,"word_explain":"ぎりぎり: vừa kịp lúc, sát nút","translation_vi":"Tôi suýt nữa thì trễ tàu, nhưng đã kịp giờ sát nút và bằng cách nào đó lên được tàu."},{"mondai":4,"q":20,"prompt":"この資格を持っていると就職（しゅうしょく）に(　　)になると聞いた。","options":["先着","優先","強力","有利"],"answer":4,"word_explain":"有利 (ゆうり): có lợi, thuận lợi","translation_vi":"Tôi nghe nói nếu có chứng chỉ này thì sẽ có lợi cho việc tìm việc làm."},{"mondai":4,"q":21,"prompt":"あの政治家は記者会見に元気な様子で現れて、病気だといううわさを(　　)。","options":["入れ替えた","打ち消した","追い返した","差し引いた"],"answer":2,"word_explain":"打ち消した (うちけした - 打ち消す): phủ nhận, bác bỏ, dập tắt (tin đồn)","translation_vi":"Chính trị gia đó đã xuất hiện tại cuộc họp báo với vẻ mặt khỏe mạnh và bác bỏ tin đồn rằng mình bị bệnh."},{"mondai":4,"q":22,"prompt":"買い物に行くのに財布を忘れてしまうとは、山口（やまぐち）さんは本当に(　　)人だ。","options":["たのもしい","そうぞうしい","あつかましい","そそっかしい"],"answer":4,"word_explain":"そそっかしい: hấp tấp, cẩu thả, hay quên","translation_vi":"Đi mua sắm mà lại quên mang ví, anh/chị Yamaguchi thật là người hấp tấp/hay quên."},{"mondai":5,"q":23,"prompt":"多くの人が、あの選手のことを今も<u>記憶している</u>。","options":["心配して","語って","覚えて","応援して"],"answer":3,"word_explain":"記憶している (きおくしている) = 覚えて (いる): nhớ, ghi nhớ","translation_vi":"Nhiều người hiện nay vẫn còn nhớ về vận động viên đó."},{"mondai":5,"q":24,"prompt":"中村（なかむら）さんは<u>不平</u>ばかり言っている。","options":["文句（もんく）","冗談（じょうだん）","うそ","自慢（じまん）"],"answer":1,"word_explain":"不平 (ふへい) = 文句 (もんく): lời phàn nàn, bất mãn","translation_vi":"Anh/chị Nakamura suốt ngày chỉ toàn phàn nàn."},{"mondai":5,"q":25,"prompt":"あんなことを言われたら、誰（だれ）だって<u>むかつく</u>よ。","options":["怒る","驚く","困る","怖がる"],"answer":1,"word_explain":"むかつく = 怒る (おこる): tức giận, bực mình","translation_vi":"Nếu bị nói những lời như thế thì ai mà chẳng tức giận chứ."},{"mondai":5,"q":26,"prompt":"高橋（たかはし）さんがあんなに<u>勝手な</u>人だとは思わなかった。","options":["いじわるな","わがままな","なさけない","だらしない"],"answer":2,"word_explain":"勝手な (かってな) = わがままな: ích kỷ, tùy tiện, chỉ nghĩ cho bản thân","translation_vi":"Tôi không ngờ anh/chị Takahashi lại là người ích kỷ/tùy tiện đến thế."},{"mondai":5,"q":27,"prompt":"今回の件は、<u>まれな</u>例です。","options":["複雑な","よくある","ほとんどない","単純な"],"answer":3,"word_explain":"まれな = ほとんどない: hiếm hoi, hiếm khi xảy ra","translation_vi":"Vụ việc lần này là một trường hợp hiếm gặp."},{"mondai":6,"q":28,"prompt":"破れる","options":["強い風が吹いたせいで、庭の木の枝が何本も<u>破れて</u>しまった。","大きな箱を無理に紙袋に入れたら、袋の端が<u>破れて</u>しまった。","落としても<u>破れない</u>ように、プラスチックのコップを買った。","生ものは<u>破れない</u>ように冷蔵庫に入れて保存してください。"],"answer":2,"word_explain":"破れる (やぶれる): bị rách (dùng cho giấy, vải, túi...; không dùng cho cành cây gãy, cốc vỡ hay đồ tươi sống bị hỏng)","translation_vi":"Vì cố nhét chiếc hộp lớn vào túi giấy nên mép túi đã bị rách."},{"mondai":6,"q":29,"prompt":"限定","options":["乗車したら、切符にある座席番号を確認(かくにん)して、<u>限定</u>された席に座ってください。","今日は少し寒くなったので、エアコンの温度を高めに<u>限定</u>した。","まだ計画が不十分なのに、実行できると<u>限定</u>するのは早すぎると思う。","このパンは販売数を20個に<u>限定</u>しているので、すぐに売り切れてしまう。"],"answer":4,"word_explain":"限定 (げんてい): giới hạn, hạn định (dùng đúng trong cấu trúc 「～を～に限定する」: giới hạn số lượng bán ở mức...)","translation_vi":"Loại bánh mì này giới hạn số lượng bán là 20 chiếc nên sẽ bán hết ngay lập tức."},{"mondai":6,"q":30,"prompt":"いっせいに","options":["卒業の日に撮った記念写真には、同じクラスの生徒が<u>いっせいに</u>写っている。","公園で小さな子どもたちが<u>いっせいに</u>遊んでいる様子は、とてもかわいらしい。","明日は家族で<u>いっせいに</u>めいの結婚式に招待されているので、とても楽しみだ。","演奏(えんそう)が終わると、観客は舞台に向かって<u>いっせいに</u>大きな拍手(はくしゅ)を送った。"],"answer":4,"word_explain":"いっせいに (一斉に): đồng loạt, cùng một lúc (cùng thực hiện một hành động tại cùng một thời điểm)","translation_vi":"Khi buổi biểu diễn kết thúc, khán giả đã đồng loạt hướng về sân khấu và dành một tràng pháo tay lớn."},{"mondai":6,"q":31,"prompt":"散らかす","options":["部屋を掃除しても、子どもがすぐに本やおもちゃを<u>散らかして</u>しまう。","このビデオは長いので、一度に見ないで何回かに<u>散らかして</u>見よう。","山下（やました）さんはいつも、香水のにおいを<u>散らかし</u>ながら歩いている。","講演が始まる前に、来場者一人一人に資料を<u>散らかして</u>ください。"],"answer":1,"word_explain":"散らかす (ちらかす): làm bừa bộn, bày bừa bãi (đồ đạc, sách vở, đồ chơi...)","translation_vi":"Dù có dọn phòng sạch sẽ thì trẻ con cũng nhanh chóng bày bừa sách và đồ chơi ra ngay."},{"mondai":6,"q":32,"prompt":"論争","options":["全員の面接が終わったので、試験官は<u>論争</u>のため別室に移った。","前田(まえだ)さんは私が言うことにいちいち<u>論争</u>するので、やりにくくて困る。","二人はその問題について<u>論争</u>を繰返(くりかえ)しているが、いまだに決着がつかない。","私が両親に<u>論争</u>すると、二人は静かに聞き、的確にアドバイスしてくれた。"],"answer":3,"word_explain":"論争 (ろんそう): tranh luận, tranh cãi (giữa hai bên có ý kiến đối lập về một vấn đề)","translation_vi":"Hai người vẫn lặp đi lặp lại cuộc tranh luận về vấn đề đó, nhưng đến giờ vẫn chưa ngã ngũ."}]},{"id":"2017_07","displayName":"07/2017","sourceFile":"Đề N2 7-2017.pdf","questions":[{"mondai":1,"q":1,"prompt":"青(あお)木(き)さんってちょっと<u>幼い</u>ところがあるよね。","options":["くどい","ずるい","おさない","しつこい"],"answer":3,"word_explain":"幼い (おさない): trẻ con, non nớt, ngây thơ","translation_vi":"Anh Aoki có điểm hơi trẻ con nhỉ."},{"mondai":1,"q":2,"prompt":"しっかり<u>握って</u>ください。","options":["ふって","にぎって","こすって","ほって"],"answer":2,"word_explain":"握って (にぎって): nắm chặt, cầm chắc","translation_vi":"Hãy nắm thật chặt nhé."},{"mondai":1,"q":3,"prompt":"空気が入らないようにきちんと<u>密閉</u>してください。","options":["ひっぺい","みっぺい","みっぱい","ひっぱい"],"answer":2,"word_explain":"密閉 (みっぺい): đậy kín, niêm phong kín","translation_vi":"Để không khí không lọt vào, hãy đậy thật kín."},{"mondai":1,"q":4,"prompt":"かなりの時間をかけてテーマを<u>絞った</u>。","options":["しぼった","けずった","さぐった","うかがった"],"answer":1,"word_explain":"絞った (しぼった): thu hẹp, chọn lọc (chủ đề)","translation_vi":"Đã dành khá nhiều thời gian để thu hẹp chủ đề."},{"mondai":1,"q":5,"prompt":"この線に対して<u>垂直</u>な線を引いてください。","options":["ついじき","ついちょく","すいじき","すいちょく"],"answer":4,"word_explain":"垂直 (すいちょく): vuông góc, thẳng đứng","translation_vi":"Hãy kẻ một đường thẳng vuông góc với đường thẳng này."},{"mondai":2,"q":6,"prompt":"今朝は寒くて、池が<u>こおった</u>。","options":["凍った","結った","固った","冷った"],"answer":1,"word_explain":"凍った (こおった): đóng băng","translation_vi":"Sáng nay trời lạnh nên mặt hồ đã đóng băng."},{"mondai":2,"q":7,"prompt":"エネルギー問題についての<u>とうろん</u>が行われた。","options":["党論","討論","討議","党議"],"answer":2,"word_explain":"討論 (とうろん): thảo luận, tranh luận","translation_vi":"Một cuộc thảo luận về vấn đề năng lượng đã được tổ chức."},{"mondai":2,"q":8,"prompt":"私たちの団体は、傷ついた動物を<u>すくう</u>活動をしています。","options":["治う","助う","救う","療う"],"answer":3,"word_explain":"救う (すくう): cứu giúp, giải cứu","translation_vi":"Tổ chức của chúng tôi đang thực hiện các hoạt động cứu giúp động vật bị thương."},{"mondai":2,"q":9,"prompt":"CDの売れ行きは<u>こうちょう</u>だ。","options":["好調","快調","好長","快長"],"answer":1,"word_explain":"好調 (こうちょう): thuận lợi, tiến triển tốt","translation_vi":"Tình hình bán đĩa CD đang rất khả quan."},{"mondai":2,"q":10,"prompt":"この機械は<u>えいきゅう</u>に動くわけではない。","options":["延久","永遠","永久","延遠"],"answer":3,"word_explain":"永久 (えいきゅう): vĩnh cửu, mãi mãi","translation_vi":"Cái máy này không phải lúc nào cũng hoạt động mãi mãi được."},{"mondai":3,"q":11,"prompt":"4月中にご入会になると、(　　)年度の会費が無料になります。","options":["発","開","頭","初"],"answer":4,"word_explain":"初年度 (しょねんど): năm đầu tiên","translation_vi":"Nếu quý khách gia nhập trong tháng 4, hội phí năm đầu tiên sẽ được miễn phí."},{"mondai":3,"q":12,"prompt":"今の社長は、(　　)社長より15歳も若い。","options":["先(せん)","前(ぜん)","昨(さく)","去(きょ)"],"answer":2,"word_explain":"前社長 (ぜんしゃちょう): giám đốc tiền nhiệm, vị giám đốc trước","translation_vi":"Giám đốc hiện tại trẻ hơn giám đốc tiền nhiệm tới 15 tuổi."},{"mondai":3,"q":13,"prompt":"ここは会員(　　)のスポーツクラブだ。","options":["令","制","則","形"],"answer":2,"word_explain":"会員制 (かいいんせい): chế độ hội viên (chỉ dành cho thành viên)","translation_vi":"Đây là câu lạc bộ thể thao áp dụng chế độ hội viên."},{"mondai":3,"q":14,"prompt":"休日の公園は家族(　　)でいっぱいだった。","options":["込み","付き","伴い","連れ"],"answer":4,"word_explain":"家族連れ (かぞくづれ): đi cùng gia đình, các nhóm gia đình","translation_vi":"Công viên vào ngày nghỉ đông kín các gia đình đi chơi cùng nhau."},{"mondai":3,"q":15,"prompt":"前の席の人は石(いし)川(かわ)さんのような気がするが、(　　)後ろからでは顔が見えない。","options":["本(ほん)","正(せい)","真(ま)","完(かん)"],"answer":3,"word_explain":"真後ろ (まうしろ): ngay đằng sau","translation_vi":"Người ngồi hàng ghế trước trông giống anh Ishikawa, nhưng nhìn từ ngay phía sau thì không thấy rõ mặt."},{"mondai":4,"q":16,"prompt":"骨を丈夫にするために、カルシウムを(　　)含む食品をとるようにしている。","options":["鮮明に","活発に","円満に","豊富に"],"answer":4,"word_explain":"豊富に (ほうふに): dồi dào, phong phú","translation_vi":"Để giúp xương chắc khỏe, tôi cố gắng ăn các thực phẩm chứa nhiều canxi."},{"mondai":4,"q":17,"prompt":"今週は、暑くも寒くもなく、強い風も吹かず、(　　)天気が続いている。","options":["柔(やわ)らかな","穏(おだ)やかな","滑(なめ)らかな","緩(ゆる)やかな"],"answer":2,"word_explain":"穏やかな (おだやかな): ôn hòa, êm dịu (thời tiết, tính cách)","translation_vi":"Tuần này trời không nóng cũng không lạnh, không có gió mạnh, thời tiết ôn hòa cứ thế tiếp diễn."},{"mondai":4,"q":18,"prompt":"資格試験がもうすぐあるのに、最近仕事が忙しくて、毎朝の勉強時間を十(じゅう)分(ぶん)に(　　)するのが難しいです。","options":["制作","保存","作成","確保"],"answer":4,"word_explain":"確保 (かくほ): đảm bảo, dành ra được (thời gian, nhân lực...)","translation_vi":"Sắp đến kỳ thi lấy chứng chỉ rồi mà dạo này công việc bận rộn nên rất khó để đảm bảo đủ thời gian học mỗi sáng."},{"mondai":4,"q":19,"prompt":"雑誌に新しい広告を出して、わが社の商品の良さを消費者にもっと(　　)したい。","options":["アピール","インストール","チャージ","セット"],"answer":1,"word_explain":"アピール: quảng bá, thể hiện sức hấp dẫn, thu hút sự chú ý","translation_vi":"Tôi muốn đăng quảng cáo mới trên tạp chí để quảng bá rõ hơn những ưu điểm của sản phẩm công ty chúng ta tới người tiêu dùng."},{"mondai":4,"q":20,"prompt":"失敗したことを(　　)より、気持ちを切り替えて、明日からまたがんばろうと思う。","options":["断る","疑う","悔やむ","あきらめる"],"answer":3,"word_explain":"悔やむ (くやむ): hối tiếc, ân hận","translation_vi":"Thay vì hối tiếc về việc đã thất bại, tôi nghĩ mình nên thay đổi tâm trạng và cố gắng lại từ ngày mai."},{"mondai":4,"q":21,"prompt":"わが社が海外への進出を考える(　　)となったのは、二年前の国際イベントだった。","options":["契(けい)機(き)","先(せん)端(たん)","始(し)発(はつ)","合(あい)図(ず)"],"answer":1,"word_explain":"契機 (けいき): cơ hội, bước ngoặt, động lực khởi đầu","translation_vi":"Sự kiện quốc tế hai năm trước chính là bước ngoặt khiến công ty chúng tôi nghĩ đến việc tiến ra nước ngoài."},{"mondai":4,"q":22,"prompt":"あの二人はさっきから(　　)話しているが、他人に聞かれては困る話なのだろうか。","options":["ぐっすり","うろうろ","ひそひそ","ばっさり"],"answer":3,"word_explain":"ひそひそ: thì thầm, nói nhỏ nhẹ","translation_vi":"Hai người kia nãy giờ cứ nói chuyện thì thầm với nhau, chẳng lẽ là chuyện ngại để người khác nghe thấy sao?"},{"mondai":5,"q":23,"prompt":"最近は生産が<u>過(か)剰(じょう)</u>であることが問題になっている。","options":["早すぎる","少なすぎる","遅すぎる","多すぎる"],"answer":4,"word_explain":"過剰 (かじょう) = 多すぎる: dư thừa, quá nhiều","translation_vi":"Gần đây việc sản xuất bị dư thừa đang trở thành vấn đề."},{"mondai":5,"q":24,"prompt":"もし資料に<u>あやまり</u>があったら知らせてください。","options":["読みにくいところ","汚れているところ","わかりにくいところ","間違っているところ"],"answer":4,"word_explain":"あやまり (誤り) = 間違っているところ: lỗi sai, chỗ nhầm lẫn","translation_vi":"Nếu trong tài liệu có chỗ sai sót thì hãy báo cho tôi biết nhé."},{"mondai":5,"q":25,"prompt":"うちの子は<u>臆(おく)病(びょう)</u>だ。","options":["よく病気をする","何でも怖がる","何でも忘れる","よく泣く"],"answer":2,"word_explain":"臆病 (おくびょう) = 何でも怖がる: nhút nhát, hay sợ sệt","translation_vi":"Con nhà tôi rất nhút nhát."},{"mondai":5,"q":26,"prompt":"高(たか)橋(はし)さんなら<u>とっくに</u>帰りましたよ。","options":["ずっと前に","一人で","あわてて","何も持たずに"],"answer":1,"word_explain":"とっくに = ずっと前に: từ lâu rồi, đã sớm (làm gì đó)","translation_vi":"Nếu là anh/chị Takahashi thì đã về từ lâu rồi đấy."},{"mondai":5,"q":27,"prompt":"あの自転車は弟に<u>ゆずりました</u>。","options":["貸しました","もらいました","あげました","借りました"],"answer":3,"word_explain":"ゆずりました (譲りました) = あげました: nhường lại, tặng lại","translation_vi":"Chiếc xe đạp đó tôi đã nhường lại cho em trai rồi."},{"mondai":6,"q":28,"prompt":"頂上","options":["この星は、夏の夜12時ごろ、空の<u>頂上</u>のあたりに見える。","山に登り始めて5時間ぐらいして、ようやく<u>頂上</u>に着いた。","この家の2階の部屋は、<u>頂上</u>にも窓がついているので、とても明るい。","本棚がいっぱいになってしまい、本棚の<u>頂上</u>にも本を置いている。"],"answer":2,"word_explain":"頂上 (ちょうじょう): đỉnh cao nhất (thường dùng cho đỉnh núi)","translation_vi":"Sau khi bắt đầu leo núi khoảng 5 tiếng, cuối cùng cũng đã lên đến đỉnh."},{"mondai":6,"q":29,"prompt":"節約","options":["駅に向かう道路の渋(じゅう)滞(たい)を<u>節約</u>するため、道の幅を広げる工事が行われている。","美術館の中は、かびが発生して絵が傷(いた)まないように、温度や湿度を<u>節約</u>しています。","試験が近くなってきたので、アルバイトの仕事を少し<u>節約</u>することにした。","私の会社では、紙や郵送費を<u>節約</u>するため、資料はすべてメールで送っている。"],"answer":4,"word_explain":"節約 (せつやく): tiết kiệm (tiền bạc, chi phí, điện, nước, giấy...)","translation_vi":"Ở công ty tôi, để tiết kiệm giấy và chi phí bưu điện, tất cả tài liệu đều được gửi qua email."},{"mondai":6,"q":30,"prompt":"分解","options":["機械の調子が悪かったので、<u>分解</u>して部品の点検をした。","すいかを買ってきたが、大きくて冷蔵庫に入らなかったので、四つに<u>分解</u>した。","細かいお金がなかったので、近くの店で千円札を<u>分解</u>してもらった。","急ぎの仕事が入ったので、三人で<u>分解</u>して進めることにした。"],"answer":1,"word_explain":"分解 (ぶんかい): tháo rời (máy móc thành bộ phận) hoặc phân giải (chất)","translation_vi":"Vì máy móc hoạt động không tốt nên tôi đã tháo rời ra để kiểm tra các linh kiện."},{"mondai":6,"q":31,"prompt":"略す","options":["時間がないので、詳しい説明は<u>略して</u>、要点だけお話しします。","合計で1万円以上ご購(こう)入(にゅう)の場合、送料は<u>略します</u>。","健康のために、砂(さ)糖(とう)を<u>略した</u>ジャムを使っています。","このオフィスは、壁を<u>略して</u>、開放感のあるデザインにしました。"],"answer":1,"word_explain":"略す (りゃくす): lược bỏ, rút gọn (lời nói, giải thích, thủ tục, tên gọi...)","translation_vi":"Vì không có thời gian nên tôi xin lược bỏ phần giải thích chi tiết và chỉ nói những điểm chính."},{"mondai":6,"q":32,"prompt":"覆(おお)う","options":["私のうちは、周りを高層マンションに<u>覆(おお)われて</u>いて、日当たりが悪い。","優勝した森(もり)選手は大勢の記者に<u>覆(おお)われて</u>インタビューを受けていた。","公園に続く並木道はすっかり落ち葉で<u>覆(おお)われて</u>いた。","部屋が暑いのか、中(なか)島(じま)さんの顔は汗で<u>覆(おお)われて</u>いた。"],"answer":3,"word_explain":"覆う (おおう): che phủ, bao phủ (tuyết, lá rụng, mây, khăn...)","translation_vi":"Con đường hàng cây dẫn vào công viên đã bị phủ kín hoàn toàn bởi lá rụng."}]},{"id":"2016_12","displayName":"12/2016","sourceFile":"Đề N2 12-2016.pdf","questions":[{"mondai":1,"q":1,"prompt":"先生に<u>貴重</u>な資料を見せていただいた。","options":["きじゅう","きちょう","きっじゅう","きっちょう"],"answer":2,"word_explain":"貴重 (きちょう): quý giá, quan trọng","translation_vi":"Tôi đã được thầy/cô giáo cho xem tài liệu quý giá."},{"mondai":1,"q":2,"prompt":"その話を聞いて、とても<u>怪しい</u>と思った。","options":["むなしい","くやしい","おかしい","あやしい"],"answer":4,"word_explain":"怪しい (あやしい): đáng ngờ, khả nghi","translation_vi":"Nghe câu chuyện đó, tôi cảm thấy rất đáng ngờ."},{"mondai":1,"q":3,"prompt":"佐藤さんは<u>容姿</u>も性格もいい。","options":["よし","ようし","ようす","よす"],"answer":2,"word_explain":"容姿 (ようし): dung mạo, ngoại hình","translation_vi":"Anh/chị Sato có cả ngoại hình lẫn tính cách đều tốt."},{"mondai":1,"q":4,"prompt":"これは危険を<u>伴う</u>実験だ。","options":["はらう","あつかう","ともなう","すくう"],"answer":3,"word_explain":"伴う (ともなう): đi kèm, kéo theo","translation_vi":"Đây là một thí nghiệm tiềm ẩn (đi kèm) nguy hiểm."},{"mondai":1,"q":5,"prompt":"以前は、海外で暮らしたいという<u>願望</u>が強かった。","options":["がんぼう","げんぼう","がんぼ","げんぼ"],"answer":1,"word_explain":"願望 (がんぼう): nguyện vọng, mong muốn","translation_vi":"Trước đây, nguyện vọng muốn sống ở nước ngoài của tôi rất mạnh mẽ."},{"mondai":2,"q":6,"prompt":"友人を家に<u>まねいた</u>。","options":["伯いた","招いた","泊いた","召いた"],"answer":2,"word_explain":"招く (まねく): mời","translation_vi":"Tôi đã mời bạn đến nhà."},{"mondai":2,"q":7,"prompt":"この商品は安全性が<u>ほしょう</u>されている。","options":["補証","保正","保証","補正"],"answer":3,"word_explain":"保証 (ほしょう): bảo đảm, bảo chứng","translation_vi":"Sản phẩm này được bảo đảm về tính an toàn."},{"mondai":2,"q":8,"prompt":"この企業では、さまざまな<u>もよおし</u>を行っている。","options":["携し","催し","推し","権し"],"answer":2,"word_explain":"催し (もよおし): sự kiện, buổi tổ chức","translation_vi":"Doanh nghiệp này đang tổ chức nhiều sự kiện đa dạng."},{"mondai":2,"q":9,"prompt":"銀行に行って、お札を<u>こうか</u>に替えた。","options":["硬貨","固貨","硬価","固価"],"answer":1,"word_explain":"硬貨 (こうか): tiền xu, tiền kim loại","translation_vi":"Tôi đã đến ngân hàng và đổi tiền giấy sang tiền xu."},{"mondai":2,"q":10,"prompt":"わが社の商品はここで<u>せいぞう</u>されている。","options":["製増","制増","制造","製造"],"answer":4,"word_explain":"製造 (せいぞう): sản xuất, chế tạo","translation_vi":"Sản phẩm của công ty chúng tôi được sản xuất tại đây."},{"mondai":3,"q":11,"prompt":"男女の結婚（　　）の違いについて調べた。","options":["観","識","念","察"],"answer":1,"word_explain":"結婚観 (けっこんかん): quan điểm về hôn nhân","translation_vi":"Tôi đã tìm hiểu về sự khác biệt trong quan điểm hôn nhân giữa nam và nữ."},{"mondai":3,"q":12,"prompt":"ここでは（　　）水準の医療が受けられる。","options":["頂","上","高","特"],"answer":3,"word_explain":"高水準 (こうすいじゅん): trình độ cao, mức độ cao","translation_vi":"Ở đây có thể tiếp nhận dịch vụ y tế trình độ cao."},{"mondai":3,"q":13,"prompt":"今日は大学の講義で日本（　　）の経営について学んだ。","options":["状","類","式","則"],"answer":3,"word_explain":"日本式 (にほんしき): kiểu Nhật, phong cách Nhật Bản","translation_vi":"Hôm nay tôi đã học về cách quản lý kiểu Nhật trong bài giảng ở trường đại học."},{"mondai":3,"q":14,"prompt":"開封しても、（　　）使用の物は返品可能です。","options":["外","否","前","未"],"answer":4,"word_explain":"未使用 (みしよう): chưa sử dụng","translation_vi":"Dù đã mở hộp nhưng những món đồ chưa qua sử dụng vẫn có thể trả lại."},{"mondai":3,"q":15,"prompt":"受験生なので、勉強（　　）の毎日だ。","options":["漬け","浸し","溶け","満ち"],"answer":1,"word_explain":"勉強漬け (べんきょうづけ): ngập đầu trong việc học, suốt ngày chỉ học","translation_vi":"Vì là sĩ tử nên ngày nào cũng ngập đầu trong việc học."},{"mondai":4,"q":16,"prompt":"この大学では一般向けの講座を開き、社会に学習の場を（　　）している。","options":["選出","提供","指示","寄付"],"answer":2,"word_explain":"提供 (ていきょう): cung cấp","translation_vi":"Trường đại học này mở các khóa học dành cho công chúng, cung cấp môi trường học tập cho xã hội."},{"mondai":4,"q":17,"prompt":"今年の夏は暑さが厳(きび)しく、仕事から家に帰ると疲れて（　　）してしまう。","options":["ぐったり","しっかり","すっきり","ぎっしり"],"answer":1,"word_explain":"ぐったり: mệt lả, rũ rượi","translation_vi":"Mùa hè năm nay nóng khắc nghiệt nên cứ đi làm về đến nhà là tôi lại mệt lả người."},{"mondai":4,"q":18,"prompt":"学生時代の友人が私の名前を忘れていたので、とても（　　）だった。","options":["アウト","ダウン","ショック","エラー"],"answer":3,"word_explain":"ショック: sốc, bàng hoàng","translation_vi":"Người bạn thời sinh viên đã quên mất tên tôi nên tôi rất sốc."},{"mondai":4,"q":19,"prompt":"通路に荷物を置いたら、通る人の（　　）になりますよ。","options":["面倒","邪魔","被害","無理"],"answer":2,"word_explain":"邪魔 (じゃま): cản trở, vướng víu","translation_vi":"Nếu để hành lý ở lối đi thì sẽ gây cản trở cho người qua lại đấy."},{"mondai":4,"q":20,"prompt":"少し長めの上(のぼ)り坂(ざか)だったが（　　）ので、それほど疲れなかった。","options":["おとなしかった","ささやかだった","なだらかだった","よわよわしかった"],"answer":3,"word_explain":"なだらか: thoai thoải, dốc nhẹ","translation_vi":"Tuy là con dốc đi lên hơi dài một chút nhưng vì thoai thoải nên tôi không mệt lắm."},{"mondai":4,"q":21,"prompt":"出席者は皆会議に積極的に参加し、意見を（　　）交換し合った。","options":["活発に","円満に","機敏に","濃厚に"],"answer":1,"word_explain":"活発に (かっぱつに): một cách sôi nổi, tích cực","translation_vi":"Những người tham dự đều tích cực tham gia cuộc họp và trao đổi ý kiến một cách sôi nổi."},{"mondai":4,"q":22,"prompt":"列に並んでいたら、私の前に強引に（　　）きた人がいて、嫌な気分になった。","options":["当てはまって","付け加えて","行き着いて","割り込んで"],"answer":4,"word_explain":"割り込む (わりこむ): chen ngang, chen hàng","translation_vi":"Khi tôi đang xếp hàng thì có người cố tình chen ngang lên trước tôi khiến tôi cảm thấy rất khó chịu."},{"mondai":5,"q":23,"prompt":"高橋さんはとても<u>愉快な</u>人だ。","options":["面白い","おしゃれな","親切な","かわいい"],"answer":1,"word_explain":"愉快な (ゆかいな) = 面白い: vui vẻ, thú vị","translation_vi":"Anh/chị Takahashi là một người rất vui vẻ, thú vị."},{"mondai":5,"q":24,"prompt":"それは確かに<u>やむをえない</u>ことだと思う。","options":["もったいない","なさけない","つまらない","しかたない"],"answer":4,"word_explain":"やむをえない = しかたない: đành chịu, bất đắc dĩ","translation_vi":"Tôi nghĩ điều đó quả thực là chuyện bất đắc dĩ (không còn cách nào khác)."},{"mondai":5,"q":25,"prompt":"少し<u>息抜きした</u>ほうがいいよ。","options":["待った","急いだ","休んだ","働いた"],"answer":3,"word_explain":"息抜きする (いきぬきする) = 休む: nghỉ ngơi, xả hơi","translation_vi":"Cậu nên nghỉ ngơi thư giãn một chút đi."},{"mondai":5,"q":26,"prompt":"今日はとても<u>ついていた</u>。","options":["気分が悪かった","運が悪かった","気分がよかった","運がよかった"],"answer":4,"word_explain":"ついている = 運がよい: may mắn, gặp may","translation_vi":"Hôm nay tôi rất gặp may."},{"mondai":5,"q":27,"prompt":"私は<u>つねに</u>言葉遣いに気をつけている。","options":["当然","いつも","特に","できるだけ"],"answer":2,"word_explain":"つねに (常に) = いつも: luôn luôn, lúc nào cũng","translation_vi":"Tôi luôn chú ý đến cách ăn nói của mình."},{"mondai":6,"q":28,"prompt":"延長","options":["悪天候で列車が運転をやめたため、旅行の出発が三日後に<u>延長</u>された。","初めの設計では２階建てだったが、3階建ての家に<u>延長</u>することにした。","予定の時間内に結論が出ず、会議が1時間<u>延長</u>されることになった。","電車の中で居眠りをして、降りる駅を一駅<u>延長</u>してしまった。"],"answer":3,"word_explain":"延長 (えんちょう): kéo dài (thời gian, khoảng cách đang diễn ra); không dùng cho hoãn ngày bắt đầu (延期) hay đi quá trạm (乗り過ごす)","translation_vi":"Vì không đưa ra được kết luận trong thời gian dự kiến nên cuộc họp đã được kéo dài thêm 1 tiếng."},{"mondai":6,"q":29,"prompt":"さびる","options":["暑いところに生ものをずっと置いておいたら、<u>さびて</u>臭くなった。","昨夜は雨が相当降ったらしく、普段はきれいな川の水が<u>さびて</u>濁っている。","鉢に植えた植物に水をやるのを忘れていたら、花が<u>さびて</u>しまった。","この鉄の棒はずっと家の外に置いてあったので、<u>さびて</u>茶色くなっている。"],"answer":4,"word_explain":"さびる (錆びる): bị gỉ sét (kim loại bị oxy hóa)","translation_vi":"Thanh sắt này cứ để mãi ở ngoài nhà nên đã bị gỉ sét và chuyển sang màu nâu."},{"mondai":6,"q":30,"prompt":"目上","options":["勉強会に参加した社員がすべて<u>目上</u>だったので、新人の私はとても緊張した。","この店で一番値段が高く<u>目上</u>の商品は、店の奥にある棚に並べられていた。","高校時代、鈴木さんはとても優秀で、成績はいつも学年で<u>目上</u>だった。","あの若さで金賞を受賞した伊藤さんは、本当に<u>目上</u>の人だと思う。"],"answer":1,"word_explain":"目上 (めうえ): người bề trên (lớn tuổi hơn hoặc chức vụ, địa vị cao hơn mình)","translation_vi":"Vì tất cả nhân viên tham gia buổi học tập đều là người bề trên (tiền bối/cấp trên) nên nhân viên mới như tôi đã rất căng thẳng."},{"mondai":6,"q":31,"prompt":"大げさ","options":["息子の誕生日に料理を作りすぎてしまい、<u>大げさ</u>に余ってしまった。","天気予報によると、明日は今日より<u>大げさ</u>に気温が下がるらしい。","努力した結果、試験の成績が<u>大げさ</u>に伸びて、先生に褒められた。","あの人は小さなことを<u>大げさ</u>に言うので、そのまま信じないほうがいい。"],"answer":4,"word_explain":"大げさ (おおげさ): phóng đại, nói quá, làm quá lên","translation_vi":"Người đó hay nói quá những chuyện nhỏ nhặt nên không nên tin hoàn toàn như vậy."},{"mondai":6,"q":32,"prompt":"反省","options":["発表の原稿を全部覚えたのに、緊張のせいでどんなに<u>反省</u>しても全く思い出せない。","今回の企画では、私の準備不足で周りに迷惑をかけたことをとても<u>反省</u>しています。","祖父はいつも若いころの思い出を懐かしそうに<u>反省</u>して私に話してくれる。","この機械の使い方を忘れないように、もう一度最初から<u>反省</u>しておきましょう。"],"answer":2,"word_explain":"反省 (はんせい): tự kiểm điểm, nhìn nhận lại lỗi lầm hay thiếu sót của bản thân","translation_vi":"Trong kế hoạch lần này, tôi rất tự kiểm điểm (hối lỗi) về việc mình chuẩn bị thiếu sót và gây phiền phức cho mọi người xung quanh."}]},{"id":"2016_07","displayName":"07/2016","sourceFile":"Đề N2 7-2016.pdf","questions":[{"mondai":1,"q":1,"prompt":"歯医者に行って虫歯の<u>治療</u>を受けた。","options":["じりょ","ちりょ","じりょう","ちりょう"],"answer":4,"word_explain":"治療 (ちりょう): điều trị, chữa trị","translation_vi":"Tôi đã đi nha sĩ để điều trị sâu răng."},{"mondai":1,"q":2,"prompt":"私たちはテストのたびに学年でトップを<u>競って</u>いた。","options":["きそって","ねらって","あらそって","うばって"],"answer":1,"word_explain":"競う (きそう): cạnh tranh, thi đua","translation_vi":"Mỗi lần kiểm tra chúng tôi đều cạnh tranh vị trí đứng đầu toàn khối."},{"mondai":1,"q":3,"prompt":"今月の雑誌に新しい映画の<u>批評</u>が掲載された。","options":["ひびょう","ひべい","ひへい","ひひょう"],"answer":4,"word_explain":"批評 (ひひょう): phê bình, bình luận, đánh giá","translation_vi":"Bài phê bình về bộ phim mới đã được đăng trên tạp chí tháng này."},{"mondai":1,"q":4,"prompt":"期日までに入学金を<u>納めた</u>。","options":["さだめた","ためた","おさめた","もとめた"],"answer":3,"word_explain":"納める (おさめる): nộp, đóng (tiền)","translation_vi":"Tôi đã nộp tiền nhập học trước thời hạn."},{"mondai":1,"q":5,"prompt":"A社の製品は他社のものより品質が<u>劣る</u>。","options":["まける","おとる","へる","おちる"],"answer":2,"word_explain":"劣る (おとる): kém hơn, thua kém","translation_vi":"Sản phẩm của công ty A có chất lượng kém hơn so với sản phẩm của công ty khác."},{"mondai":2,"q":6,"prompt":"文章は<u>かんけつ</u>に書いてください。","options":["完決","簡決","簡潔","完潔"],"answer":3,"word_explain":"簡潔 (かんけつ): ngắn gọn, súc tích","translation_vi":"Xin hãy viết câu văn một cách ngắn gọn, súc tích."},{"mondai":2,"q":7,"prompt":"具体的な内容については、本日お配りした資料をご<u>さんしょう</u>ください。","options":["賛照","参照","賛考","参考"],"answer":2,"word_explain":"参照 (さんしょう): tham chiếu, đối chiếu, xem thêm","translation_vi":"Về nội dung cụ thể, xin vui lòng xem thêm tài liệu đã phát hôm nay."},{"mondai":2,"q":8,"prompt":"火が強すぎて、肉が<u>こげて</u>しまった。","options":["焦げて","焼げて","熱げて","煙げて"],"answer":1,"word_explain":"焦げる (こげる): cháy xém, khét","translation_vi":"Vì lửa quá mạnh nên thịt đã bị cháy khét mất rồi."},{"mondai":2,"q":9,"prompt":"診察室で医者に<u>しょうじょう</u>を伝えた。","options":["障情","障状","症情","症状"],"answer":4,"word_explain":"症状 (しょうじょう): triệu chứng","translation_vi":"Tôi đã trình bày các triệu chứng với bác sĩ trong phòng khám."},{"mondai":2,"q":10,"prompt":"急なお願いにもかかわらず、森さんは<u>こころよく</u>応じてくれた。","options":["希く","快く","敬く","喜く"],"answer":2,"word_explain":"快く (こころよく): vui vẻ, sẵn lòng","translation_vi":"Mặc dù là lời nhờ vả đột ngột nhưng anh/chị Mori đã vui vẻ nhận lời giúp tôi."},{"mondai":3,"q":11,"prompt":"留学を通して(　　)文化に触れ、多くのことを学んだ。","options":["差","違","離","異"],"answer":4,"word_explain":"異文化 (いぶんか): nền văn hóa khác, văn hóa nước ngoài","translation_vi":"Thông qua việc du học, tôi đã tiếp xúc với nền văn hóa khác và học hỏi được nhiều điều."},{"mondai":3,"q":12,"prompt":"この絵画展では、森氏の作品が年代(　　)に紹介されている。","options":["順","連","番","序"],"answer":1,"word_explain":"年代順 (ねんだいじゅん): theo thứ tự thời gian, theo niên đại","translation_vi":"Tại triển lãm tranh này, các tác phẩm của ông Mori được giới thiệu theo thứ tự niên đại."},{"mondai":3,"q":13,"prompt":"この土地は、国の管理(　　)に置かれている。","options":["属","付","下","限"],"answer":3,"word_explain":"管理下 (かんりか): dưới sự quản lý","translation_vi":"Mảnh đất này đang được đặt dưới sự quản lý của nhà nước."},{"mondai":3,"q":14,"prompt":"今月から駅前の(　　)開発が始まった。","options":["改","復","再","重"],"answer":3,"word_explain":"再開発 (さいかいはつ): tái phát triển, quy hoạch lại","translation_vi":"Từ tháng này, dự án tái phát triển khu vực trước nhà ga đã bắt đầu."},{"mondai":3,"q":15,"prompt":"この薬の(　　)成分を確認した。","options":["真","主","本","要"],"answer":2,"word_explain":"主成分 (しゅせいぶん): thành phần chính","translation_vi":"Tôi đã kiểm tra thành phần chính của loại thuốc này."},{"mondai":4,"q":16,"prompt":"その話が本当かどうか分からないのに、確認もしないで(　　)信じてしまった。","options":["率直に","安易に","柔軟に","短気に"],"answer":2,"word_explain":"安易に (あんいに): một cách dễ dãi, nhẹ dạ, thiếu suy xét","translation_vi":"Dù không biết câu chuyện đó có thật hay không nhưng tôi đã chẳng kiểm chứng mà nhẹ dạ tin ngay."},{"mondai":4,"q":17,"prompt":"今年は天候に恵まれたので、昨年を上回る量の農作物が(　　)できるだろう。","options":["収穫","成立","採集","取得"],"answer":1,"word_explain":"収穫 (しゅうかく): thu hoạch","translation_vi":"Năm nay nhờ thời tiết thuận lợi nên có lẽ sẽ thu hoạch được lượng nông sản vượt qua năm ngoái."},{"mondai":4,"q":18,"prompt":"先週は忙しかったので、週末は家で本を読んで(　　)過ごした。","options":["だぶだぶ","がらがら","ぐっすり","のんびり"],"answer":4,"word_explain":"のんびり: thong thả, thư thái, nhàn nhã","translation_vi":"Tuần trước tôi bận rộn nên cuối tuần đã đọc sách ở nhà và tận hưởng thời gian thư thái."},{"mondai":4,"q":19,"prompt":"このサービスの利用者はまだ少なく、一般の人々に(　　)するには時間がかかるだろう。","options":["普及","充満","伝染","進行"],"answer":1,"word_explain":"普及 (ふきゅう): phổ cập, lan rộng, phổ biến","translation_vi":"Người sử dụng dịch vụ này vẫn còn ít, có lẽ sẽ mất thời gian để phổ biến đến đông đảo mọi người."},{"mondai":4,"q":20,"prompt":"話したいことがあったので、帰ろうとした友人を(　　)。","options":["取り付けた","引き止めた","持ち寄った","受け入れた"],"answer":2,"word_explain":"引き止める (ひきとめる): giữ lại, níu lại","translation_vi":"Vì có chuyện muốn nói nên tôi đã giữ người bạn đang định ra về lại."},{"mondai":4,"q":21,"prompt":"林さんは企画チームの(　　)として、部下をまとめ、導いていく責任がある。","options":["ライバル","ゲスト","リーダー","ファン"],"answer":3,"word_explain":"リーダー: trưởng nhóm, người lãnh đạo","translation_vi":"Anh/chị Hayashi, với tư cách là trưởng nhóm kế hoạch, có trách nhiệm gắn kết và dẫn dắt cấp dưới."},{"mondai":4,"q":22,"prompt":"外国語が得意な森さんは、海外旅行の時に通訳をして皆を助けてくれて、とても(　　)。","options":["したしかった","なつかしかった","くわしかった","たのもしかった"],"answer":4,"word_explain":"頼もしい (たのもしい): đáng tin cậy, vững chãi","translation_vi":"Anh/chị Mori giỏi ngoại ngữ đã phiên dịch giúp đỡ mọi người khi đi du lịch nước ngoài, trông thật đáng tin cậy."},{"mondai":5,"q":23,"prompt":"佐藤氏は、<u>たびたび</u>この店を訪れた。","options":["必ず","ようやく","偶然","何度も"],"answer":4,"word_explain":"たびたび = 何度も: nhiều lần, thường xuyên","translation_vi":"Ông Sato đã nhiều lần ghé thăm cửa hàng này."},{"mondai":5,"q":24,"prompt":"今日の林氏の発言に皆が<u>注目した</u>。","options":["関心を持った","疑問を持った","感動した","驚いた"],"answer":1,"word_explain":"注目する (ちゅうもくする) = 関心を持つ: chú ý, quan tâm","translation_vi":"Mọi người đều chú ý đến phát biểu hôm nay của ông Hayashi."},{"mondai":5,"q":25,"prompt":"このことは本人に<u>じかに</u>伝えてください。","options":["直接","あとで","すべて","確実に"],"answer":1,"word_explain":"じかに (直に) = 直接: trực tiếp","translation_vi":"Xin hãy truyền đạt trực tiếp chuyện này cho chính người đó."},{"mondai":5,"q":26,"prompt":"もう少しで<u>衝突する</u>ところだった。","options":["倒れる","壊れる","ぶつかる","破れる"],"answer":3,"word_explain":"衝突する (しょうとつする) = ぶつかる: va chạm, đụng phải","translation_vi":"Suýt chút nữa là đã xảy ra va chạm rồi."},{"mondai":5,"q":27,"prompt":"高橋さんは、そんな<u>ひきょうな</u>やり方はしませんよ。","options":["危ない","ずるい","厳しい","しつこい"],"answer":2,"word_explain":"ひきょうな (卑怯な) = ずるい: hèn hạ, gian lận, chơi xấu","translation_vi":"Anh/chị Takahashi sẽ không làm theo cách hèn hạ (chơi xấu) như vậy đâu."},{"mondai":6,"q":28,"prompt":"発達","options":["息子が中学生になって急に身長が<u>発達</u>し、すぐに私を追い越した。","交通が<u>発達</u>したことにより、人々の生活が便利になった。","この店は昨年度からサービスの<u>発達</u>に努め、客数を増やした。","庭に植えたトマトの<u>発達</u>がよく、おいしそうな赤い実がたくさんとれた。"],"answer":2,"word_explain":"発達 (はったつ): phát triển (dùng cho giao thông, kỹ thuật, cơ quan cơ thể, bão...)","translation_vi":"Nhờ giao thông phát triển mà cuộc sống của mọi người trở nên tiện lợi hơn."},{"mondai":6,"q":29,"prompt":"きっかけ","options":["今回は都合が悪いのですが、次の<u>きっかけ</u>にはぜひ出席したいと思います。","大学では言語学を専攻し、漢字の<u>きっかけ</u>について研究している。","今回の事件を<u>きっかけ</u>に、市民の防犯に対する意識が高まった。","この事業に反対する<u>きっかけ</u>は、環境への悪影響が予想されるからだ。"],"answer":3,"word_explain":"きっかけ: cơ duyên, nguyên nhân khởi đầu, bước ngoặt (thường dùng dạng 「～をきっかけに」)","translation_vi":"Nhân sự việc lần này, ý thức phòng chống tội phạm của người dân đã được nâng cao."},{"mondai":6,"q":30,"prompt":"引退","options":["ひどい風邪を引いてしまい、明日のスピーチ大会は<u>引退</u>するしかない。","試験が近いのでアルバイトを<u>引退</u>し、勉強に専念することにした。","鈴木選手は去年<u>引退</u>し、家族で海外に移住したそうだ。","A社の面接に合格したが、<u>引退</u>して別の会社に入社した。"],"answer":3,"word_explain":"引退 (いんたい): giải nghệ, rút lui (vận động viên, nghệ sĩ, chính trị gia...)","translation_vi":"Nghe nói tuyển thủ Suzuki đã giải nghệ vào năm ngoái và cùng gia đình chuyển ra nước ngoài sinh sống."},{"mondai":6,"q":31,"prompt":"順調","options":["佐藤先生はどんな質問に対しても<u>順調</u>に答えてくれる。","今日は朝からのどが痛くて、食べ物を<u>順調</u>に飲み込めない。","雨で道路が滑りやすくなっていたので、<u>順調</u>に転んでしまった。","このパソコンは発売以来、<u>順調</u>に売り上げを伸ばし、人気商品になった。"],"answer":4,"word_explain":"順調 (じゅんちょう): thuận lợi, suôn sẻ (dùng cho tiến triển công việc, doanh thu, hồi phục...)","translation_vi":"Chiếc máy tính này kể từ khi ra mắt đã tăng doanh số một cách thuận lợi và trở thành sản phẩm được ưa chuộng."},{"mondai":6,"q":32,"prompt":"生じる","options":["海外の生活では、習慣の違いから誤解が<u>生じる</u>ことがある。","この果物は温暖な気候の地域を中心に<u>生じている</u>。","新しい技術が<u>生じた</u>おかげで、生産量が大幅に増加した。","この大学からは有名な研究者が多く<u>生じている</u>。"],"answer":1,"word_explain":"生じる (しょうじる): phát sinh, nảy sinh (hiểu lầm, vấn đề, chênh lệch, thay đổi...)","translation_vi":"Trong cuộc sống ở nước ngoài, có những lúc phát sinh hiểu lầm do sự khác biệt về tập quán."}]},{"id":"2015_12","displayName":"12/2015","sourceFile":"Đề N2 12-2015.pdf","questions":[{"mondai":1,"q":1,"prompt":"迷惑なメールの受信を<u>拒否</u>したい。","options":["きょうひ","きょうふ","きょひ","きょふ"],"answer":3,"word_explain":"拒否 (きょひ): từ chối, khước từ","translation_vi":"Tôi muốn từ chối nhận các email làm phiền."},{"mondai":1,"q":2,"prompt":"鈴木選手は試合の後、多くの記者に<u>囲まれて</u>質問を受けていた。","options":["かこまれて","つつまれて","はさまれて","つかまれて"],"answer":1,"word_explain":"囲まれて (かこまれて): bị vây quanh, bao quanh (từ động từ 囲む)","translation_vi":"Sau trận đấu, vận động viên Suzuki bị nhiều phóng viên vây quanh và nhận câu hỏi."},{"mondai":1,"q":3,"prompt":"何とか<u>損害</u>を最小限に抑えることができた。","options":["さいかい","さいがい","そんかい","そんがい"],"answer":4,"word_explain":"損害 (そんがい): tổn hại, thiệt hại","translation_vi":"Bằng cách nào đó, chúng tôi đã có thể kiềm chế thiệt hại ở mức tối thiểu."},{"mondai":1,"q":4,"prompt":"この<u>現象</u>は、これまでの理論では説明ができない。","options":["げんそう","げんしょう","げんぞう","げんじょう"],"answer":2,"word_explain":"現象 (げんしょう): hiện tượng","translation_vi":"Hiện tượng này không thể giải thích bằng các lý thuyết từ trước đến nay."},{"mondai":1,"q":5,"prompt":"私は今まで人を<u>憎い</u>と思ったことがない。","options":["こわい","ひどい","にくい","ずるい"],"answer":3,"word_explain":"憎い (にくい): đáng ghét, đáng căm ghét","translation_vi":"Từ trước đến nay tôi chưa từng nghĩ ai là đáng ghét."},{"mondai":2,"q":6,"prompt":"多くの人が集まったため、会場の中は<u>こんらん</u>していた。","options":["混乱","混雑","困乱","困雑"],"answer":1,"word_explain":"混乱 (こんらん): hỗn loạn, rối loạn","translation_vi":"Vì có nhiều người tập trung lại nên bên trong hội trường đã trở nên hỗn loạn."},{"mondai":2,"q":7,"prompt":"この計画は<u>じゅんちょう</u>に進んでいる。","options":["準長","準調","順長","順調"],"answer":4,"word_explain":"順調 (じゅんちょう): thuận lợi, suôn sẻ","translation_vi":"Kế hoạch này đang tiến triển thuận lợi."},{"mondai":2,"q":8,"prompt":"新製品の販売権に関し、Ａ社とＢ社が<u>あらそって</u>いる。","options":["争って","戦って","競って","抗って"],"answer":1,"word_explain":"争って (あらそって): tranh giành, tranh chấp (từ 争う)","translation_vi":"Liên quan đến quyền bán sản phẩm mới, công ty A và công ty B đang tranh giành nhau."},{"mondai":2,"q":9,"prompt":"先生に<u>してき</u>された部分を直して、レポートを再提出した。","options":["指的","指摘","支的","支摘"],"answer":2,"word_explain":"指摘 (してき): chỉ ra, lưu ý, phê bình","translation_vi":"Tôi đã sửa phần được giáo viên chỉ ra và nộp lại báo cáo."},{"mondai":2,"q":10,"prompt":"この絵は空の色がとても<u>あざやか</u>だ。","options":["照やか","晴やか","鮮やか","濃やか"],"answer":3,"word_explain":"鮮やか (あざやか): rực rỡ, tươi sáng, sắc nét","translation_vi":"Bức tranh này có màu sắc bầu trời rất rực rỡ."},{"mondai":3,"q":11,"prompt":"試合会場には、各チームの応援(　　)も来ている。","options":["党","団","集","族"],"answer":2,"word_explain":"応援団 (おうえんだん): đội cổ vũ, hội cổ động viên","translation_vi":"Tại địa điểm thi đấu, đội cổ vũ của các đội cũng đã đến."},{"mondai":3,"q":12,"prompt":"その計画は自然環境に(　　)影響を与えかねない。","options":["陰","劣","危","悪"],"answer":4,"word_explain":"悪影響 (あくえいきょう): ảnh hưởng xấu, tác động tiêu cực","translation_vi":"Kế hoạch đó có nguy cơ gây ra ảnh hưởng xấu đến môi trường tự nhiên."},{"mondai":3,"q":13,"prompt":"今回の実験の成功(　　)は高いと言われている。","options":["倍","割","比","率"],"answer":4,"word_explain":"成功率 (せいこうりつ): tỷ lệ thành công","translation_vi":"Tỷ lệ thành công của thí nghiệm lần này được cho là cao."},{"mondai":3,"q":14,"prompt":"彼の話はあまりに現実(　　)していて、誰も同意しなかった。","options":["抜け","落ち","離れ","逃げ"],"answer":3,"word_explain":"現実離れ (げんじつばなれ): xa rời thực tế, phi thực tế","translation_vi":"Câu chuyện của anh ấy quá xa rời thực tế nên không ai đồng ý cả."},{"mondai":3,"q":15,"prompt":"この辺りはヨーロッパ(　　)の家が多くて、日本だとは思えない。","options":["風","状","態","類"],"answer":1,"word_explain":"ヨーロッパ風 (ヨーロッパふう): kiểu châu Âu, phong cách châu Âu","translation_vi":"Khu vực này có nhiều ngôi nhà kiểu châu Âu đến mức không thể nghĩ đây là Nhật Bản."},{"mondai":4,"q":16,"prompt":"日本の１０年後の人口を、様々なデータから(　　)した。","options":["予測","予報","予感","予習"],"answer":1,"word_explain":"予測 (よそく): dự đoán, ước tính (dựa trên dữ liệu, căn cứ)","translation_vi":"Chúng tôi đã dự đoán dân số Nhật Bản sau 10 năm nữa từ nhiều loại dữ liệu khác nhau."},{"mondai":4,"q":17,"prompt":"川の水が茶色く(　　)いて、底の方が見えない。","options":["くもって","かくれて","にごって","くずれて"],"answer":3,"word_explain":"にごって (濁って): bị đục, vẩn đục (từ 濁る)","translation_vi":"Nước sông bị đục ngầu màu nâu nên không thể nhìn thấy phần đáy."},{"mondai":4,"q":18,"prompt":"この書類に必要なことを記入して窓口に提出すれば、手続きは(　　)します。","options":["完了","決定","実現","達成"],"answer":1,"word_explain":"完了 (かんりょう): hoàn tất, hoàn thành","translation_vi":"Nếu bạn điền những thông tin cần thiết vào giấy tờ này và nộp ở quầy tiếp nhận thì thủ tục sẽ hoàn tất."},{"mondai":4,"q":19,"prompt":"栄養の(　　)を考えて、いろいろなものを食べましょう。","options":["ストレス","バランス","チェンジ","ステップ"],"answer":2,"word_explain":"バランス: sự cân bằng","translation_vi":"Hãy suy nghĩ đến sự cân bằng dinh dưỡng và ăn nhiều loại thức ăn khác nhau."},{"mondai":4,"q":20,"prompt":"この店の料理は、量が(　　)あるので、たくさん食べる人に人気があります。","options":["ふんわり","すっきり","たっぷり","ぼんやり"],"answer":3,"word_explain":"たっぷり: nhiều, đầy đặn, dồi dào","translation_vi":"Món ăn của quán này có lượng rất nhiều nên được những người ăn khỏe ưa chuộng."},{"mondai":4,"q":21,"prompt":"二人の間には意見の(　　)があり、なかなか議論が進まない。","options":["対比","間隔","大別","相違"],"answer":4,"word_explain":"相違 (そうい): sự khác biệt, bất đồng","translation_vi":"Giữa hai người có sự bất đồng về ý kiến nên cuộc thảo luận mãi không tiến triển được."},{"mondai":4,"q":22,"prompt":"約束の時間より早く来てしまったので、喫茶店に入って時間を(　　)。","options":["やぶった","つぶした","こわした","はずった"],"answer":2,"word_explain":"つぶした (潰した): đã giết (thời gian) (cụm 時間をつぶす: giết thời gian)","translation_vi":"Vì lỡ đến sớm hơn giờ hẹn nên tôi đã vào quán cà phê để giết thời gian."},{"mondai":5,"q":23,"prompt":"明日は今日より<u>やや</u>涼しくなると思います。","options":["絶対","もっと","たぶん","少し"],"answer":4,"word_explain":"やや = 少し: hơi, một chút","translation_vi":"Tôi nghĩ ngày mai sẽ mát hơn hôm nay một chút."},{"mondai":5,"q":24,"prompt":"私はこれくらいの<u>テンポ</u>の曲が歌いやすいと思う。","options":["速さ","長さ","高さ","明るさ"],"answer":1,"word_explain":"テンポ = 速さ: nhịp độ, tốc độ","translation_vi":"Tôi thấy bài hát có nhịp độ khoảng chừng này thì dễ hát."},{"mondai":5,"q":25,"prompt":"昨日、<u>妙な</u>話を聞いた。","options":["うれしい","変な","なつかしい","嫌な"],"answer":2,"word_explain":"妙な (みょうな) = 変な: kỳ lạ, kỳ quặc","translation_vi":"Hôm qua tôi đã nghe một câu chuyện kỳ lạ."},{"mondai":5,"q":26,"prompt":"高橋さんは、<u>ささやくように</u>話した。","options":["急いで","ゆっくり","大声で","小声で"],"answer":4,"word_explain":"ささやくように = 小声で: thì thầm, nói nhỏ nhẹ","translation_vi":"Anh/Chị Takahashi đã nói chuyện như thể thì thầm (bằng giọng nhỏ)."},{"mondai":5,"q":27,"prompt":"鈴木氏は、<u>かつて</u>フランスに住んでいた。","options":["確か","主に","以前","しばらく"],"answer":3,"word_explain":"かつて = 以前: trước đây, từng","translation_vi":"Ông Suzuki trước đây đã từng sống ở Pháp."},{"mondai":6,"q":28,"prompt":"作成","options":["外国語の練習のために、話す機会を多く<u>作成</u>している。","今週中に会議の資料を<u>作成</u>しておいてください。","この地域で<u>作成</u>された果物はとてもおいしい。","友人と共同で新しい会社を<u>作成</u>することにした。"],"answer":2,"word_explain":"作成 (さくせい): tạo lập, soạn thảo (dùng cho tài liệu, văn bản, kế hoạch, danh sách, dữ liệu...)","translation_vi":"Hãy soạn thảo sẵn tài liệu cuộc họp trong tuần này nhé."},{"mondai":6,"q":29,"prompt":"いったん","options":["私はまだ海外に<u>いったん</u>も行ったことがないので、いつか行きたいと思っている。","彼とはずいぶん前に<u>いったん</u>しか会っていないが、顔も名前もよく覚えている。","部長は外出先から会社に<u>いったん</u>戻ったが、すぐにまた出かけた。","学生のころは、友人と１週間に<u>いったん</u>映画を見に行った。"],"answer":3,"word_explain":"いったん (一旦): tạm thời, một lần (làm một việc gì đó trước khi chuyển sang hành động tiếp theo)","translation_vi":"Trưởng phòng từ bên ngoài đã quay tạm về công ty một lát, nhưng ngay sau đó lại đi ra ngoài tiếp."},{"mondai":6,"q":30,"prompt":"思いつく","options":["今は大変だが、将来成功している自分の姿を<u>思いつく</u>と、頑張ろうと思える。","このアイディアは仕事中ではなく、散歩しているときに<u>思いついた</u>。","佐藤さんに初めて会ったとき、この人とは親友になれそうだと思いついた。","この写真を見ると、いつも学生時代のことを<u>思いついて</u>、同級生に会いたくなる。"],"answer":2,"word_explain":"思いつく (おもいつく): nảy ra, nghĩ ra (ý tưởng, sáng kiến, cách làm...)","translation_vi":"Ý tưởng này không phải lúc đang làm việc mà là lúc đang đi dạo tôi mới nảy ra."},{"mondai":6,"q":31,"prompt":"中断","options":["参加の希望者が集まらないので、来週のイベントは<u>中断</u>されることになった。","この山には、曲がって枯れた木や<u>中断</u>した木がたくさんある。","林さんは今勤めている会社を<u>中断</u>して、別の会社に転職するらしい。","雨が強くなって試合が<u>中断</u>されているが、恐らく再開は難しいだろう。"],"answer":4,"word_explain":"中断 (ちゅうだん): gián đoạn, tạm dừng giữa chừng (một hoạt động đang diễn ra)","translation_vi":"Trời mưa to nên trận đấu đang bị tạm dừng giữa chừng, nhưng có lẽ sẽ khó mà tiếp tục lại được."},{"mondai":6,"q":32,"prompt":"たくましい","options":["両親は今までどんな苦労にも負けずに、<u>たくましく</u>生きてきた。","このひもは細くてすぐ切れそうなので、もっと<u>たくましい</u>のが欲しい。","森さんは仕事の経験が<u>たくましい</u>ので、上司から信頼されている。","昼になって急に日ざしが<u>たくましく</u>なったので、帽子をかぶった。"],"answer":1,"word_explain":"たくましい (逞しい): mạnh mẽ, kiên cường, vạm vỡ (về tinh thần hoặc thể chất)","translation_vi":"Bố mẹ tôi từ trước đến nay không khuất phục trước bất kỳ gian khổ nào và đã sống rất kiên cường."}]},{"id":"2015_07","displayName":"07/2015","sourceFile":"Đề N2 7-2015.pdf","questions":[{"mondai":1,"q":1,"prompt":"ここは<u>省略</u>してもかまわない。","options":["しょうかく","しょうらく","しょうじゃく","しょうりゃく"],"answer":4,"word_explain":"省略 (しょうりゃく): sự tỉnh lược, lược bỏ","translation_vi":"Chỗ này có thể lược bỏ đi cũng không sao."},{"mondai":1,"q":2,"prompt":"研修内容は、日程も<u>含めて</u>、今日中にお知らせします。","options":["ふくめて","さだめて","かためて","まとめて"],"answer":1,"word_explain":"含める (ふくめる): bao gồm, tính cả","translation_vi":"Nội dung tập huấn, bao gồm cả lịch trình, sẽ được thông báo trong ngày hôm nay."},{"mondai":1,"q":3,"prompt":"慣れるとつい<u>油断</u>して失敗してしまう。","options":["よたん","ゆたん","よだん","ゆだん"],"answer":4,"word_explain":"油断 (ゆだん): sự lơ là, chủ quan, mất cảnh giác","translation_vi":"Khi đã quen rồi thì rất dễ lơ là chủ quan mà dẫn đến thất bại."},{"mondai":1,"q":4,"prompt":"明日は学校の<u>行事</u>に参加します。","options":["ぎょうごと","こうごと","ぎょうじ","こうじ"],"answer":3,"word_explain":"行事 (ぎょうじ): sự kiện, hoạt động thường niên","translation_vi":"Ngày mai tôi sẽ tham gia sự kiện của trường."},{"mondai":1,"q":5,"prompt":"この世代の人たちはコンピュータの知識が<u>乏しい</u>ように思います。","options":["くわしい","とぼしい","まずしい","あやしい"],"answer":2,"word_explain":"乏しい (とぼしい): thiếu thốn, nghèo nàn, ít ỏi","translation_vi":"Tôi thấy những người thuộc thế hệ này có vẻ thiếu kiến thức về máy tính."},{"mondai":2,"q":6,"prompt":"Ａ地点からＢ地点までの<u>きょり</u>を測った。","options":["距離","距理","拒離","拒理"],"answer":1,"word_explain":"距離 (きょり): khoảng cách, cự ly","translation_vi":"Tôi đã đo khoảng cách từ điểm A đến điểm B."},{"mondai":2,"q":7,"prompt":"<u>おどろかせて</u>しまって、すみません。","options":["怖かせて","焦かせて","驚かせて","騒かせて"],"answer":3,"word_explain":"驚かせる (おどろかせる): làm cho ngạc nhiên, làm giật mình","translation_vi":"Xin lỗi vì đã làm bạn giật mình."},{"mondai":2,"q":8,"prompt":"森さんは塾の<u>こうし</u>をしています。","options":["構師","構士","講師","講士"],"answer":3,"word_explain":"講師 (こうし): giảng viên, giáo viên (trung tâm học thêm/đại học)","translation_vi":"Anh Mori đang làm giảng viên ở trung tâm học thêm."},{"mondai":2,"q":9,"prompt":"今日もまだ<u>うで</u>に痛みがあります。","options":["腹","胸","腰","腕"],"answer":4,"word_explain":"腕 (うで): cánh tay","translation_vi":"Hôm nay cánh tay tôi vẫn còn bị đau."},{"mondai":2,"q":10,"prompt":"姉はたくさんの友達に<u>めぐまれている</u>。","options":["恵まれて","善まれて","幸まれて","喜まれて"],"answer":1,"word_explain":"恵まれる (めぐまれる): được ưu ái, may mắn có được, dồi dào","translation_vi":"Chị gái tôi may mắn có được rất nhiều bạn bè."},{"mondai":3,"q":11,"prompt":"社長の代わりに（　　）社長が会見を行った。","options":["従","準","補","副"],"answer":4,"word_explain":"副社長 (ふくしゃちょう): phó giám đốc, phó tổng giám đốc","translation_vi":"Phó giám đốc đã đứng ra tổ chức buổi họp báo thay cho giám đốc."},{"mondai":3,"q":12,"prompt":"彼の発言は（　　）責任だと批判された。","options":["不","無","放","否"],"answer":2,"word_explain":"無責任 (むせきにん): vô trách nhiệm","translation_vi":"Phát ngôn của anh ta bị chỉ trích là vô trách nhiệm."},{"mondai":3,"q":13,"prompt":"週末の遊園地は、子ども（　　）の客でいっぱいだった。","options":["連れ","込み","付き","加え"],"answer":1,"word_explain":"子ども連れ (こどもづれ): đi cùng trẻ em, dắt theo trẻ con","translation_vi":"Công viên giải trí vào cuối tuần đông nghịt khách đi cùng trẻ nhỏ."},{"mondai":3,"q":14,"prompt":"友達にパーティーの招待（　　）を送った。","options":["書","便","状","紙"],"answer":3,"word_explain":"招待状 (しょうたいじょう): thiệp mời, giấy mời","translation_vi":"Tôi đã gửi thiệp mời dự tiệc cho bạn bè."},{"mondai":3,"q":15,"prompt":"弟は、買ったばかりの（　　）新しい靴をはいて出かけていった。","options":["実","真","素","本"],"answer":2,"word_explain":"真新しい (まあたらしい): mới tinh, mới toanh","translation_vi":"Em trai tôi đã xỏ đôi giày mới tinh vừa mua rồi đi ra ngoài."},{"mondai":4,"q":16,"prompt":"この学校の（　　）は、国際交流が盛んなことだ。","options":["得点","性能","効用","特色"],"answer":4,"word_explain":"特色 (とくしょく): nét đặc sắc, đặc trưng","translation_vi":"Nét đặc sắc của ngôi trường này là hoạt động giao lưu quốc tế diễn ra sôi nổi."},{"mondai":4,"q":17,"prompt":"だんだん雨が激しくなって、傘を差していたのに服が（　　）ぬれてしまった。","options":["すっきり","ぎっしり","びっしょり","ぴったり"],"answer":3,"word_explain":"びっしょり: ướt sũng, ướt đẫm","translation_vi":"Mưa ngày càng nặng hạt, dù đã che ô nhưng quần áo tôi vẫn bị ướt sũng."},{"mondai":4,"q":18,"prompt":"このチームは何度も優勝し、（　　）成績を残している。","options":["力強い","輝かしい","分厚い","限りない"],"answer":2,"word_explain":"輝かしい (かがやかしい): rực rỡ, chói lọi, vẻ vang","translation_vi":"Đội bóng này đã nhiều lần giành chức vô địch và để lại những thành tích rực rỡ."},{"mondai":4,"q":19,"prompt":"Ａホテルは大通りに（　　）いて、分かりやすい場所にある。","options":["当たって","触れて","面して","合わせて"],"answer":3,"word_explain":"面する (めんする): giáp với, hướng mặt ra","translation_vi":"Khách sạn A nằm giáp mặt đường lớn nên ở vị trí rất dễ tìm."},{"mondai":4,"q":20,"prompt":"それは、問題点を的確にとらえた（　　）質問だった。","options":["するどい","にぶい","けわしい","ゆるい"],"answer":1,"word_explain":"するどい (鋭い): sắc bén, nhạy bén, sâu sắc","translation_vi":"Đó là một câu hỏi sắc bén, nắm bắt chính xác trọng tâm vấn đề."},{"mondai":4,"q":21,"prompt":"このいすは、大きさがちょうどいいし、色や（　　）も気に入っている。","options":["インテリア","スペース","リビング","デザイン"],"answer":4,"word_explain":"デザイン: thiết kế, kiểu dáng","translation_vi":"Chiếc ghế này có kích thước vừa vặn, mà màu sắc và thiết kế của nó tôi cũng rất thích."},{"mondai":4,"q":22,"prompt":"一つの考え方に縛られず、（　　）思考を持つことで、新しい発想が生まれるだろう。","options":["快適な","柔軟な","円満な","順調な"],"answer":2,"word_explain":"柔軟な (じゅうなんな): linh hoạt, mềm dẻo","translation_vi":"Bằng cách không bị gò bó vào một lối suy nghĩ duy nhất mà có tư duy linh hoạt, những ý tưởng mới sẽ nảy sinh."},{"mondai":5,"q":23,"prompt":"森さんはこの辺りに店を<u>所有して</u>いるらしい。","options":["探して","借りて","持って","建てて"],"answer":3,"word_explain":"所有する (しょゆうする) = 持つ: sở hữu, có","translation_vi":"Nghe nói anh Mori sở hữu một cửa hàng ở quanh khu vực này."},{"mondai":5,"q":24,"prompt":"佐藤さんは<u>おそらく</u>来ないと思う。","options":["たぶん","当然","やはり","絶対"],"answer":1,"word_explain":"おそらく = たぶん: có lẽ, e là","translation_vi":"Tôi nghĩ có lẽ anh Sato sẽ không đến đâu."},{"mondai":5,"q":25,"prompt":"まだ<u>収納して</u>いない物がたくさんある。","options":["集めて","預けて","返して","しまって"],"answer":4,"word_explain":"収納する (しゅうのうする) = しまう: cất giữ, thu dọn vào chỗ","translation_vi":"Vẫn còn rất nhiều đồ đạc chưa được cất gọn."},{"mondai":5,"q":26,"prompt":"妹は母に似て<u>小柄</u>だ。","options":["声が小さい","力が弱い","体が小さい","心が弱し"],"answer":3,"word_explain":"小柄 (こがら) = 体が小さい: vóc dáng nhỏ nhắn","translation_vi":"Em gái tôi giống mẹ, có vóc dáng nhỏ nhắn."},{"mondai":5,"q":27,"prompt":"鈴木さんは<u>無口</u>だ。","options":["あまり笑わない","あまり話さない","あまり怒らない","あまり食べない"],"answer":2,"word_explain":"無口 (むくち) = あまり話さない: ít nói, trầm tính","translation_vi":"Anh Suzuki là người ít nói."},{"mondai":6,"q":28,"prompt":"温暖","options":["佐藤さんはいつも厳しいが、本当はとても<u>温暖</u>な性格の人だ。","冷めるとおいしくないので、なるべく<u>温暖</u>なうちに召し上がってください。","この地方は<u>温暖</u>で暮らしやすく、野菜や果物などの農産物も豊富だ。","エアコンをつけたら、部屋の中が<u>温暖</u>になって眠くなってきた。"],"answer":3,"word_explain":"温暖 (おんだん): ấm áp, ôn hòa (chỉ khí hậu của một vùng/khu vực)","translation_vi":"Vùng này khí hậu ấm áp dễ sống, nông sản như rau củ và trái cây cũng rất phong phú."},{"mondai":6,"q":29,"prompt":"振り向く","options":["だれかに後ろから呼ばれたので<u>振り向い</u>たら、課長だった。","道を渡るときは、左右を<u>振り向いて</u>車が来ないことを確認しよう。","だれかが空を指さしたので、近くにいた人たちが一斉に上を<u>振り向いた</u>。","森さんは私を見ると、恥ずかしそうに下を<u>振り向いた</u>まま顔を上げなかった。"],"answer":1,"word_explain":"振り向く (ふりむく): quay đầu lại, ngoảnh lại nhìn phía sau","translation_vi":"Vì có ai đó gọi từ phía sau nên khi tôi quay đầu lại thì hóa ra là trưởng phòng."},{"mondai":6,"q":30,"prompt":"用途","options":["新しい趣味を始めるため、時間の<u>用途</u>を工夫することにした。","会社での私の<u>用途</u>は、新入社員の指導をすることだ。","鈴木さんの才能は、多くの<u>用途</u>に生かされるだろう。","本来の<u>用途</u>ではないが、この容器は花瓶にしてもいいと思う。"],"answer":4,"word_explain":"用途 (ようと): công dụng, mục đích sử dụng (của đồ vật, thiết bị, v.v.)","translation_vi":"Tuy không phải công dụng vốn có, nhưng tôi nghĩ chiếc bình này có thể dùng làm lọ hoa cũng được."},{"mondai":6,"q":31,"prompt":"甘やかす","options":["今年のＡ社の就職試験は、昨年より内容が<u>甘やかされて</u>いる。","林さんは、ずっと親に<u>甘やかされて</u>育ったせいか、わがままで困る。","ひどくなったら大変だから、風邪を<u>甘やかされない</u>ほうがいいですよ。","今日は、いつもより多めに砂糖を入れて、コーヒーを<u>甘やかした</u>。"],"answer":2,"word_explain":"甘やかす (あまやかす): nuông chiều, chiều hư (trẻ con, người khác)","translation_vi":"Anh Hayashi có lẽ vì được bố mẹ nuông chiều từ nhỏ nên rất ích kỷ, thật khó xử."},{"mondai":6,"q":32,"prompt":"行方","options":["この写真の二人は事件に関係があるらしいが、まだ<u>行方</u>が分からない。","慌てていたので、<u>行方</u>を確かめずにバスに乗ってしまった。","交差点を右に曲がると、<u>行方</u>に黒い高層ビルが見えた。","日曜日の私の<u>行方</u>はいつも決まっていて、近くの喫茶店か図書館だ。"],"answer":1,"word_explain":"行方 (ゆくえ): tung tích, nơi chốn (thường dùng trong 「行方が分からない」: mất tích, không rõ tung tích)","translation_vi":"Hai người trong bức ảnh này có vẻ có liên quan đến vụ án, nhưng hiện vẫn chưa rõ tung tích."}]},{"id":"2014_12","displayName":"12/2014","sourceFile":"Đề N2 12-2014.pdf","questions":[{"mondai":1,"q":1,"prompt":"この店は、今月に入って、客数が<u>極端</u>に減ったらしい。","options":["きょたん","きょてん","きょくたん","きょくてん"],"answer":3,"word_explain":"極端 (きょくたん): cực đoan, quá mức, đột ngột","translation_vi":"Nghe nói cửa hàng này từ đầu tháng đến nay lượng khách đã giảm một cách đột ngột."},{"mondai":1,"q":2,"prompt":"食事が済んだら、食器はここに<u>戻して</u>ください。","options":["かえして","のこして","わたして","もどして"],"answer":4,"word_explain":"戻す (もどす): trả lại, đặt lại chỗ cũ","translation_vi":"Sau khi ăn xong, hãy đặt bát đĩa lại chỗ này."},{"mondai":1,"q":3,"prompt":"この効果はどのくらい<u>継続</u>するのだろう。","options":["じぞく","けいぞく","じそく","けいそく"],"answer":2,"word_explain":"継続 (けいぞく): tiếp tục, duy trì","translation_vi":"Không biết hiệu quả này sẽ kéo dài được bao lâu nhỉ."},{"mondai":1,"q":4,"prompt":"これらの経費は<u>除いて</u>計算してください。","options":["のぞいて","はぶいて","ぬいて","ひいて"],"answer":1,"word_explain":"除く (のぞく): loại trừ, bỏ ra","translation_vi":"Hãy tính toán sau khi loại trừ những khoản chi phí này."},{"mondai":1,"q":5,"prompt":"A国とB国の間で盛んに<u>貿易</u>が行われている。","options":["もうえき","ぼうえき","もうい","ぼうい"],"answer":2,"word_explain":"貿易 (ぼうえき): thương mại, mậu dịch","translation_vi":"Hoạt động thương mại giữa nước A và nước B đang diễn ra sôi nổi."},{"mondai":2,"q":6,"prompt":"<u>くわしい</u>ことは、あとで担当の先生に聞いてください。","options":["許しい","詳しい","討しい","評しい"],"answer":2,"word_explain":"詳しい (くわしい): chi tiết, tường tận","translation_vi":"Về thông tin chi tiết, lát nữa hãy hỏi thầy/cô phụ trách."},{"mondai":2,"q":7,"prompt":"兄は学費の<u>えんじょ</u>を受けて大学に通いました。","options":["補助","援財","補財","援助"],"answer":4,"word_explain":"援助 (えんじょ): sự viện trợ, hỗ trợ, giúp đỡ","translation_vi":"Anh trai tôi đã nhận hỗ trợ học phí để theo học đại học."},{"mondai":2,"q":8,"prompt":"物を入れすぎて袋が<u>やぶれて</u>しまった。","options":["被れて","割れて","破れて","削れて"],"answer":3,"word_explain":"破れる (やぶれる): bị rách, vỡ","translation_vi":"Vì nhét quá nhiều đồ nên cái túi đã bị rách mất rồi."},{"mondai":2,"q":9,"prompt":"これは少し<u>めんどう</u>な仕事ですね。","options":["面到","免倒","面倒","免到"],"answer":3,"word_explain":"面倒 (めんどう): phiền phức, rắc rối","translation_vi":"Đây là một công việc hơi phiền phức nhỉ."},{"mondai":2,"q":10,"prompt":"家に帰る途中、手帳を<u>ひろった</u>。","options":["拾った","採った","捨った","授った"],"answer":1,"word_explain":"拾う (ひろう): nhặt được","translation_vi":"Trên đường về nhà, tôi đã nhặt được một cuốn sổ tay."},{"mondai":3,"q":11,"prompt":"この器具は使い方を間違えると、けがをする危険(　　)がある。","options":["素","態","状","性"],"answer":4,"word_explain":"危険性 (きけんせい): tính nguy hiểm, nguy cơ","translation_vi":"Dụng cụ này nếu sử dụng sai cách thì có nguy cơ gây chấn thương."},{"mondai":3,"q":12,"prompt":"この作業は(　　)経験の人でも簡単にできます。","options":["未","不","少","低"],"answer":1,"word_explain":"未経験 (みけいけん): chưa có kinh nghiệm","translation_vi":"Công việc này ngay cả người chưa có kinh nghiệm cũng có thể làm một cách dễ dàng."},{"mondai":3,"q":13,"prompt":"このカードは期限(　　)なので、使うことができません。","options":["越え","折れ","切れ","終え"],"answer":3,"word_explain":"期限切れ (きげんぎれ): hết hạn","translation_vi":"Thẻ này đã hết hạn nên không thể sử dụng được."},{"mondai":3,"q":14,"prompt":"これは(　　)性能のカメラで撮られた映像です。","options":["優","高","良","上"],"answer":2,"word_explain":"高性能 (こうせいのう): tính năng cao, hiệu suất cao","translation_vi":"Đây là đoạn phim được quay bằng máy ảnh có tính năng cao."},{"mondai":3,"q":15,"prompt":"森さんは毎日掃除をするらしいが、私は忙しいので一日(　　)にしている。","options":["あき","とり","おき","とび"],"answer":3,"word_explain":"一日おき (いちにちおき): cách một ngày (làm một lần)","translation_vi":"Nghe nói anh Mori dọn dẹp mỗi ngày, nhưng tôi bận nên cứ cách một ngày mới dọn một lần."},{"mondai":4,"q":16,"prompt":"誰にも言えずにずっと悩んでいたが、昨日親友に(　　)相談してみた。","options":["思いきって","うっかり","せっかく","知らず知らず"],"answer":1,"word_explain":"思いきって (おもいきって): lấy hết can đảm, mạnh dạn, dứt khoát","translation_vi":"Tôi đã trăn trở mãi mà không nói được với ai, nhưng hôm qua tôi đã mạnh dạn tâm sự thử với bạn thân."},{"mondai":4,"q":17,"prompt":"原稿に漢字の誤りがあったので、赤のペンで(　　)した。","options":["交換","改訂","変換","訂正"],"answer":4,"word_explain":"訂正 (ていせい): đính chính, sửa chữa (lỗi sai)","translation_vi":"Vì trong bản thảo có lỗi chữ Hán nên tôi đã sửa lại bằng bút đỏ."},{"mondai":4,"q":18,"prompt":"選手たちは、次の大会での優勝を(　　)、毎日遅くまで練習している。","options":["とらえて","めざして","みはって","にぎって"],"answer":2,"word_explain":"目指す (めざす): nhắm tới, hướng tới (mục tiêu)","translation_vi":"Các vận động viên đang luyện tập đến tận khuya mỗi ngày, hướng tới chức vô địch ở giải đấu tiếp theo."},{"mondai":4,"q":19,"prompt":"この小説はとてもおもしろかったので、最後まで(　　)読んでしまった。","options":["一気に","一時的に","一斉に","一方的に"],"answer":1,"word_explain":"一気に (いっきに): một mạch, liền một hơi","translation_vi":"Cuốn tiểu thuyết này rất hay nên tôi đã đọc một mạch đến hết."},{"mondai":4,"q":20,"prompt":"希望の職に就きたいのなら、情報を集めて、必要な知識を(　　)おくことが大切だ。","options":["蓄えて","招いて","抱えて","結んで"],"answer":1,"word_explain":"蓄える (たくわえる): tích lũy, tích trữ (kiến thức, tiền bạc...)","translation_vi":"Nếu muốn làm được công việc mình mong muốn, điều quan trọng là thu thập thông tin và tích lũy sẵn những kiến thức cần thiết."},{"mondai":4,"q":21,"prompt":"今週は仕事が忙しかったので、週末は家で好きな音楽でも聞いて(　　)したい。","options":["ダウン","キャンセル","クリア","リラックス"],"answer":4,"word_explain":"リラックス: thư giãn, thả lỏng","translation_vi":"Tuần này công việc bận rộn nên cuối tuần tôi muốn ở nhà nghe bản nhạc mình thích để thư giãn."},{"mondai":4,"q":22,"prompt":"昨日徹夜したせいで、今日は眠くて、本を読みながらつい(　　)してしまった。","options":["ぎっしり","いきいき","うとうと","さっぱり"],"answer":3,"word_explain":"うとうと: ngủ gật, lơ mơ buồn ngủ","translation_vi":"Tại hôm qua thức trắng đêm nên hôm nay buồn ngủ, vừa đọc sách tôi vừa lỡ ngủ gật mất."},{"mondai":5,"q":23,"prompt":"この二つのレポートはテーマが<u>ことなります</u>。","options":["単純です","似ています","複雑です","違います"],"answer":4,"word_explain":"異なる (ことなる) = 違う: khác nhau","translation_vi":"Hai bản báo cáo này có chủ đề khác nhau."},{"mondai":5,"q":24,"prompt":"二人は<u>たまたま</u>会ったらしい。","options":["すぐに","偶然","何度も","さっき"],"answer":2,"word_explain":"たまたま = 偶然 (ぐうぜん): tình cờ, ngẫu nhiên","translation_vi":"Nghe nói hai người đó đã tình cờ gặp nhau."},{"mondai":5,"q":25,"prompt":"その発言がうそだという<u>あきらかな</u>証拠があります。","options":["さまざまな","別の","新しい","はっきりした"],"answer":4,"word_explain":"明らか (あきらか) = はっきりした: rõ ràng","translation_vi":"Có bằng chứng rõ ràng cho thấy phát ngôn đó là nói dối."},{"mondai":5,"q":26,"prompt":"できるだけ<u>用心</u>したほうがいいですよ。","options":["注意","努力","我慢","遠慮"],"answer":1,"word_explain":"用心 (ようじん) = 注意 (ちゅうい): cẩn thận, đề phòng","translation_vi":"Bạn nên cẩn thận hết sức có thể nhé."},{"mondai":5,"q":27,"prompt":"会場が急に<u>そうぞうしく</u>なった。","options":["暗く","静かに","うるさく","寒く"],"answer":3,"word_explain":"騒々しい (そうぞうしい) = うるさい: ồn ào, huyên náo","translation_vi":"Hội trường bỗng nhiên trở nên ồn ào."},{"mondai":6,"q":28,"prompt":"会見","options":["来週、アルバイトの<u>会見</u>があるので、持っていく履歴書を用意した。","社長は<u>会見</u>を開き、記者からの質問に一つ一つ丁寧に答えた。","昨夜、高校の同級生の集まりがあり、１０年振りに<u>会見</u>を楽しんだ。","駅の近くを歩いていたら声をかけられて、テレビ番組の<u>会見</u>を受けた。"],"answer":2,"word_explain":"会見 (かいけん): cuộc họp báo, cuộc gặp gỡ chính thức (thường dùng với báo chí, nhân vật quan trọng: 会見を開く)","translation_vi":"Giám đốc đã mở cuộc họp báo và trả lời cẩn thận từng câu hỏi một từ các phóng viên."},{"mondai":6,"q":29,"prompt":"支持","options":["私は、息子がサッカーの試合に出るときは必ず会場へ<u>支持</u>しに行く。","建物内部の撮影は禁止されているが、今回は特別に<u>支持</u>を得ることができた。","田中市長は市民の安全を一番に考えるので、多くの<u>支持</u>を集めている。","久しぶりに中学校を訪ねたら、先生方から温かく<u>支持</u>されてうれしかった。"],"answer":3,"word_explain":"支持 (しじ): sự ủng hộ, tán thành (ý kiến, chính sách, ứng cử viên...: 支持を集める/得る)","translation_vi":"Thị trưởng Tanaka luôn đặt sự an toàn của người dân lên hàng đầu nên nhận được rất nhiều sự ủng hộ."},{"mondai":6,"q":30,"prompt":"妥当","options":["品質に比べて値段が高いと言う人もいるが、私は<u>妥当</u>な金額だと思う。","風邪気味だったので、今日の会議が中止になったのは、私には<u>妥当</u>だった。","旅行の日は雨の予報だったが、きれいに晴れて、<u>妥当</u>な天気になった。","この曲は、歌詞が今の私の気持ちに<u>妥当</u>なので、最近よく聞いている。"],"answer":1,"word_explain":"妥当 (だとう): thỏa đáng, hợp lý, phù hợp (về mức giá, đánh giá, phán đoán...)","translation_vi":"Cũng có người nói giá đắt so với chất lượng, nhưng tôi thấy đó là một mức giá hợp lý."},{"mondai":6,"q":31,"prompt":"言い訳","options":["重要な提案なので会議できちんと<u>言い訳</u>をしたが、結局、賛成を得られなかった。","学生が質問すると、中村先生はいつも熱心に<u>言い訳</u>をしてくれる。","西さんは仕事で失敗すると必ず<u>言い訳</u>をするので、上司からよく思われていない。","診察室で医者からあしたの検査内容について<u>言い訳</u>をしてもらった。"],"answer":3,"word_explain":"言い訳 (いいわけ): lời bào chữa, viện cớ (khi mắc lỗi hay thất bại)","translation_vi":"Anh Nishi hễ thất bại trong công việc là chắc chắn viện cớ, nên không được cấp trên đánh giá tốt."},{"mondai":6,"q":32,"prompt":"手軽","options":["この運動は、道具もいらず自宅で<u>手軽</u>にできるので、人気がある。","参加者全員がお互いを知るために、一分ずつ<u>手軽</u>な自己紹介を行った。","結婚式の後のパーティーには<u>手軽</u>な服装で来てください。","昨日の試合は、<u>手軽</u>に勝てると思ったのに、意外に苦戦した。"],"answer":1,"word_explain":"手軽 (てがる): đơn giản, gọn nhẹ, dễ dàng thực hiện (không tốn công sức hay chuẩn bị cầu kỳ)","translation_vi":"Bài tập vận động này không cần dụng cụ và có thể thực hiện một cách đơn giản tại nhà nên rất được ưa chuộng."}]},{"id":"2014_07","displayName":"07/2014","sourceFile":"Đề N2 7-2014.pdf","questions":[{"mondai":1,"q":1,"prompt":"ガソリンの値段が<u>大幅</u>に上がった。","options":["おおはば","おおふく","だいはば","だいふく"],"answer":1,"word_explain":"大幅 (おおはば): đáng kể, mức độ lớn, mạnh mẽ","translation_vi":"Giá xăng đã tăng lên đáng kể."},{"mondai":1,"q":2,"prompt":"昨日、とても<u>悔しい</u>出来事があった。","options":["かなしい","くやしい","はずかしい","おそろしい"],"answer":2,"word_explain":"悔しい (くやしい): cay cú, ấm ức, hối tiếc","translation_vi":"Hôm qua đã có một chuyện rất ấm ức (đáng tiếc)."},{"mondai":1,"q":3,"prompt":"わかりやすく書いたつもりだったが、<u>幼稚</u>な文章になってしまった。","options":["ゆうち","ようし","ようち","ゆうし"],"answer":3,"word_explain":"幼稚 (ようち): ấu trĩ, non nớt, trẻ con","translation_vi":"Tôi định viết cho dễ hiểu, nhưng câu văn lại trở nên non nớt mất rồi."},{"mondai":1,"q":4,"prompt":"今回は田中選手の<u>圧勝</u>だった。","options":["あっしょう","ゆうしょう","あっしゅう","ゆうしゅう"],"answer":1,"word_explain":"圧勝 (あっしょう): thắng áp đảo","translation_vi":"Lần này là chiến thắng áp đảo của tuyển thủ Tanaka."},{"mondai":1,"q":5,"prompt":"暑い季節は食べ物が<u>傷みやすい</u>。","options":["きずみやすい","きすみやすい","いだみやすい","いたみやすい"],"answer":4,"word_explain":"傷みやすい (いたみやすい): dễ bị hỏng, ôi thiu","translation_vi":"Mùa nóng thì đồ ăn rất dễ bị hỏng (ôi thiu)."},{"mondai":2,"q":6,"prompt":"洗濯物がまだ<u>しめっぽい</u>。","options":["汚っぽい","泡っぽい","汗っぽい","湿っぽい"],"answer":4,"word_explain":"湿っぽい (しめっぽい): ẩm ướt, ẩm thấp","translation_vi":"Đồ giặt vẫn còn hơi ẩm."},{"mondai":2,"q":7,"prompt":"このパソコンにはプリンターが<u>せつぞく</u>されています。","options":["設属","接属","設族","接続"],"answer":4,"word_explain":"接続 (せつぞく): kết nối","translation_vi":"Máy tính này được kết nối với máy in."},{"mondai":2,"q":8,"prompt":"私は親に<u>さからって</u>大学に進学した。","options":["逆らって","敵らって","拒って","争って"],"answer":1,"word_explain":"逆らう (さからう): làm trái, chống đối","translation_vi":"Tôi đã làm trái ý bố mẹ để học lên đại học."},{"mondai":2,"q":9,"prompt":"田中社長の強引なやり方を<u>ひはん</u>する人もいる。","options":["非判","批判","批反","非反"],"answer":2,"word_explain":"批判 (ひはん): phê phán, chỉ trích","translation_vi":"Cũng có người phê phán cách làm độc đoán của giám đốc Tanaka."},{"mondai":2,"q":10,"prompt":"A社の製品のほうが機能の面では<u>おとっている</u>と思う。","options":["悪って","負って","劣って","乏って"],"answer":3,"word_explain":"劣る (おとる): kém hơn, thua kém","translation_vi":"Tôi nghĩ sản phẩm của công ty A xét về mặt tính năng thì kém hơn."},{"mondai":3,"q":11,"prompt":"歴史小説家西村氏の代表的な作品を収めた作品(　　)が発行された。","options":["集","族","部","団"],"answer":1,"word_explain":"作品集 (さくひんしゅう): tuyển tập tác phẩm","translation_vi":"Tuyển tập các tác phẩm tiêu biểu của tiểu thuyết gia lịch sử Nishimura đã được phát hành."},{"mondai":3,"q":12,"prompt":"ここから駅まで行くなら、線路(　　)の道を行くのが一番早いですよ。","options":["付き","並び","沿い","従い"],"answer":3,"word_explain":"線路沿い (せんろぞい): dọc theo đường ray","translation_vi":"Nếu đi từ đây đến nhà ga thì đi con đường dọc theo đường ray là nhanh nhất đấy."},{"mondai":3,"q":13,"prompt":"田中先生は、子どもの英語教育に関する(　　)問題について研究している。","options":["総","複","数","諸"],"answer":4,"word_explain":"諸問題 (しょもんだい): nhiều vấn đề, các vấn đề khác nhau","translation_vi":"Thầy Tanaka đang nghiên cứu về các vấn đề liên quan đến giáo dục tiếng Anh cho trẻ em."},{"mondai":3,"q":14,"prompt":"大きな図書館に行きたいが、遠いのでけっこう電車(　　)がかかる。","options":["金","賃","料","財"],"answer":2,"word_explain":"電車賃 (でんしゃちん): tiền tàu điện","translation_vi":"Tôi muốn đi đến thư viện lớn, nhưng vì xa nên tốn khá nhiều tiền tàu điện."},{"mondai":3,"q":15,"prompt":"町は朝からお祭りムード(　　)だった。","options":["一例","一面","一種","一色"],"answer":4,"word_explain":"一色 (いっしょく): tràn ngập một sắc thái/bầu không khí (〜一色)","translation_vi":"Từ sáng cả khu phố đã tràn ngập bầu không khí lễ hội."},{"mondai":4,"q":16,"prompt":"子どものいたずらにいちいち(　　)を立てても仕方がない。","options":["気","頭","腹","心"],"answer":3,"word_explain":"腹 (はら) [腹を立てる]: nổi giận, tức giận","translation_vi":"Cứ hơi tí lại nổi giận với trò nghịch ngợm của trẻ con thì cũng chẳng giải quyết được gì."},{"mondai":4,"q":17,"prompt":"A社が開発した商品管理システムは評価が高く、多くの会社に(　　)されている。","options":["導入","引用","吸収","移行"],"answer":1,"word_explain":"導入 (どうにゅう): đưa vào áp dụng, triển khai","translation_vi":"Hệ thống quản lý hàng hóa do công ty A phát triển được đánh giá cao và đang được nhiều công ty đưa vào áp dụng."},{"mondai":4,"q":18,"prompt":"工事の音が(　　)、全然眠れない。","options":["しつこくて","ずうずうしくて","やかましくて","けわしくて"],"answer":3,"word_explain":"やかましい: ồn ào, inh ỏi","translation_vi":"Tiếng công trình ồn ào quá, tôi hoàn toàn không ngủ được."},{"mondai":4,"q":19,"prompt":"自転車のタイヤが(　　)して、空気が抜けていた。","options":["ストライキ","パンク","ダウン","ミス"],"answer":2,"word_explain":"パンク (する): thủng lốp, xì lốp","translation_vi":"Lốp xe đạp bị thủng nên bị xì hết hơi."},{"mondai":4,"q":20,"prompt":"セミナーの日の朝は準備の時間がないので、資料は(　　)コピーしておいてください。","options":["遅くとも","あらかじめ","とっくに","先々"],"answer":2,"word_explain":"あらかじめ: trước, sẵn trước","translation_vi":"Sáng ngày diễn ra hội thảo không có thời gian chuẩn bị nên hãy photo sẵn tài liệu trước đi."},{"mondai":4,"q":21,"prompt":"山口さんは柔道をしているので、がっしりした(　　)をしている。","options":["体格","姿勢","格好","容姿"],"answer":1,"word_explain":"体格 (たいかく): thể hình, vóc dáng","translation_vi":"Anh Yamaguchi tập Judo nên có vóc dáng rất vạm vỡ."},{"mondai":4,"q":22,"prompt":"こんなに夜遅くまでおきていると、明日の仕事に(　　)よ。","options":["かかわり合う","割り込む","引っかかる","差し支える"],"answer":4,"word_explain":"差し支える (さしつかえる): gây trở ngại, ảnh hưởng đến","translation_vi":"Nếu thức khuya thế này thì sẽ ảnh hưởng đến công việc ngày mai đấy."},{"mondai":5,"q":23,"prompt":"文字のサイズを<u>そろえて</u>ください。","options":["大きくして","同じにして","調べて","教えて"],"answer":2,"word_explain":"そろえる = 同じにする: làm cho đồng đều, giống nhau","translation_vi":"Xin hãy chỉnh kích cỡ chữ cho đồng đều nhau."},{"mondai":5,"q":24,"prompt":"中野氏は、古い工場が取り壊されて空いた土地を<u>買いしめた</u>そうだ。","options":["無理に買った","全部買った","安く買った","さっそく買った"],"answer":2,"word_explain":"買いしめる (かいしめる) = 全部買う: mua gom toàn bộ, thâu tóm hết","translation_vi":"Nghe nói ông Nakano đã mua gom hết mảnh đất trống sau khi nhà máy cũ bị phá dỡ."},{"mondai":5,"q":25,"prompt":"出発<u>間際</u>に、妹から電話がかかってきた。","options":["直前","直後","当日","前日"],"answer":1,"word_explain":"間際 (まぎわ) = 直前 (ちょくぜん): ngay trước khi, sát lúc","translation_vi":"Ngay sát lúc khởi hành thì em gái gọi điện đến."},{"mondai":5,"q":26,"prompt":"薬を飲んだら<u>たちまち</u>痛みが治まった。","options":["すっかり","やっと","すぐに","たしかに"],"answer":3,"word_explain":"たちまち = すぐに: ngay lập tức, tức thì","translation_vi":"Uống thuốc xong thì cơn đau lập tức dịu đi."},{"mondai":5,"q":27,"prompt":"もう<u>お勘定は済ましました</u>。","options":["料理は注文しました","店は予約しました","店員は呼びました","お金は払いました"],"answer":4,"word_explain":"お勘定は済ましました = お金は払いました: đã thanh toán tiền","translation_vi":"Tôi đã thanh toán tiền rồi."},{"mondai":6,"q":28,"prompt":"頑丈","options":["石川さんは<u>頑丈</u>で、なかなか意見を変えない。","重要な書類は必ず金庫に入れて、<u>頑丈</u>に管理してください。","このいすはとても<u>頑丈</u>で、少しくらい乱暴に扱っても壊れません。","A社との間には<u>頑丈</u>な信頼関係があるので安心です。"],"answer":3,"word_explain":"頑丈 (がんじょう): chắc chắn, bền bỉ, khỏe khoắn (dùng cho đồ vật cứng cáp hoặc cơ thể khỏe mạnh)","translation_vi":"Chiếc ghế này rất chắc chắn, dù có sử dụng hơi thô bạo một chút cũng không hỏng."},{"mondai":6,"q":29,"prompt":"畳む","options":["青木さんは、小さな紙を器用に<u>畳んで</u>鶴を作った。","この上着は小さく<u>畳む</u>ことができるので、旅行に持っていくのに便利だ。","髪が長いと首の周りが暑いので、夏はいつも髪を<u>畳んで</u>います。","中川さんは腕を<u>畳んで</u>、何か考えているようだった。"],"answer":2,"word_explain":"畳む (たたむ): gấp, xếp (quần áo, chăn màn, ô dù, hoặc đóng cửa hàng)","translation_vi":"Chiếc áo khoác này có thể gấp nhỏ lại được nên rất tiện mang theo khi đi du lịch."},{"mondai":6,"q":30,"prompt":"合図","options":["スタートの<u>合図</u>で、選手たちは一斉に走り出した。","ガス会社から、器具の点検を来月行うという<u>合図</u>があった。","山道に何か小さい動物が歩いたような<u>合図</u>があった。","種をまいたところを忘れないように、<u>合図</u>をつけておいた。"],"answer":1,"word_explain":"合図 (あいず): tín hiệu, ám hiệu, hiệu lệnh (báo hiệu bắt đầu hay hành động gì đó)","translation_vi":"Theo hiệu lệnh xuất phát, các vận động viên đồng loạt chạy ra."},{"mondai":6,"q":31,"prompt":"こつこつ","options":["何度も説明を聞いていたら、<u>こつこつ</u>とわかってきた。","料理が熱くて、舌をやけどしそうなので、<u>こつこつ</u>と食べた。","朝は涼しかったが、昼になって<u>こつこつ</u>と気温が上がり始めた。","資格をとるために、この一年間、毎日<u>こつこつ</u>と勉強をしてきた。"],"answer":4,"word_explain":"こつこつ: chăm chỉ, cần cù, từng chút một một cách bền bỉ","translation_vi":"Để lấy được chứng chỉ, suốt một năm qua tôi đã chăm chỉ học hành từng ngày."},{"mondai":6,"q":32,"prompt":"縮む","options":["箱を積み重ねておいたら、重さで一番下の箱が<u>縮んで</u>いた。","この鉛筆はもう<u>縮んで</u>いて、ちょっと書きづらい。","洗濯物でセーターを洗ったら、<u>縮んで</u>着られなくなった。","建て替えて、家は広くなったが、庭が<u>縮んで</u>しまった。"],"answer":3,"word_explain":"縮む (ちぢむ): co lại, rút lại (vải vóc, quần áo, chiều dài, khoảng cách)","translation_vi":"Khi giặt áo len cùng đồ giặt, áo bị co lại nên không mặc vừa nữa."}]},{"id":"2013_12","displayName":"12/2013","sourceFile":"Đề N2 12-2013.pdf","questions":[{"mondai":1,"q":1,"prompt":"そのホテルは古いですが、部屋はとても<u>清潔</u>でしたよ。","options":["せっきつ","せいきつ","せっけつ","せいけつ"],"answer":4,"word_explain":"清潔 (せいけつ): sạch sẽ","translation_vi":"Khách sạn đó tuy cũ nhưng phòng rất sạch sẽ."},{"mondai":1,"q":2,"prompt":"それは<u>隠す</u>必要がないですよ。","options":["かくす","もどす","わたす","さがす"],"answer":1,"word_explain":"隠す (かくす): giấu giếm","translation_vi":"Việc đó không cần phải giấu giếm đâu."},{"mondai":1,"q":3,"prompt":"山田さんはいつも<u>姿勢</u>がいいですね。","options":["しぜい","しっぜい","しせい","しっせい"],"answer":3,"word_explain":"姿勢 (しせい): tư thế, dáng vẻ","translation_vi":"Anh/chị Yamada lúc nào cũng có tư thế đẹp nhỉ."},{"mondai":1,"q":4,"prompt":"もっと丁寧に<u>積んで</u>ください。","options":["たたんで","あんで","むすんで","つんで"],"answer":4,"word_explain":"積む (つむ): chất, xếp (chồng lên)","translation_vi":"Xin hãy xếp cẩn thận hơn nữa."},{"mondai":1,"q":5,"prompt":"犯人は10年以上も<u>逃亡</u>生活を送っていた。","options":["とうぼう","とぼう","とうそう","とそう"],"answer":1,"word_explain":"逃亡 (とうぼう): chạy trốn, đào tẩu","translation_vi":"Hung thủ đã sống cuộc sống trốn chạy suốt hơn 10 năm."},{"mondai":2,"q":6,"prompt":"あのころはまだ、将来のことを<u>しんけん</u>に考えていなかった。","options":["真険","真剣","信険","信剣"],"answer":2,"word_explain":"真剣 (しんけん): nghiêm túc","translation_vi":"Hồi đó tôi vẫn chưa suy nghĩ một cách nghiêm túc về tương lai."},{"mondai":2,"q":7,"prompt":"今後もサービス向上に<u>つとめて</u>いきたいと思っています。","options":["志めて","勧めて","勤めて","努めて"],"answer":4,"word_explain":"努める (つとめる): nỗ lực, cố gắng","translation_vi":"Trong thời gian tới, tôi cũng muốn tiếp tục nỗ lực nâng cao chất lượng dịch vụ."},{"mondai":2,"q":8,"prompt":"バザーの売り上げは全額<u>きふ</u>しました。","options":["寄符","貴付","寄付","貴符"],"answer":3,"word_explain":"寄付 (きふ): quyên góp, đóng góp","translation_vi":"Toàn bộ doanh thu từ hội chợ từ thiện đã được quyên góp hết."},{"mondai":2,"q":9,"prompt":"そのうわさについて本人に尋ねたら、<u>そくざ</u>に否定された。","options":["即座に","速座に","即差に","速差に"],"answer":1,"word_explain":"即座に (そくざに): ngay lập tức","translation_vi":"Khi hỏi chính người đó về tin đồn ấy, họ đã phủ nhận ngay lập tức."},{"mondai":2,"q":10,"prompt":"そんなに<u>せめたら</u>かわいそうだよ。","options":["疑めたら","怒めたら","憎めたら","責めたら"],"answer":4,"word_explain":"責める (せめる): trách móc, khiển trách","translation_vi":"Nếu trách mắng như thế thì tội nghiệp quá."},{"mondai":3,"q":11,"prompt":"書類に記入ミスがあったので、直してから(　　)提出するように言われた。","options":["改","次","再","復"],"answer":3,"word_explain":"再提出 (さいていしゅつ): nộp lại","translation_vi":"Vì có lỗi điền thông tin trong hồ sơ nên tôi được bảo sửa lại rồi nộp lại."},{"mondai":3,"q":12,"prompt":"3時10分東京駅(　　)の新幹線に乗る予定です。","options":["始","発","出","離"],"answer":2,"word_explain":"東京駅発 (とうきょうえきはつ): xuất phát từ ga Tokyo","translation_vi":"Tôi dự định đi chuyến tàu Shinkansen khởi hành từ ga Tokyo lúc 3 giờ 10 phút."},{"mondai":3,"q":13,"prompt":"歌謡曲からクラシックまで、音楽(　　)に興味があります。","options":["共同","全面","共通","全般"],"answer":4,"word_explain":"音楽全般 (おんがくぜんぱん): âm nhạc nói chung","translation_vi":"Từ nhạc đại chúng đến nhạc cổ điển, tôi quan tâm đến âm nhạc nói chung."},{"mondai":3,"q":14,"prompt":"会長候補の中では北川氏が(　　)有力だと言われている。","options":["特","最","頂","極"],"answer":2,"word_explain":"最有力 (さいゆうりょく): có triển vọng nhất, sáng giá nhất","translation_vi":"Trong số các ứng cử viên chủ tịch, ông Kitagawa được cho là người sáng giá nhất."},{"mondai":3,"q":15,"prompt":"宿題を夏休み(　　)に出さなければならない。","options":["明け","閉め","分け","止め"],"answer":1,"word_explain":"夏休み明け (なつやすみあけ): ngay sau kỳ nghỉ hè","translation_vi":"Phải nộp bài tập ngay sau khi kết thúc kỳ nghỉ hè."},{"mondai":4,"q":16,"prompt":"オリンピックの開会式の様子が、会場から世界中に(　　)された。","options":["普及","接続","分配","中継"],"answer":4,"word_explain":"中継 (ちゅうけい): truyền hình trực tiếp, tiếp sóng","translation_vi":"Hình ảnh lễ khai mạc Olympic đã được truyền hình trực tiếp từ địa điểm tổ chức ra khắp thế giới."},{"mondai":4,"q":17,"prompt":"彼は最近かなりの収入があったらしく、(　　)生活をするようになった。","options":["ぜいたくな","豊富な","わずかな","質素な"],"answer":1,"word_explain":"ぜいたくな (贅沢な): xa xỉ, sang trọng","translation_vi":"Hình như gần đây anh ấy có thu nhập khá cao nên bắt đầu sống xa hoa."},{"mondai":4,"q":18,"prompt":"絵のことはよく知らないので、この作品にどのくらいの価値があるのか(　　)がつかない。","options":["発想","仮定","見当","目印"],"answer":3,"word_explain":"見当 (けんとう): sự ước lượng, phán đoán (見当がつかない: không thể đoán chừng được)","translation_vi":"Vì không rành về hội họa nên tôi không thể ước lượng được tác phẩm này có giá trị khoảng bao nhiêu."},{"mondai":4,"q":19,"prompt":"不要な物を捨てて、散らかった部屋を整理したら、気分が(　　)した。","options":["ぎっしり","すっきり","ぶらぶら","きらきら"],"answer":2,"word_explain":"すっきり: sảng khoái, nhẹ nhõm, gọn gàng","translation_vi":"Sau khi vứt bỏ những đồ không cần thiết và dọn dẹp căn phòng bừa bộn, tâm trạng tôi thấy sảng khoái hẳn."},{"mondai":4,"q":20,"prompt":"気温の上昇に(　　)して、エアコンの売上も伸びているらしい。","options":["比例","対応","比較","応答"],"answer":1,"word_explain":"比例 (ひれい): tỷ lệ thuận","translation_vi":"Nghe nói doanh số máy điều hòa cũng đang tăng tỷ lệ thuận theo sự gia tăng của nhiệt độ."},{"mondai":4,"q":21,"prompt":"地図を見ながら歩いていたら、小さな石に(　　)、転んでしまった。","options":["つっこんで","つまずいて","くっついて","かたむいて"],"answer":2,"word_explain":"つまずく (躓く): vấp phải","translation_vi":"Vừa xem bản đồ vừa đi bộ nên tôi vấp phải một hòn đá nhỏ và bị ngã."},{"mondai":4,"q":22,"prompt":"その会にはぜひ出席したいのですが、(　　)ほかに予定が入ってるんです。","options":["せっかく","うっかり","あいにく","わざわざ"],"answer":3,"word_explain":"あいにく (生憎): không may, tiếc thay","translation_vi":"Tôi rất muốn tham dự buổi gặp mặt đó, nhưng tiếc thay lại có lịch hẹn khác mất rồi."},{"mondai":5,"q":23,"prompt":"荷物の重さは<u>およそ</u>5キロでした。","options":["ぜんぶで","ぴったり","だいたい","それぞれ"],"answer":3,"word_explain":"およそ = だいたい: khoảng chừng, đại khái","translation_vi":"Trọng lượng của hành lý khoảng 5 kg."},{"mondai":5,"q":24,"prompt":"もう少し具体的な<u>プラン</u>を教えてほしい。","options":["理由","情報","特徴","計画"],"answer":4,"word_explain":"プラン = 計画 (けいかく): kế hoạch","translation_vi":"Tôi muốn bạn cho biết kế hoạch cụ thể hơn một chút."},{"mondai":5,"q":25,"prompt":"市の経済状況は<u>依然として</u>厳しいらしい。","options":["相変わらず","思ったとおり","実際には","これまでより"],"answer":1,"word_explain":"依然として (いぜんとして) = 相変わらず (あいかわらず): vẫn như trước, không thay đổi","translation_vi":"Tình hình kinh tế của thành phố nghe nói vẫn khó khăn như trước."},{"mondai":5,"q":26,"prompt":"あのときは本当に<u>必死だった</u>。","options":["危なかった","一生懸命だった","緊張した","恐ろしかった"],"answer":2,"word_explain":"必死だった (ひっしだった) = 一生懸命だった: đã cố gắng hết sức, liều mạng","translation_vi":"Lúc đó tôi thực sự đã cố gắng hết sức mình."},{"mondai":5,"q":27,"prompt":"山の<u>ふもと</u>にきれいな湖があります。","options":["山の向こう","山の上のほう","山の中間あたり","山の下のほう"],"answer":4,"word_explain":"ふもと (麓) = 山の下のほう: chân núi","translation_vi":"Ở dưới chân núi có một hồ nước rất đẹp."},{"mondai":6,"q":28,"prompt":"補足","options":["スープの味が薄かったので、塩を<u>補足</u>しました。","資料には概要しか書かれていないので、少し説明を<u>補足</u>します。","新入社員の仕事を<u>補足</u>するのが私の役割です。","暗い部屋だったので、明るい色の家具を<u>補足</u>しました。"],"answer":2,"word_explain":"補足 (ほそく): bổ sung (thêm thông tin, lời giải thích cho phần còn thiếu)","translation_vi":"Vì trong tài liệu chỉ ghi tóm tắt nên tôi sẽ giải thích bổ sung thêm một chút."},{"mondai":6,"q":29,"prompt":"あわただしい","options":["最近、寒かったり暑かったり気温の変化が<u>あわただしい</u>ので、風をひく人が多い。","森さんは<u>あわただしい</u>人で、よく忘れ物をしたり、乗る電車を間違えたりする。","この町の発展は<u>あわただしく</u>、数年前とは様子がずいぶん変わりました。","山下さんは午前の会議が終わると、昼ご飯も食べずに<u>あわただしく</u>出かけていった。"],"answer":4,"word_explain":"あわただしい (慌ただしい): hối hả, vội vã, tất bật (dùng cho hành động/không khí vội vàng)","translation_vi":"Anh/chị Yamashita sau khi kết thúc cuộc họp buổi sáng đã vội vã ra ngoài mà không kịp ăn cả bữa trưa."},{"mondai":6,"q":30,"prompt":"かすか","options":["財布の中に<u>かすかな</u>お金があったので、バスで帰った。","船に乗って1時間たつと、遠くに島が<u>かすかに</u>見えてきた。","今日は天気がいいので、<u>かすかな</u>時間で洗濯物が乾きそうだ。","私と田中さんは同じ年だが、私のほうが誕生日が<u>かすかに</u>早い。"],"answer":2,"word_explain":"かすか (微か): mơ hồ, mờ nhạt, thoáng qua (cảm nhận yếu ớt qua giác quan như nhìn, nghe, ngửi)","translation_vi":"Sau khi lên tàu được 1 tiếng, ở phía xa hòn đảo bắt đầu hiện ra mờ mờ."},{"mondai":6,"q":31,"prompt":"催促","options":["３０度を超える暑い日には、水分を十分とるように学校でも注意を<u>催促</u>している。","異文化交流の<u>催促</u>のために、ボランティア団体が毎月イベントを開いている。","家賃を払うのをすっかり忘れていたら、<u>催促</u>の電話がかかってきた。","どこからか、おいしそうなにおいがしてきて、食欲が<u>催促</u>された。"],"answer":3,"word_explain":"催促 (さいそく): thúc giục, hối thúc (làm việc gì đó như trả tiền, nộp bài, trả lời)","translation_vi":"Vì quên bẵng mất việc đóng tiền nhà nên tôi đã nhận được cuộc gọi thúc giục."},{"mondai":6,"q":32,"prompt":"ものたりない","options":["少しうまくなってきたので、初心者向けのクラスだと<u>ものたりなく</u>なってきた。","クラスメートが転校することになり、みんな<u>ものたりなく</u>思っています。","日本に来たばかりで、いろいろ<u>ものたりない</u>でしょうが、すぐに慣れますよ。","楽しみにしていたパーティーなのに、中止なんて本当に<u>ものたりない</u>。"],"answer":1,"word_explain":"ものたりない (物足りない): cảm thấy chưa đủ, chưa thỏa mãn (không đáp ứng đủ trình độ hoặc kỳ vọng)","translation_vi":"Vì đã khá hơn một chút rồi nên lớp học dành cho người mới bắt đầu trở nên không còn đủ thỏa mãn nữa."}]},{"id":"2013_07","displayName":"07/2013","sourceFile":"Đề N2 7-2013.pdf","questions":[{"mondai":1,"q":1,"prompt":"新聞を読めば、<u>世の中</u>の動きを知ることができる。","options":["よのなか","せのなか","ようのなか","せいのなか"],"answer":1,"word_explain":"世の中 (よのなか): thế gian, xã hội, cuộc đời","translation_vi":"Nếu đọc báo, có thể biết được những chuyển động của xã hội."},{"mondai":1,"q":2,"prompt":"新入生をサークルに<u>勧誘</u>した。","options":["かんゆ","かんげい","かんゆう","かんげ"],"answer":3,"word_explain":"勧誘 (かんゆう): mời gọi, rủ rê, vận động tham gia","translation_vi":"Tôi đã mời gọi sinh viên mới vào câu lạc bộ."},{"mondai":1,"q":3,"prompt":"当日必要な資料などについても<u>改めて</u>ご連絡します。","options":["たしかめて","あらためて","まとめて","ふくめて"],"answer":2,"word_explain":"改めて (あらためて): một lần nữa, vào dịp khác, lại","translation_vi":"Về những tài liệu cần thiết vào hôm đó, chúng tôi cũng sẽ liên lạc lại sau."},{"mondai":1,"q":4,"prompt":"海外市場に進出するために販売部門を<u>拡充</u>した。","options":["こうじゅ","かくじゅ","こうじゅう","かくじゅう"],"answer":4,"word_explain":"拡充 (かくじゅう): mở rộng và tăng cường","translation_vi":"Để tiến vào thị trường nước ngoài, công ty đã mở rộng và tăng cường bộ phận bán hàng."},{"mondai":1,"q":5,"prompt":"教師は生徒の<u>模範</u>となるような行動をとるべきだ。","options":["もうほん","もうはん","もほん","もはん"],"answer":4,"word_explain":"模範 (もはん): tấm gương, mẫu mực","translation_vi":"Giáo viên nên có những hành động làm tấm gương cho học sinh."},{"mondai":2,"q":6,"prompt":"食費をこれ以上<u>けずる</u>ことはできない。","options":["縮る","減る","略る","削る"],"answer":4,"word_explain":"削る (けずる): cắt giảm, gọt, bào","translation_vi":"Không thể cắt giảm tiền ăn hơn nữa."},{"mondai":2,"q":7,"prompt":"今学期の<u>こうぎ</u>は来週までです。","options":["構義","講議","講義","構議"],"answer":3,"word_explain":"講義 (こうぎ): bài giảng, giờ giảng","translation_vi":"Các buổi giảng của học kỳ này sẽ kết thúc vào tuần sau."},{"mondai":2,"q":8,"prompt":"いつのまにか看板が<u>かたむいて</u>いた。","options":["傾いて","頃いて","倒いて","到いて"],"answer":1,"word_explain":"傾く (かたむく): nghiêng, ngả","translation_vi":"Biển hiệu đã bị nghiêng đi từ lúc nào không hay."},{"mondai":2,"q":9,"prompt":"自分に与えられた役割をしっかり<u>はたす</u>つもりだ。","options":["果たす","務たす","担たす","任たす"],"answer":1,"word_explain":"果たす (はたす): hoàn thành, thực hiện trọn vẹn (vai trò, nhiệm vụ)","translation_vi":"Tôi dự định sẽ hoàn thành thật tốt vai trò được giao cho mình."},{"mondai":2,"q":10,"prompt":"今度は田中さんも<u>しょうたい</u>するつもりです。","options":["招待","招介","紹介","紹待"],"answer":1,"word_explain":"招待 (しょうたい): mời, chiêu đãi","translation_vi":"Lần tới tôi cũng định sẽ mời cả anh Tanaka."},{"mondai":3,"q":11,"prompt":"初めて出た大会で（　　）決勝まで進むことができた。","options":["前","副","次","準"],"answer":4,"word_explain":"準決勝 (じゅんけっしょう): vòng bán kết","translation_vi":"Trong giải đấu lần đầu tiên tham dự, tôi đã có thể tiến vào đến vòng bán kết."},{"mondai":3,"q":12,"prompt":"このレストランは、いつも親子（　　）の客で込んでいる。","options":["添え","連れ","伴い","付き"],"answer":2,"word_explain":"親子連れ (おやこづれ): cha mẹ đi cùng con cái, gia đình có cả bố mẹ và con","translation_vi":"Nhà hàng này lúc nào cũng đông khách là các gia đình cha mẹ đi cùng con cái."},{"mondai":3,"q":13,"prompt":"日当たりが悪いので、この部屋は昼でも（　　）暗い。","options":["浅","軽","薄","弱"],"answer":3,"word_explain":"薄暗い (うすぐらい): mờ tối, hơi tối, tranh tối tranh sáng","translation_vi":"Vì ít ánh nắng chiếu vào nên căn phòng này ngay cả ban ngày cũng hơi tối."},{"mondai":3,"q":14,"prompt":"子供が風邪（　　）なので、今日は学校を休ませることにした。","options":["気味","具合","寄り","向き"],"answer":1,"word_explain":"風邪気味 (かぜぎみ): hơi cảm, có triệu chứng cảm cúm","translation_vi":"Vì con hơi có dấu hiệu bị cảm nên hôm nay tôi quyết định cho cháu nghỉ học."},{"mondai":3,"q":15,"prompt":"食器（　　）は、この箱に詰めてください。","options":["型","種","属","類"],"answer":4,"word_explain":"食器類 (しょっきるい): các loại bát đĩa, đồ dùng ăn uống","translation_vi":"Các loại bát đĩa xin hãy đóng vào chiếc hộp này."},{"mondai":4,"q":16,"prompt":"駅前を歩いていたら、テレビのリポーターに突然（　　）、インタビューを受けた。","options":["聞き取られて","呼び止められて","問い合わせられて","見分けられて"],"answer":2,"word_explain":"呼び止める (よびとめる): gọi giật lại, gọi dừng lại","translation_vi":"Khi đang đi bộ trước nhà ga, tôi bất ngờ bị phóng viên truyền hình gọi dừng lại và phỏng vấn."},{"mondai":4,"q":17,"prompt":"明日のハイキングは午前１０時集合、午後４時（　　）の予定です。","options":["解散","解放","退出","退場"],"answer":1,"word_explain":"解散 (かいさん): giải tán, tan (buổi tập trung, sự kiện)","translation_vi":"Buổi đi bộ đường dài ngày mai dự kiến tập trung lúc 10 giờ sáng và giải tán lúc 4 giờ chiều."},{"mondai":4,"q":18,"prompt":"司会をしてくれる人がいると、話し合いが（　　）進む。","options":["シンプルに","スムーズに","ソフトに","クリアに"],"answer":2,"word_explain":"スムーズに: một cách suôn sẻ, trôi chảy","translation_vi":"Khi có người làm chủ trì, cuộc thảo luận sẽ diễn ra suôn sẻ."},{"mondai":4,"q":19,"prompt":"転校する日はクラスのみんなと分かれるのが（　　）、涙が止まらなかった。","options":["にくくて","つらくて","痛ましくて","重苦しくて"],"answer":2,"word_explain":"つらい: đau khổ, buồn bã, khó chịu","translation_vi":"Vào ngày chuyển trường, việc phải chia tay mọi người trong lớp thật đau buồn khiến nước mắt tôi không ngừng rơi."},{"mondai":4,"q":20,"prompt":"自分のやったことがきちんと評価されると、仕事への（　　）も高まる。","options":["活気","根気","意図","意欲"],"answer":4,"word_explain":"意欲 (いよく): động lực, ý chí, sự hăng hái muốn làm","translation_vi":"Khi những việc mình làm được đánh giá đúng mực, động lực đối với công việc cũng tăng lên."},{"mondai":4,"q":21,"prompt":"試験が近くなってきたので、アルバイトはやめて、勉強に（　　）することにした。","options":["特定","統一","専念","注目"],"answer":3,"word_explain":"専念 (せんねん): chuyên tâm, tập trung toàn lực vào","translation_vi":"Vì kỳ thi đang đến gần nên tôi quyết định nghỉ việc làm thêm để chuyên tâm vào việc học."},{"mondai":4,"q":22,"prompt":"卒業パーティーには、ちゃんとした（　　）で行ったほうがいいのかな。","options":["様子","容姿","外見","格好"],"answer":4,"word_explain":"格好 (かっこう): trang phục, ăn mặc, dáng vẻ bên ngoài","translation_vi":"Đến tiệc tốt nghiệp thì nên ăn mặc chỉnh tề một chút phải không nhỉ."},{"mondai":5,"q":23,"prompt":"できるだけ早く仕事を<u>済ます</u>ようにします。","options":["覚える","終える","始める","教える"],"answer":2,"word_explain":"済ます (すます) = 終える (おえる): làm xong, hoàn thành","translation_vi":"Tôi sẽ cố gắng hoàn thành công việc sớm nhất có thể."},{"mondai":5,"q":24,"prompt":"昨日のあの人の態度は<u>あいまいだった</u>。","options":["ていねいだった","はっきりしなかった","りっぱだった","なさけなかった"],"answer":2,"word_explain":"あいまいだ = はっきりしない: mơ hồ, mập mờ, không rõ ràng","translation_vi":"Thái độ của người đó hôm qua thật mập mờ không rõ ràng."},{"mondai":5,"q":25,"prompt":"昨日、学校で<u>思いがけない</u>出来事があった。","options":["おもしろい","悲しい","意外な","ふしぎな"],"answer":3,"word_explain":"思いがけない (おもいがけない) = 意外な (いがいな): bất ngờ, ngoài dự đoán","translation_vi":"Hôm qua ở trường đã có một chuyện bất ngờ xảy ra."},{"mondai":5,"q":26,"prompt":"彼は大学を卒業した後、<u>みずから</u>会社を立ち上げる。","options":["自分で","すぐに","仲間と","しばらくして"],"answer":1,"word_explain":"みずから (自ら) = 自分で: tự mình, đích thân","translation_vi":"Sau khi tốt nghiệp đại học, anh ấy tự mình thành lập công ty."},{"mondai":5,"q":27,"prompt":"もう全員<u>そろいました</u>か。","options":["集まりました","訪ねました","出発しました","案内しました"],"answer":1,"word_explain":"そろう (揃う) = 集まる (あつまる): tập hợp đầy đủ, có mặt đủ","translation_vi":"Mọi người đã có mặt đầy đủ cả chưa?"},{"mondai":6,"q":28,"prompt":"掲示","options":["山田氏は有名な科学者で、いくつもの本に研究論文を<u>掲示</u>している。","テレビでよく<u>掲示</u>されている洗剤が安くなっていたので、試しに買ってみた。","最近は名刺に自分の写真を<u>掲示</u>しているビジネスマンも多い。","マンションの入り口に、水道工事のお知らせが<u>掲示</u>されていた。"],"answer":4,"word_explain":"掲示 (けいじ): niêm yết, dán thông báo công khai nơi công cộng (bảng tin, lối vào...)","translation_vi":"Ở lối vào khu chung cư có dán thông báo về việc thi công đường ống nước."},{"mondai":6,"q":29,"prompt":"快い","options":["要らないパソコンでしたら、<u>快く</u>もらっていきます。","遠慮しないでいつでも<u>快く</u>遊びに来てください。","急な仕事だったが、彼が<u>快く</u>引き受けてくれて助かった。","親友の森さんには、どんな悩みも<u>快く</u>打ち明けられる。"],"answer":3,"word_explain":"快い (こころよい): vui vẻ, sẵn lòng (đồng ý hoặc nhận lời nhờ vả của người khác)","translation_vi":"Tuy là công việc gấp nhưng anh ấy đã vui vẻ nhận lời giúp nên tôi rất biết ơn."},{"mondai":6,"q":30,"prompt":"分野","options":["保証の<u>分野</u>を超えた修理に関しては、費用がかかります。","明日は朝から冷え込んで、山に近い<u>分野</u>では雪になるそうだ。","セミナーには心理学や言語学の<u>分野</u>から多数の専門家が参加した。","小説のこの<u>分野</u>には筆者の実際の体験が書かれている。"],"answer":3,"word_explain":"分野 (ぶんや): lĩnh vực, chuyên ngành (học thuật, công việc, nghệ thuật...)","translation_vi":"Nhiều chuyên gia từ các lĩnh vực như tâm lý học và ngôn ngữ học đã tham gia hội thảo."},{"mondai":6,"q":31,"prompt":"生き生き","options":["私は体が<u>生き生き</u>しているうちに、あちこち旅行をしたいと思う。","子供が熱を出したが、薬を飲ませたらだんだん<u>生き生き</u>してきた。","彼は、好きなサッカーをしているときが一番<u>生き生き</u>している。","記憶が<u>生き生き</u>しているので、今なら間違えずに答えることができる。"],"answer":3,"word_explain":"生き生き (いきいき): sống động, tràn đầy sức sống, tươi tắn, hăng hái","translation_vi":"Anh ấy trông tràn đầy sức sống nhất là khi đang chơi môn bóng đá mình yêu thích."},{"mondai":6,"q":32,"prompt":"隔てる","options":["この二つの問題は<u>隔てて</u>考えるべきだ。","大きな川が二つの市を<u>隔てている</u>。","５分ほど休憩を<u>隔てて</u>、１１時から再開します。","試験のときは、隣の人と<u>隔てて</u>座ってください。"],"answer":2,"word_explain":"隔てる (へだてる): ngăn cách, chia cắt (khoảng cách không gian, địa lý hoặc ranh giới)","translation_vi":"Một con sông lớn đang ngăn cách hai thành phố."}]},{"id":"2012_12","displayName":"12/2012","sourceFile":"Đề N2 12-2012.pdf","questions":[{"mondai":1,"q":1,"prompt":"田中さんの話は<u>抽象的</u>で分かりにくかった。","options":["ちゅうしょうてき","ちゅうぞうてき","ゆうしょうてき","ゆうぞうてき"],"answer":1,"word_explain":"抽象的 (ちゅうしょうてき): trừu tượng","translation_vi":"Câu chuyện của anh Tanaka rất trừu tượng nên khó hiểu."},{"mondai":1,"q":2,"prompt":"その本は、明日までに必ず<u>返却</u>してください。","options":["へんきょく","へんきゃ","へんきゃく","へんきょ"],"answer":3,"word_explain":"返却 (へんきゃく): trả lại, hoàn trả","translation_vi":"Cuốn sách đó nhất định hãy trả lại trước ngày mai."},{"mondai":1,"q":3,"prompt":"<u>針</u>が見つからなくて困った。","options":["ねじ","はり","くぎ","かぎ"],"answer":2,"word_explain":"針 (はり): cái kim","translation_vi":"Tôi gặp rắc rối vì không tìm thấy cây kim."},{"mondai":1,"q":4,"prompt":"山田さんはいつもここから夕日を<u>撮影</u>している。","options":["さつえい","さいけい","さつけい","さいえい"],"answer":1,"word_explain":"撮影 (さつえい): chụp ảnh, quay phim","translation_vi":"Anh Yamada lúc nào cũng chụp ảnh hoàng hôn từ đây."},{"mondai":1,"q":5,"prompt":"ガラスの<u>破片</u>が落ちているから、気をつけてください。","options":["ひがた","はがた","ひへん","はへん"],"answer":4,"word_explain":"破片 (はへん): mảnh vỡ","translation_vi":"Có mảnh vỡ thủy tinh rơi trên sàn nên xin hãy cẩn thận."},{"mondai":2,"q":6,"prompt":"夏になると、この島には多くの観光客が<u>おとずれる</u>。","options":["往れる","伺れる","参れる","訪れる"],"answer":4,"word_explain":"訪れる (おとずれる): ghé thăm, viếng thăm","translation_vi":"Hễ đến mùa hè, có rất nhiều khách du lịch ghé thăm hòn đảo này."},{"mondai":2,"q":7,"prompt":"今年はたくさんの野菜が<u>しゅうかく</u>できたそうだ。","options":["集穫","集得","収穫","収得"],"answer":3,"word_explain":"収穫 (しゅうかく): thu hoạch","translation_vi":"Nghe nói năm nay đã thu hoạch được rất nhiều rau củ."},{"mondai":2,"q":8,"prompt":"餌をあげたとたん、その犬がすごい<u>いきおい</u>で食べ始めたのでびっくりした。","options":["乱い","勢い","荒い","暴い"],"answer":2,"word_explain":"勢い (いきおい): khí thế, đà, sự hăng hái","translation_vi":"Ngay khi vừa cho ăn, con chó đó bắt đầu ăn một cách hăng hái đến mức tôi giật mình."},{"mondai":2,"q":9,"prompt":"<u>そしき</u>が大きくなると、運営も大変になる。","options":["祖識","組識","組織","祖織"],"answer":3,"word_explain":"組織 (そしき): tổ chức","translation_vi":"Khi tổ chức lớn mạnh lên thì việc vận hành cũng trở nên vất vả."},{"mondai":2,"q":10,"prompt":"町の<u>いたるところ</u>に花が植えられている。","options":["至るところ","及るところ","満るところ","総るところ"],"answer":1,"word_explain":"至るところ (いたるところ): khắp mọi nơi","translation_vi":"Hoa được trồng ở khắp mọi nơi trong thị trấn."},{"mondai":3,"q":11,"prompt":"昨日、(　　)夜中に電話で起こされた。","options":["正","実","本","真"],"answer":4,"word_explain":"真夜中 (まよなか): nửa đêm, giữa đêm khuya","translation_vi":"Hôm qua, tôi bị đánh thức bởi một cuộc điện thoại vào giữa đêm khuya."},{"mondai":3,"q":12,"prompt":"昨日の選挙の投票(　　)は非常に高かった。","options":["割","率","値","比"],"answer":2,"word_explain":"投票率 (とうひょうりつ): tỷ lệ bỏ phiếu","translation_vi":"Tỷ lệ đi bỏ phiếu của cuộc bầu cử hôm qua rất cao."},{"mondai":3,"q":13,"prompt":"この本棚の本は、作家名のアルファベット(　　)に並んでいます。","options":["順","番","序","位"],"answer":1,"word_explain":"アルファベット順 (あるふぁべっとじゅん): theo thứ tự bảng chữ cái","translation_vi":"Sách trên kệ này được xếp theo thứ tự bảng chữ cái của tên tác giả."},{"mondai":3,"q":14,"prompt":"外からあまり見えないように、この窓は(　　)透明のガラスにしてある。","options":["弱","中","低","半"],"answer":4,"word_explain":"半透明 (はんとうめい): bán trong suốt, kính mờ","translation_vi":"Để bên ngoài khó nhìn vào được, cửa sổ này được làm bằng kính bán trong suốt (kính mờ)."},{"mondai":3,"q":15,"prompt":"海外のホテルでも日本(　　)のサービスを取り入れるところが増えているらしい。","options":["似","流","類","法"],"answer":2,"word_explain":"日本流 (にほんりゅう): kiểu Nhật, phong cách Nhật Bản","translation_vi":"Nghe nói ngay cả các khách sạn ở nước ngoài cũng ngày càng có nhiều nơi áp dụng dịch vụ theo phong cách Nhật Bản."},{"mondai":4,"q":16,"prompt":"栄養が(　　)ように、いろいろな食品を食べたほうがいい。","options":["はぶかれない","はずされない","かたよらない","かたむかない"],"answer":3,"word_explain":"偏らない (かたよらない): không bị thiên lệch, không mất cân bằng","translation_vi":"Để dinh dưỡng không bị mất cân đối, bạn nên ăn đa dạng các loại thực phẩm."},{"mondai":4,"q":17,"prompt":"ダムの建設は、計画通り(　　)進んでいる。","options":["さらさら","すらすら","着々と","続々と"],"answer":3,"word_explain":"着々と (ちゃくちゃくと): từng bước một cách vững chắc, thuận lợi theo kế hoạch","translation_vi":"Việc xây dựng đập thủy điện đang tiến triển từng bước vững chắc đúng theo kế hoạch."},{"mondai":4,"q":18,"prompt":"急いでいるのに、渋滞のせいで車が前に進まなくて(　　)した。","options":["いらいら","わくわく","すっきり","うっかり"],"answer":1,"word_explain":"いらいら: sốt ruột, bực bội, cáu kỉnh","translation_vi":"Đang vội mà vì tắc đường xe không nhúc nhích được nên tôi đã rất sốt ruột."},{"mondai":4,"q":19,"prompt":"兄は「残業が多い、給料が安い」と会社の(　　)ばかり言っている。","options":["ゆううつ","ぐち","苦情","非難"],"answer":2,"word_explain":"愚痴 (ぐち): lời than vãn, cằn nhằn","translation_vi":"Anh trai tôi suốt ngày chỉ toàn than vãn về công ty như \"tăng ca nhiều, lương thấp\"."},{"mondai":4,"q":20,"prompt":"あのドラマは、最後に主人公が恋人と再会する(　　)が感動的だった。","options":["要所","名所","場面","画面"],"answer":3,"word_explain":"場面 (ばめん): cảnh, phân cảnh (trong phim, kịch, truyện)","translation_vi":"Bộ phim truyền hình đó có cảnh cuối khi nhân vật chính tái ngộ với người yêu thật cảm động."},{"mondai":4,"q":21,"prompt":"Ａ社はこの１０年で、社員一万人の大企業に(　　)した。","options":["発達","展開","上昇","成長"],"answer":4,"word_explain":"成長 (せいちょう): phát triển, tăng trưởng (thành doanh nghiệp lớn)","translation_vi":"Công ty A trong 10 năm qua đã phát triển thành một doanh nghiệp lớn với 10.000 nhân viên."},{"mondai":4,"q":22,"prompt":"激しい運動をたまにするより、(　　)運動を毎日続ける方が体にはいいらしい。","options":["適度な","簡略な","好調な","対等な"],"answer":1,"word_explain":"適度な (てきどな): vừa phải, điều độ","translation_vi":"Nghe nói thay vì thỉnh thoảng vận động mạnh, việc duy trì vận động vừa phải mỗi ngày sẽ tốt cho cơ thể hơn."},{"mondai":5,"q":23,"prompt":"ちょっと<u>追加したい</u>データがあります。","options":["たしたい","なおしたい","のせたい","しらべたい"],"answer":1,"word_explain":"追加したい (ついかしたい) = たしたい (足したい): muốn bổ sung, thêm vào","translation_vi":"Có một chút dữ liệu tôi muốn bổ sung thêm."},{"mondai":5,"q":24,"prompt":"その国も今の時期は<u>そうとう</u>暑いだろう。","options":["たぶん","どうせ","やはり","かなり"],"answer":4,"word_explain":"そうとう (相当) = かなり: khá, tương đối, rất","translation_vi":"Đất nước đó vào thời điểm này chắc hẳn cũng khá nóng."},{"mondai":5,"q":25,"prompt":"少しの間、<u>じっとしていて</u>ください。","options":["見ないで","話さないで","使わないで","動かないで"],"answer":4,"word_explain":"じっとしていて = 動かないで: hãy đứng yên, đừng cử động","translation_vi":"Xin hãy giữ yên một chút (đừng cử động)."},{"mondai":5,"q":26,"prompt":"<u>あやまった</u>情報が流れてしまったようだ。","options":["古い","正しくない","秘密の","必要のない"],"answer":2,"word_explain":"あやまった (誤った) = 正しくない: sai lệch, không chính xác","translation_vi":"Có vẻ như thông tin sai lệch đã bị lan truyền ra ngoài rồi."},{"mondai":5,"q":27,"prompt":"ちょっと手が<u>かさかさしている</u>。","options":["汚れている","冷えている","しびれている","乾燥している"],"answer":4,"word_explain":"かさかさしている = 乾燥している: bị khô, khô ráp","translation_vi":"Tay tôi hơi bị khô ráp một chút."},{"mondai":6,"q":28,"prompt":"廃止","options":["両国が互いに主張を譲らず、会議は予定より早く<u>廃止</u>された。","時間も遅くなったので、区切りのいいところで作業を<u>廃止</u>した。","その制度は現状に合わなくなったので、先月で<u>廃止</u>された。","健康のために、たばこを<u>廃止</u>するよう家族に言われた。"],"answer":3,"word_explain":"廃止 (はいし): bãi bỏ, hủy bỏ (dùng cho chế độ, luật lệ, quy tắc, tuyến đường... đã tồn tại từ trước)","translation_vi":"Chế độ đó không còn phù hợp với tình hình hiện tại nữa nên đã bị bãi bỏ vào tháng trước."},{"mondai":6,"q":29,"prompt":"心強い","options":["姉は<u>心強く</u>て、どんなにつらいことがあっても涙を見せない。","初めてのプレゼンで不安だったが、先輩が一緒だったので<u>心強かった</u>。","アメリカに１０年住んでいたので、英語はわりと<u>心強い</u>です。","やると決めたことは最後まであきらめずにやる<u>心強い</u>人間になりたい。"],"answer":2,"word_explain":"心強い (こころづよい): yên tâm, vững lòng, cảm thấy có chỗ dựa tinh thần","translation_vi":"Lần đầu thuyết trình nên tôi rất lo lắng, nhưng vì có anh/chị khóa trên đi cùng nên tôi cảm thấy rất vững tâm."},{"mondai":6,"q":30,"prompt":"さっさと","options":["いつまでもテレビを見てないで、<u>さっさと</u>宿題をしなさい。","雷が鳴り出したと思ったら、<u>さっさと</u>雨が降り出した。","<u>さっさと</u>着くので、もう少しそこで待っていてください。","買ってまだ一週間なのに、<u>さっさと</u>壊れた。"],"answer":1,"word_explain":"さっさと: nhanh chóng, mau lẹ (dùng để thúc giục ai đó làm việc gì đó ngay, hoặc chỉ hành động dứt khoát không chần chừ)","translation_vi":"Đừng có xem tivi mãi thế, mau làm bài tập về nhà đi."},{"mondai":6,"q":31,"prompt":"ふさぐ","options":["種をまいたら、土で<u>ふさいで</u>水をやってください。","鍋をふたで<u>ふさぐ</u>と、中の肉に熱が通りやすくなります。","紙袋に穴があいていたので、セロテープで<u>ふさいだ</u>。","電子レンジで温めるときは、皿をラップで<u>ふさいで</u>ください。"],"answer":3,"word_explain":"ふさぐ (塞ぐ): bịt kín, lấp kín, chắn lại (lỗ thủng, khe hở, đường đi, miệng...)","translation_vi":"Túi giấy bị thủng một lỗ nên tôi đã dùng băng keo dán bịt lại."},{"mondai":6,"q":32,"prompt":"冷静","options":["不安定だったわが国の経済状態が、ようやく<u>冷静</u>になってきた。","トラブルが発生したときでも、森さんは慌てずに<u>冷静</u>に対応していた。","熱が下がるまで、<u>冷静</u>にしていたほうがいい。","台風で波が高かった海も、今日はすっかり<u>冷静</u>になった。"],"answer":2,"word_explain":"冷静 (れいせい): bình tĩnh, điềm tĩnh (chỉ thái độ, tâm trạng không hoảng loạn trước tình huống)","translation_vi":"Ngay cả khi sự cố xảy ra, anh Mori cũng không hề hoảng hốt mà xử lý một cách rất bình tĩnh."}]},{"id":"2012_07","displayName":"07/2012","sourceFile":"Đề N2 7-2012.pdf","questions":[{"mondai":1,"q":1,"prompt":"これは水をきれいにする<u>装置</u>です。","options":["しょち","しょうち","そち","そうち"],"answer":4,"word_explain":"装置 (そうち): thiết bị, máy móc","translation_vi":"Đây là thiết bị làm sạch nước."},{"mondai":1,"q":2,"prompt":"この店の客は女性が８０％を<u>占める</u>。","options":["しめる","つめる","せめる","うめる"],"answer":1,"word_explain":"占める (しめる): chiếm (tỷ lệ, vị trí)","translation_vi":"Khách của cửa hàng này nữ giới chiếm 80%."},{"mondai":1,"q":3,"prompt":"間違って、大事なメールを<u>削除</u>してしまった。","options":["しょうじ","しょうじょ","さくじ","さくじょ"],"answer":4,"word_explain":"削除 (さくじょ): xóa bỏ, cắt bỏ","translation_vi":"Tôi đã lỡ xóa nhầm email quan trọng mất rồi."},{"mondai":1,"q":4,"prompt":"今回の国際会議では人口問題が議論の<u>焦点</u>になった。","options":["しょうてん","しゅうてん","じょうてん","じゅうてん"],"answer":1,"word_explain":"焦点 (しょうてん): tiêu điểm, trọng tâm","translation_vi":"Trong hội nghị quốc tế lần này, vấn đề dân số đã trở thành trọng tâm thảo luận."},{"mondai":1,"q":5,"prompt":"最近は、「就職活動」を<u>略して</u>「就活」と言うことがある。","options":["やくして","かくして","りゃくして","きゃくして"],"answer":3,"word_explain":"略す (りゃくす): viết tắt, nói tắt, lược bỏ","translation_vi":"Gần đây, người ta hay nói tắt \"就職活動\" (hoạt động tìm việc) thành \"就活\"."},{"mondai":2,"q":6,"prompt":"先生の一言が、私をこの研究に<u>みちびいて</u>くれた。","options":["招いて","導いて","誘いて","伴いて"],"answer":2,"word_explain":"導いて (みちびいて): dẫn dắt, hướng dẫn","translation_vi":"Một lời nói của thầy đã dẫn dắt tôi đến với nghiên cứu này."},{"mondai":2,"q":7,"prompt":"こわれやすいので、丁寧に<u>あつかって</u>ください。","options":["拠って","吸って","扱って","処って"],"answer":3,"word_explain":"扱って (あつかって): xử lý, cầm nắm, đối xử","translation_vi":"Vì dễ vỡ nên xin hãy cầm nắm cẩn thận."},{"mondai":2,"q":8,"prompt":"ゼミには<u>せっきょくてき</u>に参加してほしい。","options":["責局的","積局的","責極的","積極的"],"answer":4,"word_explain":"積極的 (せっきょくてき): tích cực, chủ động","translation_vi":"Tôi muốn các bạn tham gia buổi seminar một cách tích cực."},{"mondai":2,"q":9,"prompt":"最初のうちは<u>ていこう</u>を感じていたが、いつの間にか慣れてしまった。","options":["底抗","抵抗","底坑","抵坑"],"answer":2,"word_explain":"抵抗 (ていこう): sự phản kháng, sự kháng cự, cảm giác ngần ngại","translation_vi":"Lúc đầu tôi cảm thấy hơi gượng gạo (ngần ngại), nhưng chẳng biết từ lúc nào đã quen mất rồi."},{"mondai":2,"q":10,"prompt":"昨日から<u>かた</u>が痛いんです。","options":["腰","腹","背","肩"],"answer":4,"word_explain":"肩 (かた): vai","translation_vi":"Từ hôm qua vai tôi bị đau."},{"mondai":3,"q":11,"prompt":"その事件の犯人は、ビジネスマン(　　)の男だったらしい。","options":["状","式","風","流"],"answer":3,"word_explain":"ビジネスマン風 (ビジネスマンふう): trông giống doanh nhân, vẻ ngoài như nhân viên văn phòng","translation_vi":"Nghe nói hung thủ của vụ án đó là một người đàn ông trông giống nhân viên văn phòng."},{"mondai":3,"q":12,"prompt":"今はまだ(　　)採用だが、いずれ本採用になるはずだ。","options":["副","短","仮","半"],"answer":3,"word_explain":"仮採用 (かりさいよう): tuyển dụng tạm thời, thử việc","translation_vi":"Bây giờ vẫn chỉ là tuyển dụng tạm thời (thử việc), nhưng rồi cũng sẽ được tuyển chính thức thôi."},{"mondai":3,"q":13,"prompt":"ここは国際(　　)の豊かな都市として知られている。","options":["質","香","気","色"],"answer":4,"word_explain":"国際色 (こくさいしょく): sắc thái quốc tế, tính chất quốc tế","translation_vi":"Nơi đây được biết đến như một thành phố mang đậm sắc thái quốc tế."},{"mondai":3,"q":14,"prompt":"レポートの課題で、(　　)外国の教育事情を調べて、違いを表にまとめた。","options":["数","多","総","諸"],"answer":4,"word_explain":"諸外国 (しょがいこく): các nước ngoài","translation_vi":"Trong bài tập báo cáo, tôi đã tìm hiểu tình hình giáo dục ở các nước ngoài và tổng hợp sự khác biệt vào bảng."},{"mondai":3,"q":15,"prompt":"Ａ社は、(　　)価格の商品で市場の拡大を狙っている。","options":["低","安","少","下"],"answer":1,"word_explain":"低価格 (ていかかく): giá thấp, giá rẻ","translation_vi":"Công ty A đang nhắm đến việc mở rộng thị trường bằng các sản phẩm giá rẻ."},{"mondai":4,"q":16,"prompt":"子どもが遊んだあとは、おもちゃが(　　)いる。","options":["飛び越えて","散らかって","見わたして","落ち込んで"],"answer":2,"word_explain":"散らかって (ちらかって): bừa bộn, vương vãi","translation_vi":"Sau khi trẻ con chơi xong, đồ chơi vương vãi khắp nơi."},{"mondai":4,"q":17,"prompt":"田中選手はサッカーの日本代表に選ばれたが、けがを理由に代表を(　　)した。","options":["避難","逃避","退場","辞退"],"answer":4,"word_explain":"辞退 (じたい): từ chối, rút lui (không nhận lời mời/đề cử)","translation_vi":"Cầu thủ Tanaka đã được chọn vào đội tuyển bóng đá quốc gia Nhật Bản, nhưng anh ấy đã xin rút khỏi đội tuyển với lý do chấn thương."},{"mondai":4,"q":18,"prompt":"今回の調査で(　　)結果は、今後のサービス向上に生かしていきたい。","options":["にぎった","はさんだ","得た","込めた"],"answer":3,"word_explain":"得た (えた): thu được, đạt được","translation_vi":"Kết quả thu được từ cuộc khảo sát lần này, chúng tôi muốn vận dụng vào việc nâng cao chất lượng dịch vụ trong tương lai."},{"mondai":4,"q":19,"prompt":"大きな荷物を(　　)いたので、携帯電話に出られなかった。","options":["だいて","いだいて","かかえて","だきしめて"],"answer":3,"word_explain":"かかえて (抱えて): ôm, bê, mang (bằng hai tay/cánh tay)","translation_vi":"Vì đang ôm hành lý cồng kềnh nên tôi không thể nghe điện thoại di động được."},{"mondai":4,"q":20,"prompt":"法律が(　　)されて、申請方法が以前とは大幅に変わりました。","options":["改正","改造","転換","変換"],"answer":1,"word_explain":"改正 (かいせい): sửa đổi, cải chính (luật, quy định)","translation_vi":"Luật đã được sửa đổi, nên cách thức đăng ký đã thay đổi đáng kể so với trước đây."},{"mondai":4,"q":21,"prompt":"読書に(　　)なっていて、友達との約束の時間を忘れていた。","options":["好調に","夢中に","頑固に","強引に"],"answer":2,"word_explain":"夢中に (むちゅうに): say mê, mải mê","translation_vi":"Tôi mải mê đọc sách đến mức quên cả giờ hẹn với bạn."},{"mondai":4,"q":22,"prompt":"目が覚めたが、まだ時間が早かったので、しばらくベッドで(　　)していた。","options":["ごろごろ","ぶらぶら","ゆらゆら","うろうろ"],"answer":1,"word_explain":"ごろごろ: nằm ườn ra, lăn lóc (thư giãn trên giường/sàn)","translation_vi":"Tôi đã tỉnh giấc nhưng vì vẫn còn sớm nên đã nằm ườn trên giường thêm một lúc."},{"mondai":5,"q":23,"prompt":"この問題は、<u>ただちに</u>部長に報告しなければならない。","options":["あとで","すぐに","くわしく","きちんと"],"answer":2,"word_explain":"ただちに (直ちに) = すぐに: ngay lập tức","translation_vi":"Vấn đề này phải báo cáo ngay lập tức cho trưởng phòng."},{"mondai":5,"q":24,"prompt":"隣の部屋から<u>奇妙な</u>音が聞こえる。","options":["変な","にぎやかな","大きな","嫌な"],"answer":1,"word_explain":"奇妙な (きみょうな) = 変な: kỳ lạ, kỳ quặc","translation_vi":"Từ phòng bên cạnh nghe thấy âm thanh kỳ lạ."},{"mondai":5,"q":25,"prompt":"明日までに、この資料を<u>仕上げて</u>おいてください。","options":["出して","直して","完成させて","移動させて"],"answer":3,"word_explain":"仕上げて (しあげて) = 完成させて: hoàn thành, làm xong","translation_vi":"Hãy hoàn thành xong tài liệu này trước ngày mai nhé."},{"mondai":5,"q":26,"prompt":"<u>日中</u>はアルバイトに行っています。","options":["平日","休日","夜間","昼間"],"answer":4,"word_explain":"日中 (にっちゅう) = 昼間: ban ngày","translation_vi":"Ban ngày tôi đi làm thêm."},{"mondai":5,"q":27,"prompt":"このタオルとシャツは<u>しめっている</u>ね。","options":["まだきれいになっていない","まだ乾いていない","もうきれいになっている","もう乾いている"],"answer":2,"word_explain":"しめっている (湿っている) = まだ乾いていない: bị ẩm, vẫn chưa khô","translation_vi":"Cái khăn và chiếc áo sơ mi này vẫn còn ẩm nhỉ."},{"mondai":6,"q":28,"prompt":"とぼしい","options":["このスープは塩味が<u>とぼしい</u>。","この国は天然資源に<u>とぼしい</u>。","音量が<u>とぼしく</u>て聞こえにくい。","この商品には<u>とぼしい</u>需要しかない。"],"answer":2,"word_explain":"とぼしい (乏しい): thiếu thốn, nghèo nàn (thường dùng với 資源に乏しい, 経験に乏しい, 知識に乏しい...)","translation_vi":"Đất nước này nghèo nàn (thiếu thốn) về tài nguyên thiên nhiên."},{"mondai":6,"q":29,"prompt":"矛盾","options":["山田さんはみんなで決めたことに<u>矛盾</u>している。","北半球と南半球では夏と冬が<u>矛盾</u>している。","あの人の言ったことは、この前の話と<u>矛盾</u>している。","穏やかな彼女がロックを聞くなんて、<u>矛盾</u>している。"],"answer":3,"word_explain":"矛盾 (むじゅん): mâu thuẫn, trái ngược nhau (dùng với lời nói, hành động, sự thật: AとBが矛盾している)","translation_vi":"Điều mà người đó nói mâu thuẫn với câu chuyện lần trước."},{"mondai":6,"q":30,"prompt":"問い合わせる","options":["ご質問はこの電話番号にお<u>問い合わせ</u>ください。","街で知らない人に道を<u>問い合わせ</u>られた。","週末は映画を見に行かないかと、妹に<u>問い合わせ</u>た。","言葉の正確な意味は辞書に<u>問い合わせ</u>よう。"],"answer":1,"word_explain":"問い合わせる (といあわせる): hỏi thăm, liên hệ để hỏi thông tin (tới cơ quan, cửa hàng, bộ phận phụ trách)","translation_vi":"Nếu có thắc mắc, xin vui lòng liên hệ hỏi qua số điện thoại này."},{"mondai":6,"q":31,"prompt":"交代","options":["時計の電池が切れてしまったので、新しいのに<u>交代</u>した。","少し疲れたので、友達に運転を<u>交代</u>してもらった。","用事ができて、待ち合わせの時間を１時から３時に<u>交代</u>してもらった。","今年の４月に前の会社をやめて、今の会社に<u>交代</u>した。"],"answer":2,"word_explain":"交代 (こうたい): thay phiên, đổi ca, đổi người đảm nhận (lái xe, trực nhật, cầu thủ...)","translation_vi":"Vì hơi mệt nên tôi đã nhờ bạn đổi lái xe giúp."},{"mondai":6,"q":32,"prompt":"合同","options":["複数の大学が<u>合同</u>でスポーツ大会を行った。","みんなの<u>合同</u>で、イベントの準備は着々と進んでいる。","三つの市の<u>合同</u>で、県で一番大きな市が誕生した。","寮ではみんなが<u>合同</u>でシャワールームを使っている。"],"answer":1,"word_explain":"合同 (ごうどう): hợp tác chung, liên kết nhiều bên cùng làm gì đó (合同で行う, 合同説明会...)","translation_vi":"Nhiều trường đại học đã phối hợp cùng nhau tổ chức đại hội thể thao."}]},{"id":"2011_12","displayName":"12/2011","sourceFile":"Đề N2 12-2011.pdf","questions":[{"mondai":1,"q":1,"prompt":"この大学は<u>地元</u>の学生が多い。","options":["ちげん","ちもと","じけん","じもと"],"answer":4,"word_explain":"地元 (じもと): địa phương, bản địa","translation_vi":"Trường đại học này có nhiều sinh viên địa phương."},{"mondai":1,"q":2,"prompt":"両国経済的に<u>密接</u>な関係にある。","options":["ひっせつ","みつせつ","みっせつ","ひつせつ"],"answer":3,"word_explain":"密接 (みっせつ): mật thiết, gắn bó chặt chẽ","translation_vi":"Hai nước có mối quan hệ mật thiết về mặt kinh tế."},{"mondai":1,"q":3,"prompt":"野菜にはビタミンが<u>豊富</u>に含まれている。","options":["のうふ","ほうふう","ほうふ","のうふう"],"answer":3,"word_explain":"豊富 (ほうふ): phong phú, dồi dào","translation_vi":"Trong rau xanh có chứa hàm lượng vitamin phong phú."},{"mondai":1,"q":4,"prompt":"実力が足りないところは、努力で<u>補いたい</u>。","options":["やしないたい","すくいたい","かばいたい","おぎないたい"],"answer":4,"word_explain":"補う (おぎなう): bù đắp, bổ sung","translation_vi":"Những chỗ thực lực còn thiếu thì tôi muốn bù đắp bằng nỗ lực."},{"mondai":1,"q":5,"prompt":"みなさんの<u>率直</u>な考えを聞かせてください。","options":["そつじき","りつじき","そっちょく","りっちょく"],"answer":3,"word_explain":"率直 (そっちょく): thẳng thắn, bộc trực","translation_vi":"Xin hãy cho tôi nghe suy nghĩ thẳng thắn của mọi người."},{"mondai":2,"q":6,"prompt":"彼女の生き方は多くの人に感動を<u>あたえた</u>。","options":["与えた","授えた","贈えた","供えた"],"answer":1,"word_explain":"与えた (あたえた): đã mang lại, đem lại, trao cho","translation_vi":"Cách sống của cô ấy đã mang lại niềm xúc động cho nhiều người."},{"mondai":2,"q":7,"prompt":"この公園は市が<u>かんり</u>している。","options":["管利","管理","官利","官理"],"answer":2,"word_explain":"管理 (かんり): quản lý","translation_vi":"Công viên này do thành phố quản lý."},{"mondai":2,"q":8,"prompt":"この国は<u>ふくし</u>が充実している。","options":["福施","副施","副詞","福祉"],"answer":4,"word_explain":"福祉 (ふくし): phúc lợi","translation_vi":"Đất nước này có chế độ phúc lợi rất đầy đủ."},{"mondai":2,"q":9,"prompt":"テレビで外国語教育についての<u>とうろん</u>が行われた。","options":["討諭","討論","投論","投諭"],"answer":2,"word_explain":"討論 (とうろん): thảo luận, tranh luận","translation_vi":"Trên truyền hình đã diễn ra cuộc thảo luận về giáo dục ngoại ngữ."},{"mondai":2,"q":10,"prompt":"この二つの会社は、同じ企業グループに<u>ぞくして</u>いる。","options":["続して","属して","族して","束して"],"answer":2,"word_explain":"属して (ぞくして): trực thuộc, thuộc về","translation_vi":"Hai công ty này trực thuộc cùng một tập đoàn doanh nghiệp."},{"mondai":3,"q":11,"prompt":"あの小説家は数々の文学(　　)を獲得している。","options":["賞","位","号","段"],"answer":1,"word_explain":"文学賞 (ぶんがくしょう): giải thưởng văn học","translation_vi":"Nhà văn đó đã giành được rất nhiều giải thưởng văn học."},{"mondai":3,"q":12,"prompt":"今回は(　　)条件がいくつも重なってしまって、大変だった。","options":["苦","悪","損","劣"],"answer":2,"word_explain":"悪条件 (あくじょうけん): điều kiện bất lợi, điều kiện xấu","translation_vi":"Lần này nhiều điều kiện bất lợi chồng chất lên nhau nên thật sự rất vất vả."},{"mondai":3,"q":13,"prompt":"クリーム(　　)になるまで、バターと砂糖をよく混ぜてください。","options":["流","似","態","状"],"answer":4,"word_explain":"クリーム状 (くりーむじょう): dạng kem, sệt như kem","translation_vi":"Hãy trộn đều bơ và đường cho đến khi thành dạng kem."},{"mondai":3,"q":14,"prompt":"父は一日(　　)にジョギングをしている。","options":["かけ","あき","ぬけ","おき"],"answer":4,"word_explain":"一日おき (いちにちおき): cách một ngày (hai ngày một lần)","translation_vi":"Bố tôi chạy bộ cách ngày (cứ cách một ngày lại chạy một lần)."},{"mondai":3,"q":15,"prompt":"(　　)シーズンは、あの選手の活躍が楽しみだ。","options":["明","迎","来","越"],"answer":3,"word_explain":"来シーズン (らいしーずん): mùa giải tới","translation_vi":"Tôi rất mong chờ màn thể hiện của tuyển thủ đó vào mùa giải tới."},{"mondai":4,"q":16,"prompt":"ストレスを(　　)するために、何かしていますか。","options":["解消","削除","減量","停止"],"answer":1,"word_explain":"解消 (かいしょう): giải tỏa, xóa bỏ (căng thẳng)","translation_vi":"Bạn có làm gì để giải tỏa căng thẳng không?"},{"mondai":4,"q":17,"prompt":"生活習慣を(　　)してから、ほとんど病気をしなくなりました。","options":["訂正","変換","整備","改善"],"answer":4,"word_explain":"改善 (かいぜん): cải thiện","translation_vi":"Kể từ khi cải thiện thói quen sinh hoạt, tôi hầu như không còn bị ốm nữa."},{"mondai":4,"q":18,"prompt":"申し込みの締め切りは明日に(　　)いる。","options":["迫って","限って","寄って","至って"],"answer":1,"word_explain":"迫る (せまる): cận kề, đến gần (hạn chót)","translation_vi":"Hạn chót đăng ký đã cận kề vào ngày mai rồi."},{"mondai":4,"q":19,"prompt":"日曜だから込んでいるかと思ったけど、(　　)すいているね。","options":["たいして","どうりで","わりと","よけい"],"answer":3,"word_explain":"わりと: tương đối, khá (so với dự đoán)","translation_vi":"Tôi cứ tưởng là Chủ nhật nên sẽ đông, nhưng hóa ra lại khá vắng nhỉ."},{"mondai":4,"q":20,"prompt":"組織のトップに立つ人間は、広い(　　)を持つことが必要だ。","options":["視界","視野","視線","視察"],"answer":2,"word_explain":"視野 (しや): tầm nhìn (trong tư duy, quản lý)","translation_vi":"Người đứng đầu một tổ chức cần phải có tầm nhìn rộng."},{"mondai":4,"q":21,"prompt":"シャワーを浴びたら、体も気分も(　　)した。","options":["さらさら","きらきら","さっぱり","きっぱり"],"answer":3,"word_explain":"さっぱり: sảng khoái, nhẹ nhõm, mát mẻ","translation_vi":"Sau khi tắm vòi sen xong, cả cơ thể lẫn tinh thần đều thấy sảng khoái."},{"mondai":4,"q":22,"prompt":"この携帯電話には、いろいろな(　　)がついている。","options":["効用","才能","機能","効力"],"answer":3,"word_explain":"機能 (きのう): chức năng, tính năng","translation_vi":"Chiếc điện thoại di động này được trang bị rất nhiều tính năng."},{"mondai":5,"q":23,"prompt":"真夏の屋外でずっと仕事をしたら、<u>くたくた</u>になった。","options":["ひどく疲れた","のどがかわいた","お腹が空いた","汗をかいた"],"answer":1,"word_explain":"くたくた = ひどく疲れた: mệt rã rời, kiệt sức","translation_vi":"Làm việc ngoài trời giữa mùa hè suốt một thời gian dài nên tôi đã mệt rã rời."},{"mondai":5,"q":24,"prompt":"この１０年で、この鳥の自然環境<u>わずかに</u>変化した。","options":["急に","ゆっくり","大きく","少し"],"answer":4,"word_explain":"わずかに = 少し: một chút, hơi, ít","translation_vi":"Trong 10 năm qua, môi trường tự nhiên của loài chim này đã thay đổi một chút."},{"mondai":5,"q":25,"prompt":"田中さんは子供のころから<u>優秀</u>だったらしい。","options":["あたまがよかった","体が丈夫だった","話がおもしろかった","人気があった"],"answer":1,"word_explain":"優秀 (ゆうしゅう) = あたまがよかった: ưu tú, xuất sắc, thông minh","translation_vi":"Nghe nói anh Tanaka đã thông minh xuất sắc từ hồi còn nhỏ."},{"mondai":5,"q":26,"prompt":"鈴木さんは恥ずかしそうに<u>うつむいて</u>いた。","options":["横を向いて","下を向いて","頭をかいて","鼻をかいて"],"answer":2,"word_explain":"うつむく = 下を向く: cúi mặt xuống, cúi đầu xuống","translation_vi":"Anh Suzuki trông có vẻ ngượng ngùng và cúi mặt xuống."},{"mondai":5,"q":27,"prompt":"学生時代の友人が<u>いきなり</u>訪ねてきた。","options":["つぎつぎ","やっと","とつぜん","いちどに"],"answer":3,"word_explain":"いきなり = とつぜん (突然): đột nhiên, bất ngờ","translation_vi":"Một người bạn thời sinh viên đột nhiên đến thăm tôi."},{"mondai":6,"q":28,"prompt":"世間","options":["この映画は動物の<u>世間</u>を描いた作品だ。","あの政党は、よりよい<u>世間</u>の実現を目指している。","田中さんは数学の<u>世間</u>では有名だ。","その事件は<u>世間</u>の注目を集めた。"],"answer":4,"word_explain":"世間 (せけん): thế gian, xã hội, dư luận, công chúng (thường dùng với nghĩa người đời/dư luận như 世間の注目)","translation_vi":"Vụ việc đó đã thu hút sự chú ý của dư luận."},{"mondai":6,"q":29,"prompt":"違反","options":["ルールに<u>違反</u>して退場になった選手が３人もいる。","子供のころは皆、親に<u>違反</u>する時期があるものだ。","彼の意見に<u>違反</u>する人はあまりいなかった。","見た目がよくないが、予想に<u>違反</u>しておいしかった。"],"answer":1,"word_explain":"違反 (いはん): vi phạm (quy tắc, luật lệ, hợp đồng...)","translation_vi":"Có tới 3 cầu thủ bị truất quyền thi đấu vì vi phạm luật."},{"mondai":6,"q":30,"prompt":"質素","options":["この文章は<u>質素</u>で、とてもわかりやすい。","もう少し値段の<u>質素</u>なツアーはありませんか。","経験は<u>質素</u>でも、やる気がある人を採用したい。","無駄なものを買わずに、<u>質素</u>な生活を送っている。"],"answer":4,"word_explain":"質素 (しっそ): giản dị, đạm bạc, tiết kiệm (dùng cho lối sống, ăn mặc, bữa ăn...)","translation_vi":"Không mua những thứ lãng phí, tôi đang sống một cuộc sống giản dị."},{"mondai":6,"q":31,"prompt":"とっくに","options":["この辺には、<u>とっくに</u>大きいお寺があった。","山田さんなら<u>とっくに</u>帰りましたよ。","あの時のことを今ごろ謝っても<u>とっくに</u>遅いよ。","さっきから電話が<u>とっくに</u>鳴りっぱなしだ。"],"answer":2,"word_explain":"とっくに: từ lâu rồi, đã sớm (dùng với sự việc đã hoàn thành từ trước đó khá lâu)","translation_vi":"Nếu là anh Yamada thì anh ấy đã về từ lâu rồi đấy."},{"mondai":6,"q":32,"prompt":"受け入れる","options":["チケットのお申し込みは電話で<u>受け入れて</u>います。","入口でパンフレットを<u>受け入れて</u>から席にお座りください。","私の大学では、毎年大勢の留学生を<u>受け入れて</u>います。","最新の技術を<u>受け入れた</u>製品について説明してもらいました。"],"answer":3,"word_explain":"受け入れる (うけいれる): tiếp nhận, chấp nhận (người như du học sinh, hoặc ý kiến, yêu cầu...)","translation_vi":"Ở trường đại học của tôi, hằng năm tiếp nhận rất nhiều du học sinh."}]},{"id":"2011_07","displayName":"07/2011","sourceFile":"Đề N2 7-2011.pdf","questions":[{"mondai":1,"q":1,"prompt":"ずっと好調だったのに、最後の試合で<u>敗れて</u>しまった。","options":["たおれて","やぶれて","みだれて","つぶれて"],"answer":2,"word_explain":"敗れる (やぶれる): thất bại, thua","translation_vi":"Suốt thời gian qua phong độ vẫn luôn tốt, vậy mà lại thua ở trận đấu cuối cùng."},{"mondai":1,"q":2,"prompt":"この仕事には高い語学力が<u>要求</u>される。","options":["ようきゅ","よっきゅう","ようきゅう","よっきゅ"],"answer":3,"word_explain":"要求 (ようきゅう): yêu cầu, đòi hỏi","translation_vi":"Công việc này đòi hỏi năng lực ngoại ngữ cao."},{"mondai":1,"q":3,"prompt":"友達の合格をみんなで<u>祝った</u>。","options":["いわった","いのった","うらなった","ねがった"],"answer":1,"word_explain":"祝う (いわう): chúc mừng, ăn mừng","translation_vi":"Mọi người cùng nhau chúc mừng việc bạn mình thi đỗ."},{"mondai":1,"q":4,"prompt":"寒かったら、エアコンの温度を<u>調節</u>してください。","options":["ちょうさい","ちょうせい","ちょうさつ","ちょうせつ"],"answer":4,"word_explain":"調節 (ちょうせつ): điều chỉnh, điều tiết","translation_vi":"Nếu lạnh thì hãy điều chỉnh nhiệt độ điều hòa nhé."},{"mondai":1,"q":5,"prompt":"この書類を<u>至急</u>コピーしてきてください。","options":["しっきゅう","ちっきゅう","しきゅう","ちきゅう"],"answer":3,"word_explain":"至急 (しきゅう): khẩn cấp, ngay lập tức, gấp","translation_vi":"Hãy đi photocopy gấp tài liệu này mang về đây."},{"mondai":2,"q":6,"prompt":"ハトは平和の<u>しょうちょう</u>だと言われている。","options":["像徴","象微","象徴","像微"],"answer":3,"word_explain":"象徴 (しょうちょう): biểu tượng, tượng trưng","translation_vi":"Chim bồ câu được cho là biểu tượng của hòa bình."},{"mondai":2,"q":7,"prompt":"退院しても、しばらくの間、<u>はげしい</u>運動はしないでください。","options":["険しい","激しい","暴しい","極しい"],"answer":2,"word_explain":"激しい (はげしい): dữ dội, mạnh, quyết liệt","translation_vi":"Dù đã xuất viện, trong một thời gian xin đừng vận động mạnh."},{"mondai":2,"q":8,"prompt":"携帯電話に友達の電話番号を<u>とうろく</u>した。","options":["登緑","登録","答録","答緑"],"answer":2,"word_explain":"登録 (とうろく): đăng ký, lưu vào danh bạ","translation_vi":"Tôi đã lưu (đăng ký) số điện thoại của bạn vào điện thoại di động."},{"mondai":2,"q":9,"prompt":"岡田さんを話題の映画に<u>さそった</u>。","options":["招った","勧った","請った","誘った"],"answer":4,"word_explain":"誘う (さそう): rủ, mời","translation_vi":"Tôi đã rủ anh/chị Okada đi xem bộ phim đang nổi tiếng."},{"mondai":2,"q":10,"prompt":"待ち合わせの時間を６時に<u>へんこう</u>してもらった。","options":["変改","変更","変換","変替"],"answer":2,"word_explain":"変更 (へんこう): thay đổi","translation_vi":"Tôi đã nhờ đổi thời gian hẹn thành 6 giờ."},{"mondai":3,"q":11,"prompt":"彼は医学(　　)ではかなり知られた存在だ。","options":["界","帯","域","区"],"answer":1,"word_explain":"医学界 (いがくかい): giới y học","translation_vi":"Anh ấy là một nhân vật khá nổi tiếng trong giới y học."},{"mondai":3,"q":12,"prompt":"決勝戦で負けて、(　　)優勝に終わった。","options":["後","準","次","副"],"answer":2,"word_explain":"準優勝 (じゅんゆうしょう): giải nhì, á quân","translation_vi":"Thua ở trận chung kết và dừng lại ở vị trí á quân."},{"mondai":3,"q":13,"prompt":"(　　)段階では詳細は決まっていないらしい。","options":["現","直","近","当"],"answer":1,"word_explain":"現段階 (げんだんかい): giai đoạn hiện tại","translation_vi":"Nghe nói ở giai đoạn hiện tại thì chi tiết vẫn chưa được quyết định."},{"mondai":3,"q":14,"prompt":"今回の大臣の訪問は(　　)公式に行われた。","options":["不","未","無","非"],"answer":4,"word_explain":"非公式 (ひこうしき): không chính thức","translation_vi":"Chuyến thăm lần này của bộ trưởng đã được thực hiện một cách không chính thức."},{"mondai":3,"q":15,"prompt":"わが社の今年の(　　)売上は、昨年を上回った。","options":["集","総","合","満"],"answer":2,"word_explain":"総売上 (そううりあげ): tổng doanh thu","translation_vi":"Tổng doanh thu năm nay của công ty chúng ta đã vượt qua năm ngoái."},{"mondai":4,"q":16,"prompt":"さまざまなデータを(　　)した結果、事故の原因が明らかになった。","options":["視察","検査","発明","分析"],"answer":4,"word_explain":"分析 (ぶんせき): phân tích","translation_vi":"Kết quả sau khi phân tích các dữ liệu khác nhau, nguyên nhân vụ tai nạn đã được làm sáng tỏ."},{"mondai":4,"q":17,"prompt":"街を(　　)していたら、山本さんに会った。","options":["ぐらぐら","がらがら","ばらばら","ぶらぶら"],"answer":4,"word_explain":"ぶらぶら: đi dạo thong dong, lang thang","translation_vi":"Đang đi dạo lang thang trên phố thì tôi gặp anh/chị Yamamoto."},{"mondai":4,"q":18,"prompt":"祭りの日は町が(　　)にあふれている。","options":["活気","活発","活躍","活動"],"answer":1,"word_explain":"活気 (かっき): không khí sôi động, tràn đầy sức sống","translation_vi":"Vào ngày lễ hội, cả thị trấn tràn ngập không khí sôi động."},{"mondai":4,"q":19,"prompt":"コピー機に紙が(　　)、出てこない。","options":["もぐって","つまって","しずんで","うまって"],"answer":2,"word_explain":"詰まる (つまる): bị kẹt, bị tắc","translation_vi":"Giấy bị kẹt trong máy photocopy nên không ra được."},{"mondai":4,"q":20,"prompt":"この小説は今の時代を(　　)した作品だ。","options":["反映","放映","引用","採用"],"answer":1,"word_explain":"反映 (はんえい): phản ánh","translation_vi":"Cuốn tiểu thuyết này là tác phẩm phản ánh thời đại hiện nay."},{"mondai":4,"q":21,"prompt":"田中さんは長い間(　　)窓の外を見ていた。","options":["ぼんやり","ふんわり","うっすら","しっとり"],"answer":1,"word_explain":"ぼんやり: lơ đãng, thẫn thờ, mơ màng","translation_vi":"Anh/chị Tanaka đã nhìn ra ngoài cửa sổ một cách thẫn thờ trong suốt một thời gian dài."},{"mondai":4,"q":22,"prompt":"経済だけでなく、法律にも詳しいのが彼の(　　)だ。","options":["深み","強み","高み","重み"],"answer":2,"word_explain":"強み (つよみ): điểm mạnh, thế mạnh","translation_vi":"Am hiểu không chỉ kinh tế mà cả luật pháp chính là thế mạnh của anh ấy."},{"mondai":5,"q":23,"prompt":"この<u>ブーム</u>は長くは続かないだろう。","options":["効果","状態","流行","緊張"],"answer":3,"word_explain":"ブーム = 流行 (りゅうこう): trào lưu, sự thịnh hành","translation_vi":"Trào lưu này chắc sẽ không kéo dài lâu đâu."},{"mondai":5,"q":24,"prompt":"この作業は<u>慎重に</u>やってください。","options":["急いで","絶対忘れずに","静かに","十分注意して"],"answer":4,"word_explain":"慎重に (しんちょうに) = 十分注意して: một cách thận trọng, hết sức chú ý","translation_vi":"Hãy làm công việc này một cách thật thận trọng."},{"mondai":5,"q":25,"prompt":"シャツが<u>ちぢんで</u>しまった。","options":["小さくなって","古くなって","汚れて","破れて"],"answer":1,"word_explain":"縮む (ちぢむ) = 小さくなる: co lại, nhỏ lại","translation_vi":"Chiếc áo sơ mi bị co lại mất rồi."},{"mondai":5,"q":26,"prompt":"宿題のレポートは<u>ほぼ</u>終わった。","options":["すべて","すぐに","だいたい","やっと"],"answer":3,"word_explain":"ほぼ = だいたい: gần như, đại khái, hầu như","translation_vi":"Báo cáo bài tập về nhà gần như đã xong rồi."},{"mondai":5,"q":27,"prompt":"来週は天気が<u>回復する</u>そうだ。","options":["あまり変わらない","変わりやすい","よくなる","悪くなる"],"answer":3,"word_explain":"回復する (かいふくする) = よくなる: hồi phục, trở nên tốt hơn","translation_vi":"Nghe nói tuần tới thời tiết sẽ tốt lên."},{"mondai":6,"q":28,"prompt":"方針","options":["台風の<u>方針</u>がそれたので、特に被害は出なかった。","私の今年の<u>方針</u>は漢字を６００字覚えることだ。","この料理を作る<u>方針</u>を教えてください。","教育に関する政府の<u>方針</u>が大きく変わった。"],"answer":4,"word_explain":"方針 (ほうしん): phương châm, đường lối (của tổ chức, chính phủ, kế hoạch lớn)","translation_vi":"Phương châm (đường lối) của chính phủ liên quan đến giáo dục đã thay đổi lớn."},{"mondai":6,"q":29,"prompt":"範囲","options":["この町は川によって二つの<u>範囲</u>に分かれている。","この会社は新しい<u>範囲</u>に進出した。","明日は広い<u>範囲</u>で強い雨が降るでしょう。","家から駅までの<u>範囲</u>は２キロぐらいだ。"],"answer":3,"word_explain":"範囲 (はんい): phạm vi, khu vực (ví dụ: 広い範囲で雨が降る - mưa trên diện rộng)","translation_vi":"Ngày mai có lẽ sẽ có mưa lớn trên diện rộng."},{"mondai":6,"q":30,"prompt":"せめて","options":["その店のセーターは<u>せめて</u>１万円はするだろう。","今からタクシーに乗っても、<u>せめて</u>１０時には着けない。","京都に行くなら、<u>せめて</u>１泊はしたい。","先週のテストは自信がなかったが、<u>せめて</u>５０点は取れた。"],"answer":3,"word_explain":"せめて: ít nhất là, chí ít (dùng khi bày tỏ mong muốn mức tối thiểu)","translation_vi":"Nếu đi Kyoto thì ít nhất tôi cũng muốn ở lại một đêm."},{"mondai":6,"q":31,"prompt":"利益","options":["ジョギングは健康の<u>利益</u>になる。","この値段で売ったら、店の<u>利益</u>はほとんどない。","かぜ薬を飲んだが、<u>利益</u>が感じられない。","バスの<u>利益</u>は、新幹線よりも料金が安いことだ。"],"answer":2,"word_explain":"利益 (りえき): lợi nhuận, tiền lãi (trong kinh doanh)","translation_vi":"Nếu bán với giá này thì cửa hàng hầu như không có lợi nhuận."},{"mondai":6,"q":32,"prompt":"かなう","options":["苦労が<u>かない</u>、彼は俳優として成功をおさめた。","天気予報が<u>かない</u>、今日は一日中快晴だった。","準備を重ねてきたイベントが無事<u>かなった</u>。","自分の店を持つという夢が、とうとう<u>かなった</u>。"],"answer":4,"word_explain":"かなう (叶う): thành hiện thực, trở thành sự thật (dùng với 夢, 願い, 希望...)","translation_vi":"Giấc mơ có cửa hàng riêng của mình cuối cùng đã thành hiện thực."}]},{"id":"2010_12","displayName":"12/2010","sourceFile":"N2 12-2010.pdf","questions":[{"mondai":1,"q":1,"prompt":"今回のマラソン大会は、過去最大の<u>規模</u>で行われた。","options":["きぼ","ぎぼ","きも","ぎも"],"answer":1,"word_explain":"規模 (きぼ): quy mô","translation_vi":"Giải marathon lần này đã được tổ chức với quy mô lớn nhất từ trước đến nay."},{"mondai":1,"q":2,"prompt":"異文化に<u>触れた</u>のがきっかけで、この仕事を始めた。","options":["ふれた","なれた","めぐまれた","あこがれた"],"answer":1,"word_explain":"触れる (ふれる): tiếp xúc, chạm vào","translation_vi":"Cơ duyên tiếp xúc với nền văn hóa khác đã khiến tôi bắt đầu công việc này."},{"mondai":1,"q":3,"prompt":"話し合いでは、少数意見も<u>尊重</u>しよう。","options":["けいちょう","けいじゅう","そんちょう","そんじゅう"],"answer":3,"word_explain":"尊重 (そんちょう): tôn trọng","translation_vi":"Trong cuộc thảo luận, hãy tôn trọng cả ý kiến của thiểu số."},{"mondai":1,"q":4,"prompt":"けがの<u>治療</u>に2か月かかった。","options":["じりょ","ちりょ","じりょう","ちりょう"],"answer":4,"word_explain":"治療 (ちりょう): điều trị, chữa trị","translation_vi":"Việc điều trị vết thương đã mất 2 tháng."},{"mondai":1,"q":5,"prompt":"花屋の<u>隣</u>に空き地があります。","options":["うら","となり","そば","むかい"],"answer":2,"word_explain":"隣 (となり): bên cạnh","translation_vi":"Bên cạnh tiệm hoa có một bãi đất trống."},{"mondai":2,"q":6,"prompt":"来月、スポーツ大会が<u>かいさい</u>される。","options":["開催","開幕","開演","開講"],"answer":1,"word_explain":"開催 (かいさい): tổ chức (sự kiện, đại hội)","translation_vi":"Tháng sau, đại hội thể thao sẽ được tổ chức."},{"mondai":2,"q":7,"prompt":"小林さんは<u>たより</u>になる人だ。","options":["依り","任り","頼り","援り"],"answer":3,"word_explain":"頼り (たより): chỗ dựa, đáng tin cậy (頼りになる: đáng tin cậy)","translation_vi":"Anh/Chị Kobayashi là người rất đáng tin cậy."},{"mondai":2,"q":8,"prompt":"最近忙しくて生活のリズムが<u>みだれて</u>いる。","options":["破れて","乱れて","荒れて","暴れて"],"answer":2,"word_explain":"乱れる (みだれる): bị xáo trộn, rối loạn","translation_vi":"Gần đây bận rộn nên nhịp sống sinh hoạt đang bị xáo trộn."},{"mondai":2,"q":9,"prompt":"東京駅までの<u>うんちん</u>はいくらですか。","options":["運貸","運費","運賃","運貨"],"answer":3,"word_explain":"運賃 (うんちん): tiền cước, giá vé (tàu, xe)","translation_vi":"Tiền vé đến ga Tokyo là bao nhiêu ạ?"},{"mondai":2,"q":10,"prompt":"近くの公園でドラマの<u>さつえい</u>が行われた。","options":["録映","撮映","録影","撮影"],"answer":4,"word_explain":"撮影 (さつえい): quay phim, chụp ảnh","translation_vi":"Buổi quay phim truyền hình đã được thực hiện ở công viên gần đây."},{"mondai":3,"q":11,"prompt":"昨日の試合は、私たちのチームが2(　　)1で勝った。","options":["反","比","差","対"],"answer":4,"word_explain":"2対1 (にたいいち): 2 đấu 1, tỷ số 2-1","translation_vi":"Trận đấu hôm qua, đội của chúng tôi đã thắng với tỷ số 2-1."},{"mondai":3,"q":12,"prompt":"1年前のテレビドラマが、来週から(　　)放送される。","options":["改","再","更","復"],"answer":2,"word_explain":"再放送 (さいほうそう): phát sóng lại","translation_vi":"Bộ phim truyền hình của 1 năm trước sẽ được phát sóng lại từ tuần sau."},{"mondai":3,"q":13,"prompt":"このレストランは予約(　　)です。","options":["則","法","制","系"],"answer":3,"word_explain":"予約制 (よやくせい): chế độ đặt chỗ trước","translation_vi":"Nhà hàng này áp dụng chế độ phải đặt bàn trước."},{"mondai":3,"q":14,"prompt":"この大学は就職(　　)が高い。","options":["率","割","度","倍"],"answer":1,"word_explain":"就職率 (しゅうしょくりつ): tỷ lệ có việc làm","translation_vi":"Trường đại học này có tỷ lệ sinh viên có việc làm cao."},{"mondai":3,"q":15,"prompt":"今は(　　)制度からの移行時期だ。","options":["先","旧","昔","元"],"answer":2,"word_explain":"旧制度 (きゅうせいど): chế độ cũ","translation_vi":"Hiện tại đang là giai đoạn chuyển tiếp từ chế độ cũ."},{"mondai":4,"q":16,"prompt":"あの町の人口は(　　)減少している。","options":["軽々と","順々に","徐々に","細々と"],"answer":3,"word_explain":"徐々に (じょじょに): dần dần, từ từ","translation_vi":"Dân số của thị trấn kia đang giảm dần."},{"mondai":4,"q":17,"prompt":"最近、物価が(　　)している。","options":["増加","上達","増大","上昇"],"answer":4,"word_explain":"上昇 (じょうしょう): tăng lên (giá cả, nhiệt độ, mức độ)","translation_vi":"Gần đây, vật giá đang tăng lên."},{"mondai":4,"q":18,"prompt":"多くの人が旅行する(　　)は、飛行機のチケットが高い。","options":["シリーズ","タイム","シーズン","チャンス"],"answer":3,"word_explain":"シーズン: mùa (mùa du lịch, mùa cao điểm)","translation_vi":"Vào mùa nhiều người đi du lịch thì vé máy bay đắt."},{"mondai":4,"q":19,"prompt":"私の上司はとても(　　)で、今まで怒ったのを見たことがない。","options":["優良","温暖","良性","温厚"],"answer":4,"word_explain":"温厚 (おんこう): ôn hòa, điềm đạm","translation_vi":"Cấp trên của tôi rất ôn hòa, từ trước đến nay tôi chưa từng thấy anh ấy nổi giận."},{"mondai":4,"q":20,"prompt":"この数カ月、新しいゲームが(　　)発売されている。","options":["相次いで","間もなく","ぐんぐん","すいすい"],"answer":1,"word_explain":"相次いで (あいついで): liên tiếp, nối tiếp nhau","translation_vi":"Trong vài tháng trở lại đây, các trò chơi mới liên tiếp được phát hành."},{"mondai":4,"q":21,"prompt":"池田さんはまじめすぎて、冗談が(　　)。","options":["当たらない","渡らない","構わない","通じない"],"answer":4,"word_explain":"通じる (つうじる): hiểu được, thông hiểu (冗談が通じない: không hiểu được chuyện đùa)","translation_vi":"Anh/Chị Ikeda nghiêm túc quá nên không hiểu được lời nói đùa."},{"mondai":4,"q":22,"prompt":"このホテルの宿泊料金には、朝食も(　　)いる。","options":["含まれて","納めれて","割り込まれて","詰め込まれて"],"answer":1,"word_explain":"含まれる (ふくまれる): bao gồm","translation_vi":"Giá phòng của khách sạn này đã bao gồm cả bữa sáng."},{"mondai":5,"q":23,"prompt":"あまり<u>勝手な</u>ことは言わないでください。","options":["わがままな","うるさい","消極的な","情けない"],"answer":1,"word_explain":"勝手な (かってな) = わがままな: ích kỷ, tùy tiện","translation_vi":"Xin đừng nói những điều ích kỷ/tùy tiện quá như vậy."},{"mondai":5,"q":24,"prompt":"あの人は<u>たびたび</u>夜遅くに電話をかけてくる。","options":["たまに","何度も","たいてい","突然"],"answer":2,"word_explain":"たびたび = 何度も: nhiều lần, thường xuyên","translation_vi":"Người đó thường xuyên gọi điện vào đêm muộn."},{"mondai":5,"q":25,"prompt":"この靴は<u>ぶかぶか</u>だ。","options":["とても重い","とても小さい","とても軽い","とても大きい"],"answer":4,"word_explain":"ぶかぶか = とても大きい: rộng thùng thình, quá to (giày, quần áo)","translation_vi":"Đôi giày này rộng thùng thình."},{"mondai":5,"q":26,"prompt":"同じ分野の専門家でも、立場によって<u>見解</u>が異なる。","options":["教え方","調べ方","考え方","決め方"],"answer":3,"word_explain":"見解 (けんかい) = 考え方: quan điểm, cách nhìn nhận","translation_vi":"Ngay cả các chuyên gia trong cùng một lĩnh vực, tùy theo lập trường mà quan điểm cũng khác nhau."},{"mondai":5,"q":27,"prompt":"先週、車を<u>レンタル</u>した。","options":["修理した","借りた","検査した","買った"],"answer":2,"word_explain":"レンタル = 借りた: thuê, mượn","translation_vi":"Tuần trước tôi đã thuê một chiếc ô tô."},{"mondai":6,"q":28,"prompt":"はずす","options":["歯医者で虫歯を<u>はずして</u>もらった。","腕時計を<u>はずして</u>、机の上に置いた。","家に入る前に、靴の汚れを<u>はずした</u>。","食事の後、テーブルから皿を<u>はずした</u>。"],"answer":2,"word_explain":"はずす (外す): tháo ra, cởi ra (đồng hồ, kính, nhẫn...); tránh, rời khỏi vị trí","translation_vi":"Tôi tháo đồng hồ đeo tay ra và đặt lên trên bàn."},{"mondai":6,"q":29,"prompt":"普及","options":["携帯電話は急速に<u>普及</u>してきている。","今、若者の間ではこんなうわさが<u>普及</u>している。","この病気は人から人へ<u>普及</u>する可能性がある。","あの大臣の発言は国際問題にまで<u>普及</u>した。"],"answer":1,"word_explain":"普及 (ふきゅう): phổ cập, phổ biến rộng rãi (sản phẩm, kỹ thuật, tư tưởng...)","translation_vi":"Điện thoại di động đang ngày càng được phổ biến một cách nhanh chóng."},{"mondai":6,"q":30,"prompt":"注目","options":["きれいな眺めに<u>注目</u>して、時間がたつのを忘れた。","寝不足で<u>注目</u>が足りないと、仕事でミスが多くなる。","来月の選挙の結果が<u>注目</u>されている。","この問題を別の<u>注目</u>から見てみよう。"],"answer":3,"word_explain":"注目 (ちゅうもく): chú mục, chú ý, quan tâm theo dõi (sự việc, kết quả, nhân vật...)","translation_vi":"Kết quả của cuộc bầu cử tháng sau đang rất được chú ý."},{"mondai":6,"q":31,"prompt":"ふさわしい","options":["中川さんの指摘は、いつも<u>ふさわしい</u>です。","彼は責任感が強く、この仕事のリーダーに<u>ふさわしい</u>。","私に<u>ふさわしい</u>サイズの帽子がやっと見つかった。","私、あの人とは性格が<u>ふさわしい</u>んです。"],"answer":2,"word_explain":"ふさわしい: xứng đáng, thích hợp, phù hợp (với vị trí, vai trò, hoàn cảnh...)","translation_vi":"Anh ấy có tinh thần trách nhiệm cao, rất xứng đáng làm trưởng nhóm của công việc này."},{"mondai":6,"q":32,"prompt":"保つ","options":["山田さんは、いつも約束の時間を<u>保つ</u>人です。","一人で全部食べないで、私の分も<u>保って</u>おいてください。","あとで捨てるので、ごみはそのまま<u>保って</u>おいていいですよ。","健康を<u>保つ</u>ためには、バランスのいい食事と運動が大切だ。"],"answer":4,"word_explain":"保つ (たもつ): duy trì, giữ gìn (sức khỏe, hòa bình, trạng thái...)","translation_vi":"Để duy trì sức khỏe thì chế độ ăn uống cân bằng và vận động là rất quan trọng."}]},{"id":"2010_07","displayName":"07/2010","sourceFile":"Đề N2 7-2010.pdf","questions":[{"mondai":1,"q":1,"prompt":"これからも様々な国との<u>相互</u>理解を深めていこうと思う。","options":["しょうご","しょうごう","そうご","そうごう"],"answer":3,"word_explain":"相互 (そうご): lẫn nhau, tương hỗ","translation_vi":"Từ nay về sau, tôi muốn tiếp tục làm sâu sắc thêm sự hiểu biết lẫn nhau với nhiều quốc gia khác nhau."},{"mondai":1,"q":2,"prompt":"この料理は<u>辛くて</u>食べられない。","options":["からくて","くさくて","にがくて","しぶくて"],"answer":1,"word_explain":"辛くて (からくて): cay (辛い: からい)","translation_vi":"Món ăn này cay quá nên không ăn được."},{"mondai":1,"q":3,"prompt":"晴れている日は、この山頂からすばらしい<u>景色</u>が見える。","options":["けいしき","けしき","けいいろ","けいろ"],"answer":2,"word_explain":"景色 (けしき): phong cảnh, cảnh sắc","translation_vi":"Vào những ngày trời nắng, từ đỉnh núi này có thể nhìn thấy phong cảnh tuyệt vời."},{"mondai":1,"q":4,"prompt":"このお金は、何かあったときに<u>備えて</u>残しておこう。","options":["ととのえて","たくわえて","かかえて","そなえて"],"answer":4,"word_explain":"備えて (そなえて): chuẩn bị sẵn, dự phòng (備える: そなえる)","translation_vi":"Số tiền này hãy để dành lại để phòng khi có chuyện gì xảy ra."},{"mondai":1,"q":5,"prompt":"今から、<u>防災</u>訓練を行います。","options":["ぼうえん","ぼうさい","ほうえん","ほうさい"],"answer":2,"word_explain":"防災 (ぼうさい): phòng chống thiên tai, phòng tai","translation_vi":"Bây giờ, chúng ta sẽ tiến hành diễn tập phòng chống thiên tai."},{"mondai":2,"q":6,"prompt":"彼はとても<u>れいぎ</u>正しいです。","options":["札義","札儀","礼義","礼儀"],"answer":4,"word_explain":"礼儀 (れいぎ): lễ nghi, phép lịch sự","translation_vi":"Anh ấy rất lễ phép, lịch sự."},{"mondai":2,"q":7,"prompt":"彼は苦労を重ねて、社長にまで<u>しゅっせ</u>した。","options":["出成","出世","昇成","昇世"],"answer":2,"word_explain":"出世 (しゅっせ): thành đạt, thăng tiến","translation_vi":"Anh ấy đã trải qua nhiều vất vả và thăng tiến lên đến chức giám đốc."},{"mondai":2,"q":8,"prompt":"この店は<u>でんとう</u>の味を守り続けている。","options":["伝授","伝承","伝統","伝達"],"answer":3,"word_explain":"伝統 (でんとう): truyền thống","translation_vi":"Cửa hàng này vẫn luôn giữ gìn hương vị truyền thống."},{"mondai":2,"q":9,"prompt":"そんなに<u>あせらなくても</u>大丈夫ですよ。","options":["焦らなくても","騒らなくても","競らなくても","暴らなくても"],"answer":1,"word_explain":"焦らなくても (あせらなくても): không cần phải vội vàng, hấp tấp (焦る: あせる)","translation_vi":"Không cần phải vội vàng, sốt ruột như vậy đâu."},{"mondai":2,"q":10,"prompt":"大学に入学してから、一人で<u>くらして</u>います。","options":["幕らして","募らして","暮らして","墓らして"],"answer":3,"word_explain":"暮らして (くらして): sinh sống (暮らす: くらす)","translation_vi":"Từ khi vào đại học, tôi sống một mình."},{"mondai":3,"q":11,"prompt":"今日の講演のテーマは、教育の(　　)問題についてです。","options":["諸","複","雑","類"],"answer":1,"word_explain":"諸問題 (しょもんだい): các vấn đề","translation_vi":"Chủ đề của buổi diễn thuyết hôm nay là về các vấn đề của giáo dục."},{"mondai":3,"q":12,"prompt":"駅前の商店(　　)で、買い物して帰ろう。","options":["帯","域","街","町"],"answer":3,"word_explain":"商店街 (しょうてんがい): khu phố mua sắm, khu thương mại","translation_vi":"Hãy mua sắm ở khu phố thương mại trước nhà ga rồi về nhé."},{"mondai":3,"q":13,"prompt":"夏休みに旅行に行きたいので、(　　)収入のアルバイトを探している。","options":["上","良","優","高"],"answer":4,"word_explain":"高収入 (こうしゅうにゅう): thu nhập cao","translation_vi":"Vì muốn đi du lịch vào kỳ nghỉ hè nên tôi đang tìm việc làm thêm có thu nhập cao."},{"mondai":3,"q":14,"prompt":"来週の会議には、社長と(　　)社長も出席する予定だ。","options":["準","副","補","助"],"answer":2,"word_explain":"副社長 (ふくしゃちょう): phó giám đốc","translation_vi":"Trong cuộc họp tuần tới, dự kiến cả giám đốc và phó giám đốc đều sẽ tham dự."},{"mondai":3,"q":15,"prompt":"疲れると、集中(　　)が落ちて仕事が進まなくなる。","options":["能","考","気","力"],"answer":4,"word_explain":"集中力 (しゅうちゅうりょく): khả năng tập trung, sự tập trung","translation_vi":"Khi mệt mỏi thì khả năng tập trung giảm sút và công việc không tiến triển được."},{"mondai":4,"q":16,"prompt":"今週は忙しかったから、週末は家で(　　)テレビを見ていた。","options":["のろのろ","のんびり","ぐるぐる","ぐっすり"],"answer":2,"word_explain":"のんびり: thong thả, thư thái, thoải mái","translation_vi":"Vì tuần này bận rộn nên cuối tuần tôi đã ở nhà thong thả xem tivi."},{"mondai":4,"q":17,"prompt":"マラソンでは周りの人にあわせようとしないで、(　　)で走るといい。","options":["テクニック","フレッシュ","アプローチ","マイペース"],"answer":4,"word_explain":"マイペース: theo nhịp độ của bản thân, không chạy theo người khác","translation_vi":"Trong chạy marathon, bạn không nên cố chạy theo những người xung quanh mà hãy chạy theo nhịp độ của riêng mình."},{"mondai":4,"q":18,"prompt":"あの店はサービスがいいと(　　)だ。","options":["評判","評価","診断","決断"],"answer":1,"word_explain":"評判 (ひょうばん): tiếng tăm, danh tiếng, dư luận đánh giá","translation_vi":"Cửa hàng đó nổi tiếng là có dịch vụ tốt."},{"mondai":4,"q":19,"prompt":"彼女とは久しぶりに会ったので、何時間話しても話が(　　)。","options":["枯れない","限らない","尽きない","衰えない"],"answer":3,"word_explain":"尽きない (つきない): không cạn, không dứt (話が尽きない: chuyện nói mãi không hết)","translation_vi":"Vì lâu rồi mới gặp lại cô ấy nên nói chuyện bao nhiêu tiếng đồng hồ cũng không hết chuyện."},{"mondai":4,"q":20,"prompt":"練習の成果が(　　)できれば、きっと優勝できるだろう。","options":["発揮","発生","発行","発明"],"answer":1,"word_explain":"発揮 (はっき): phát huy","translation_vi":"Nếu có thể phát huy được thành quả của việc luyện tập thì chắc chắn sẽ vô địch được."},{"mondai":4,"q":21,"prompt":"この表現は(　　)でわかりにくい。","options":["軟弱","質素","あいまい","ささやか"],"answer":3,"word_explain":"あいまい (曖昧): mơ hồ, mập mờ, không rõ ràng","translation_vi":"Cách diễn đạt này mơ hồ nên rất khó hiểu."},{"mondai":4,"q":22,"prompt":"この切符は、明日まで(　　)です。","options":["利点","権利","効用","有効"],"answer":4,"word_explain":"有効 (ゆうこう): có hiệu lực, còn giá trị sử dụng","translation_vi":"Chiếc vé này có hiệu lực đến ngày mai."},{"mondai":5,"q":23,"prompt":"<u>とりあえず</u>社長に電話で話しておいた。","options":["さっき","すぐに","一応","直接"],"answer":3,"word_explain":"とりあえず = 一応 (いちおう): trước mắt, tạm thời","translation_vi":"Trước mắt tôi đã gọi điện nói chuyện với giám đốc rồi."},{"mondai":5,"q":24,"prompt":"友人がバイクを安く<u>ゆずって</u>くれた。","options":["売って","貸して","預かって","直して"],"answer":1,"word_explain":"ゆずって (譲って) = 売って (うって): nhượng lại, bán lại","translation_vi":"Bạn tôi đã nhượng / bán lại chiếc xe máy với giá rẻ cho tôi."},{"mondai":5,"q":25,"prompt":"<u>雑談</u>をしているときにいいアイディアが浮かんだ。","options":["あいさつ","おしゃべり","説明","報告"],"answer":2,"word_explain":"雑談 (ざつだん) = おしゃべり: nói chuyện phiếm, tán gẫu","translation_vi":"Trong lúc đang tán gẫu thì một ý tưởng hay đã nảy ra."},{"mondai":5,"q":26,"prompt":"うちの犬はとても<u>かしこい</u>。","options":["頭がいい","足が速い","めずらしい","おとなしい"],"answer":1,"word_explain":"かしこい (賢い) = 頭がいい: thông minh, lanh lợi","translation_vi":"Con chó nhà tôi rất thông minh."},{"mondai":5,"q":27,"prompt":"彼の話はいつも<u>大げさ</u>だ。","options":["エネルギーがある","ユーモアがある","オープンだ","オーバーだ"],"answer":4,"word_explain":"大げさ (おおげさ) = オーバーだ: phóng đại, làm quá lên","translation_vi":"Câu chuyện của anh ấy lúc nào cũng phóng đại quá mức."},{"mondai":6,"q":28,"prompt":"取材","options":["学期末試験の範囲を友達に<u>取材</u>しました。","デパートに買い物に行く前に、営業時間を<u>取材</u>しておこう。","インターネットは、簡単に地図を<u>取材</u>できるので便利です。","あの選手の練習の様子を<u>取材</u>したときは、とても緊張しました。"],"answer":4,"word_explain":"取材 (しゅざい): lấy tin, phỏng vấn, thu thập tư liệu (dùng cho báo chí, truyền thông)","translation_vi":"Khi phỏng vấn / đưa tin về buổi tập luyện của vận động viên đó, tôi đã rất hồi hộp."},{"mondai":6,"q":29,"prompt":"きっかけ","options":["季節の<u>きっかけ</u>は風邪をひきやすい。","友人に写真をほめられたのが<u>きっかけ</u>で、本格的に勉強を始めた。","その意見に反対する<u>きっかけ</u>は、主観的すぎるからだ。","今回は時間がないので、次の<u>きっかけ</u>に訪れようと思う。"],"answer":2,"word_explain":"きっかけ: cơ duyên, động lực, nguyên cớ khởi đầu (thường dùng với ～がきっかけで)","translation_vi":"Nhờ được bạn khen ảnh đẹp mà tôi đã bắt đầu học một cách nghiêm túc."},{"mondai":6,"q":30,"prompt":"深刻","options":["彼は動物に対して<u>深刻</u>な愛情を持っている。","家族との時間を<u>深刻</u>に過ごしている。","彼は<u>深刻</u>な悩みをかかえているようだ。","テストが近いので、<u>深刻</u>に勉強した。"],"answer":3,"word_explain":"深刻 (しんこく): nghiêm trọng, sâu sắc (thường đi với 悩み, 問題, 状況...)","translation_vi":"Có vẻ như anh ấy đang mang trong lòng một nỗi phiền muộn nghiêm trọng."},{"mondai":6,"q":31,"prompt":"続出","options":["満員電車から乗客が<u>続出</u>してきた。","暑さのせいで気分が悪くなる人が<u>続出</u>した。","最近は、天気の悪い日が<u>続出</u>している。","薬で治ったと思っていた風邪が<u>続出</u>した。"],"answer":2,"word_explain":"続出 (ぞくしゅつ): xuất hiện liên tiếp, xảy ra dồn dập (người hoặc sự việc xuất hiện nối tiếp nhau)","translation_vi":"Do trời nóng nên liên tiếp có nhiều người bị khó chịu / mệt mỏi."},{"mondai":6,"q":32,"prompt":"外見","options":["人を<u>外見</u>で判断するのはよくないことだ。","窓の<u>外見</u>をペンキで白く塗った。","月の<u>外見</u>はでこぼこしている。","母は怒っている<u>外見</u>だった。"],"answer":1,"word_explain":"外見 (がいけん): vẻ bề ngoài, ngoại hình","translation_vi":"Đánh giá con người qua vẻ bề ngoài là điều không tốt."}]}];
